module.exports = [{"id":"0532","name":"kettlebell figure 8","nameZh":"壶铃 8字","equipment":"kettlebell","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0532-L4ay0PW.jpg","gifPath":"exercises/videos/0532-L4ay0PW.gif","instructionSteps":["双脚分开与肩同宽站立，一只手握住壶铃。","稍微弯曲膝盖，髋部向前转动，保持背部挺直。","将壶铃放在双腿之间，当壶铃到达双腿后部时交换双手。","当壶铃向前移动时，将其传递到两腿之间的另一只手。","继续以 8 字形动作将壶铃传递到双腿之间。","在整个练习过程中保持稳定的节奏并调动核心力量。","重复所需的重复次数。"]},{"id":"0533","name":"kettlebell front squat","nameZh":"壶铃前蹲","equipment":"kettlebell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0533-DB0n8AG.jpg","gifPath":"exercises/videos/0533-DB0n8AG.gif","instructionSteps":["站立，双脚分开与肩同宽，脚趾稍微向外。","双手将壶铃放在胸前，靠近身体。","收紧核心并保持挺胸，同时降低臀部和向后倾斜，就像坐在椅子上一样。","降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。","通过脚跟发力站起来，在顶部挤压臀部。","重复所需的重复次数。"]},{"id":"0534","name":"kettlebell goblet squat","nameZh":"壶铃高脚杯深蹲","equipment":"kettlebell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0534-ZA8b5hc.jpg","gifPath":"exercises/videos/0534-ZA8b5hc.gif","instructionSteps":["双脚分开与肩同宽站立，双手握住壶铃靠近胸部。","保持胸部挺直，核心收紧，弯曲膝盖和臀部，将身体降低至蹲姿。","继续降低，直到大腿与地面平行，或者尽可能低。","在底部停顿片刻，然后推动脚后跟回到起始位置。","重复所需的重复次数。"]},{"id":"0535","name":"kettlebell hang clean","nameZh":"壶铃悬垂翻举","equipment":"kettlebell","bodyPart":"upper legs","target":"hamstrings","imagePath":"exercises/images/0535-LHWF7us.jpg","gifPath":"exercises/videos/0535-LHWF7us.gif","instructionSteps":["双脚分开与肩同宽站立，将壶铃放在大腿前面。","稍微弯曲膝盖，髋部向前转动，保持背部挺直。","将壶铃放低至地面，使其在双腿之间摆动。","快速伸展臀部和膝盖，利用动量将壶铃摆动到肩膀高度。","当壶铃达到肩膀高度时，旋转手腕，将壶铃置于架子位置，肘部内收，壶铃靠在前臂上。","将壶铃放回双腿之间的起始位置，然后重复所需的重复次数。"]},{"id":"0536","name":"kettlebell lunge pass through","nameZh":"壶铃弓步传穿过","equipment":"kettlebell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0536-WKMQzCD.jpg","gifPath":"exercises/videos/0536-WKMQzCD.gif","instructionSteps":["双脚分开与肩同宽站立，双手握住壶铃放在胸前。","右脚向前迈出一步，将身体降低至弓步位置。","当你向前弓步时，将壶铃传递到右大腿下方，然后将其转移到左手。","用右脚蹬地回到起始位置，同时将壶铃传回右手。","在另一侧重复弓步，将壶铃传递到左大腿下方。","继续交替弓步并在双手之间传递壶铃，达到所需的重复次数。"]},{"id":"0537","name":"kettlebell one arm clean and jerk","nameZh":"壶铃单臂翻举挺举","equipment":"kettlebell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0537-vzAxBtt.jpg","gifPath":"exercises/videos/0537-vzAxBtt.gif","instructionSteps":["双脚分开与肩同宽站立，一只手握住壶铃，正手握住。","稍微弯曲膝盖并以臀部为铰链，将壶铃放在两腿之间。","爆发性地伸展你的臀部、膝盖和脚踝，利用动量将壶铃摆动到肩膀的高度。","当壶铃到达肩膀高度时，旋转手腕并向上挥拳，将手臂锁定在头顶上方。","将壶铃放回起始位置，然后重复所需的重复次数。"]},{"id":"0538","name":"kettlebell one arm jerk","nameZh":"壶铃单臂挺举","equipment":"kettlebell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0538-S37C94C.jpg","gifPath":"exercises/videos/0538-S37C94C.gif","instructionSteps":["双脚分开与肩同宽站立，一只手握住壶铃，与肩同高。","稍微弯曲膝盖并启动核心。","将壶铃沿直线压过头顶，充分伸展手臂。","当你将壶铃举过头顶时，同时弯曲膝盖并快速伸直以产生动力。","当壶铃到达最高点时，弯曲膝盖和臀部，快速落到壶铃下方。","膝盖和臀部稍微弯曲，抓住壶铃，手臂完全伸过头顶。","站直，充分伸展膝盖和臀部，并将壶铃稳定在头顶上。","弯曲膝盖和臀部，将壶铃放回起始位置，然后重复所需的重复次数。"]},{"id":"0539","name":"kettlebell one arm military press to the side","nameZh":"壶铃单臂军事推举至侧","equipment":"kettlebell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0539-yCvYdi7.jpg","gifPath":"exercises/videos/0539-yCvYdi7.gif","instructionSteps":["双脚分开与肩同宽站立，一只手握住壶铃，与肩同高。","启动你的核心并保持背部挺直。","将壶铃压过头顶，充分伸展手臂。","在顶部暂停片刻，然后慢慢将壶铃放回起始位置。","重复所需的重复次数，然后换边。"]},{"id":"0540","name":"kettlebell one arm push press","nameZh":"壶铃单臂借力推举","equipment":"kettlebell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0540-osdXT3K.jpg","gifPath":"exercises/videos/0540-osdXT3K.gif","instructionSteps":["双脚分开与肩同宽站立，一只手握住壶铃，与肩同高。","稍微弯曲膝盖并启动核心。","伸展手臂并完全伸展双腿，将壶铃压过头顶。","弯曲膝盖并将壶铃放回肩膀，将壶铃放回起始位置。","重复所需的重复次数，然后换边。"]},{"id":"0541","name":"kettlebell one arm row","nameZh":"壶铃单臂划船","equipment":"kettlebell","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0541-g9AsZ8P.jpg","gifPath":"exercises/videos/0541-g9AsZ8P.gif","instructionSteps":["双脚分开与肩同宽站立，一只手握住壶铃，正手握住。","稍微弯曲膝盖，髋部向前转动，保持背部挺直，核心肌群参与。","将壶铃向上拉向胸部，保持肘部靠近身体并将肩胛骨挤压在一起。","在顶部暂停片刻，然后慢慢将壶铃放回起始位置。","重复所需的重复次数，然后换边并用另一只手臂重复。"]},{"id":"0542","name":"kettlebell one arm snatch","nameZh":"壶铃单臂抓举","equipment":"kettlebell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0542-aXcUyKb.jpg","gifPath":"exercises/videos/0542-aXcUyKb.gif","instructionSteps":["双脚分开与肩同宽站立，一只手将壶铃放在两腿之间。","稍微弯曲膝盖并铰接臀部，将壶铃降低到地面。","爆发性地伸展你的臀部和膝盖，利用动量将壶铃向上摆动到你的肩膀上。","当壶铃到达肩膀高度时，旋转你的手并将其直接击打到头顶，完全伸展你的手臂。","将壶铃放回到双腿之间，然后重复所需的重复次数。"]},{"id":"0543","name":"kettlebell pirate supper legs","nameZh":"壶铃海盗晚餐腿","equipment":"kettlebell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0543-kuXhl0o.jpg","gifPath":"exercises/videos/0543-kuXhl0o.gif","instructionSteps":["双脚分开与肩同宽站立，一只手握住壶铃。","稍微弯曲膝盖，髋部向前转动，保持背部挺直。","将壶铃举至肩膀高度，保持肘部靠近身体。","将手臂完全伸过头顶，伸直肘部。","将壶铃降低至肩膀高度，然后返回起始位置。","重复所需的重复次数，然后换边。"]},{"id":"0544","name":"kettlebell pistol squat","nameZh":"壶铃手枪式深蹲","equipment":"kettlebell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0544-5bpPTHv.jpg","gifPath":"exercises/videos/0544-5bpPTHv.gif","instructionSteps":["双脚分开与肩同宽站立，双手握住壶铃放在胸前。","将左脚抬离地面并向前伸展，保持与地面平行。","慢慢地将身体降低到蹲姿，保持右脚平放在地面上，左腿伸展。","在深蹲底部暂停片刻，然后推动右脚跟返回到起始位置。","重复所需的重复次数，然后换腿。"]},{"id":"0545","name":"kettlebell plyo push-up","nameZh":"壶铃爆发式俯卧撑","equipment":"kettlebell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0545-ktf3nvW.jpg","gifPath":"exercises/videos/0545-ktf3nvW.gif","instructionSteps":["从高平板支撑位置开始，双手放在壶铃上，距离与肩同宽。","将胸部压向地面，保持肘部靠近身体。","爆发性地推动你的手，将你的手从壶铃上抬起并完全伸展你的手臂。","轻轻地回到壶铃上，并立即降低胸部以进行下一次重复。","重复所需的重复次数。"]},{"id":"0546","name":"kettlebell seated press","nameZh":"壶铃坐姿推举","equipment":"kettlebell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0546-BkxB8LW.jpg","gifPath":"exercises/videos/0546-BkxB8LW.gif","instructionSteps":["坐在长凳上，背部挺直，双脚平放在地上。","每只手握住一个壶铃，与肩同高，手掌朝前。","将壶铃压过头顶，充分伸展手臂。","将壶铃降低至肩膀高度。","重复所需的重复次数。"]},{"id":"0547","name":"kettlebell seesaw press","nameZh":"壶铃跷跷板推举","equipment":"kettlebell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0547-UDm6cGl.jpg","gifPath":"exercises/videos/0547-UDm6cGl.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个壶铃，与肩同高。","将一个壶铃压过头顶，同时将另一个壶铃保持在肩膀高度。","将按下的壶铃降低至肩膀高度，同时将另一个壶铃压过头顶。","继续交替按压动作，形成跷跷板状的运动。","重复所需的重复次数。"]},{"id":"0548","name":"kettlebell sumo high pull","nameZh":"壶铃相扑高位拉","equipment":"kettlebell","bodyPart":"back","target":"traps","imagePath":"exercises/images/0548-8ARQ9Hw.jpg","gifPath":"exercises/videos/0548-8ARQ9Hw.gif","instructionSteps":["站立，双脚分开比肩宽，脚趾朝外。","双手握住壶铃放在身体前方，手臂向下伸展。","弯曲膝盖，降低臀部至下蹲位置，保持背部挺直。","脚后跟发力，爆发性伸展臀部和膝盖，将壶铃拉向下巴。","当你向上拉壶铃时，保持肘部高且宽，并将肩胛骨挤压在一起。","将壶铃放回起始位置，然后重复所需的重复次数。"]},{"id":"0549","name":"kettlebell swing","nameZh":"壶铃摆动","equipment":"kettlebell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0549-UHJlbu3.jpg","gifPath":"exercises/videos/0549-UHJlbu3.gif","instructionSteps":["双脚分开与肩同宽站立，脚趾稍微向外。","双手握住壶铃放在身体前方，双臂伸展。","稍微弯曲膝盖并铰接臀部，将臀部向后推。","将壶铃在两腿之间向后摆动，保持手臂伸直并保持背部平坦。","利用臀部产生的动量，向前推动臀部并将壶铃摆动到肩膀高度。","让壶铃在双腿之间向下摆动，然后重复该动作达到所需的重复次数。"]},{"id":"0550","name":"kettlebell thruster","nameZh":"壶铃推蹲","equipment":"kettlebell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0550-yWxMvB5.jpg","gifPath":"exercises/videos/0550-yWxMvB5.gif","instructionSteps":["首先，双脚分开与肩同宽站立，双手将壶铃放在胸前，手掌相对。","弯曲膝盖并将臀部向后推，保持挺胸、背部挺直，进入蹲姿。","当你到达深蹲底部时，爆发性地通过脚后跟站起来，同时将壶铃压过头顶。","在动作的最高点锁定你的手臂，完全伸展你的肘部。","通过反转动作，弯曲肘部并将重量放回胸部，将壶铃放回起始位置。","重复所需的重复次数。"]},{"id":"0551","name":"kettlebell turkish get up (squat style)","nameZh":"壶铃土耳其起立 (深蹲式)","equipment":"kettlebell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0551-Ha7SZ3y.jpg","gifPath":"exercises/videos/0551-Ha7SZ3y.gif","instructionSteps":["首先仰卧，双腿伸展，右手握住壶铃，手臂完全伸展到肩膀上方。","弯曲右膝，将右脚平放在地面上，保持左腿伸展。","压右脚，将臀部抬离地面，进入桥位。","将左腿滑到身体下方，弯曲左膝并将左脚平放在地面上。","将躯干向左旋转，将左手放在地面上以获得支撑。","压右脚和左手，将躯干抬离地面，形成跪姿。","从跪姿站起来，保持壶铃伸过头顶。","反向运动以返回到起始位置。","从左手的壶铃开始，在另一侧重复练习。"]},{"id":"0552","name":"kettlebell two arm clean","nameZh":"壶铃双臂翻举","equipment":"kettlebell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0552-7Ba7bQ2.jpg","gifPath":"exercises/videos/0552-7Ba7bQ2.gif","instructionSteps":["双脚分开与肩同宽站立，双手握住壶铃放在大腿前，手掌朝向自己。","稍微弯曲膝盖并铰接臀部，将壶铃降低到地面。","爆发性伸展臀部和膝盖，利用动量将壶铃拉向肩膀。","当壶铃达到肩膀高度时，旋转手腕，将壶铃放在架子上，肘部内收，壶铃放在前臂背面。","将壶铃放回起始位置，然后重复所需的重复次数。"]},{"id":"0553","name":"kettlebell two arm military press","nameZh":"壶铃双臂军事推举","equipment":"kettlebell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0553-blBXysN.jpg","gifPath":"exercises/videos/0553-blBXysN.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个壶铃，与肩同高，手掌朝前。","启动你的核心并将壶铃压过头顶，充分伸展你的手臂。","在顶部暂停片刻，然后慢慢将壶铃放回起始位置。","重复所需的重复次数。"]},{"id":"0554","name":"kettlebell windmill","nameZh":"壶铃风车式","equipment":"kettlebell","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0554-9Tkqa9O.jpg","gifPath":"exercises/videos/0554-9Tkqa9O.gif","instructionSteps":["双脚分开与肩同宽站立，右手握住壶铃举过头顶。","将左脚向外旋转约 45 度，并保持右脚指向前方。","将你的躯干向左侧弯曲，保持右臂伸过头顶，眼睛盯着壶铃。","尽可能降低躯干，同时保持右臂伸直，左臂向一侧伸展。","暂停片刻，然后通过推动右脚并接合斜肌返回到起始位置。","重复所需的重复次数，然后换边。"]},{"id":"0555","name":"kick out sit","nameZh":"踢腿坐","equipment":"body weight","bodyPart":"upper legs","target":"hamstrings","imagePath":"exercises/images/0555-v7p5bYl.jpg","gifPath":"exercises/videos/0555-v7p5bYl.gif","instructionSteps":["坐在长凳或椅子的边缘，双脚平放在地上，膝盖弯曲成 90 度角。","稍微向后倾斜，将双手放在长凳或椅子的边缘以获得支撑。","启动腿筋，将脚抬离地面，并将双腿伸直到身前。","在顶部停顿片刻，然后慢慢弯曲膝盖，将脚放回身体。","重复所需的重复次数。"]},{"id":"0558","name":"kipping muscle up","nameZh":"借力双力臂","equipment":"body weight","bodyPart":"back","target":"lats","imagePath":"exercises/images/0558-pM07UxU.jpg","gifPath":"exercises/videos/0558-pM07UxU.gif","instructionSteps":["首先，用正手握法悬挂在引体向上杆上，双手分开的距离略大于肩宽。","启动你的核心并使用摆动动作来产生动力。","当你向前挥杆时，将胸部拉向杠铃，用背阔肌和二头肌开始动作。","继续向上运动，直到胸部到达杠铃，然后向下推杠铃并伸展手臂，过渡到双臂屈伸姿势。","弯曲手臂并控制下降，将自己放回到起始位置。","重复所需的重复次数。"]},{"id":"0562","name":"landmine 180","nameZh":"地雷管 180","equipment":"barbell","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0562-QYysSLV.jpg","gifPath":"exercises/videos/0562-QYysSLV.gif","instructionSteps":["双脚分开与肩同宽站立，双手握住杠铃于胸前。","稍微弯曲膝盖并将躯干向右旋转，将杠铃向下朝右臀部摆动。","当你到达动作的底部时，快速反向运动并向左旋转你的躯干，向上摆动杠铃并穿过你的身体朝向左肩。","继续这个扭转动作，两侧交替，达到所需的重复次数。"]},{"id":"0570","name":"leg pull in flat bench","nameZh":"腿拉内平板凳","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0570-OyoZ3Pu.jpg","gifPath":"exercises/videos/0570-OyoZ3Pu.gif","instructionSteps":["坐在平坦的长凳上，双腿在身前伸直。","将双手放在臀部旁边的长凳上以获得支撑。","收紧腹肌，将双腿抬离地面，使膝盖靠近胸部。","在顶部暂停片刻，然后慢慢将双腿放回起始位置。","重复所需的重复次数。"]},{"id":"0571","name":"lever alternating narrow grip seated row","nameZh":"杠杆机交替窄握坐姿划船","equipment":"leverage machine","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0571-w2oRpuH.jpg","gifPath":"exercises/videos/0571-w2oRpuH.gif","instructionSteps":["调整座椅高度和踏板位置以确保正确对齐。","坐在机器上，背部挺直，双脚平放在踏板上。","紧紧握住手柄，手掌相对。","在整个练习过程中保持挺胸、肩膀向后。","将一个手柄拉向您的躯干，同时保持另一个手柄静止。","在动作结束时将肩胛骨挤压在一起。","慢慢地将手柄返回到起始位置，并在另一侧重复此操作。","继续交替进行所需的重复次数。"]},{"id":"0572","name":"lever assisted chin-up","nameZh":"杠杆机辅助反握引体向上","equipment":"leverage machine","bodyPart":"back","target":"lats","imagePath":"exercises/images/0572-MaMuGH6.jpg","gifPath":"exercises/videos/0572-MaMuGH6.gif","instructionSteps":["将杠杆机调整至您想要的阻力水平。","站在脚踏板上，正手握住手柄，握距略宽于肩宽。","双臂完全伸展，保持身体挺直。","收紧背部肌肉，将身体拉向手柄，以胸部为主导。","继续拉，直到下巴位于手柄上方。","在顶部停顿片刻，然后慢慢将身体放回起始位置。","重复所需的重复次数。"]},{"id":"0573","name":"lever back extension","nameZh":"杠杆机背伸展","equipment":"leverage machine","bodyPart":"back","target":"spine","imagePath":"exercises/images/0573-rUXfn3R.jpg","gifPath":"exercises/videos/0573-rUXfn3R.gif","instructionSteps":["调整机器以适合您的身体尺寸和运动范围。","坐在机器上，背部靠在垫子上，双脚固定。","将手放在手柄或握杆上。","启动你的核心并慢慢向前倾斜，让你的背部稍微弯曲。","在底部位置暂停片刻，感觉下背部有拉伸感。","使用背部肌肉，慢慢将躯干抬回到起始位置。","重复所需的重复次数。"]},{"id":"0574","name":"lever bent over row","nameZh":"杠杆机俯身划船","equipment":"barbell","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0574-X3cqyXz.jpg","gifPath":"exercises/videos/0574-X3cqyXz.gif","instructionSteps":["站立，双脚分开与肩同宽，膝盖稍微弯曲。","正手握住杠铃，双手分开略宽于肩宽。","臀部向前弯曲，保持背部挺直，挺胸。","将杠铃拉向下胸部，将肩胛骨挤压在一起。","在顶部停顿片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0575","name":"lever bicep curl","nameZh":"杠杆机肱二头肌弯举","equipment":"leverage machine","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0575-q6y3OhV.jpg","gifPath":"exercises/videos/0575-q6y3OhV.gif","instructionSteps":["调整座椅高度并将自己放在机器上，背部靠在垫子上。","反手握住手柄，手掌朝上，肘部靠近身体两侧。","呼气并向上弯曲手柄，收缩二头肌。","在动作的最高点暂停片刻，挤压你的二头肌。","吸气，慢慢将手柄放回起始位置，充分伸展双臂。","重复所需的重复次数。"]},{"id":"0576","name":"lever chest press","nameZh":"杠杆机胸部推举","equipment":"leverage machine","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0576-DOoWcnA.jpg","gifPath":"exercises/videos/0576-DOoWcnA.gif","instructionSteps":["调整座椅高度，将自己放在机器上，背部平放在垫子上。","正手握住手柄，肘部呈 90 度角。","向前推动手柄，直到手臂完全伸展，运动过程中呼气。","动作结束时短暂暂停，然后慢慢回到起始位置，同时吸气。","重复所需的重复次数。"]},{"id":"0577","name":"lever chest press","nameZh":"杠杆机胸部推举","equipment":"leverage machine","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0577-T0yTjgW.jpg","gifPath":"exercises/videos/0577-T0yTjgW.gif","instructionSteps":["调整座椅高度，将自己放在机器上，背部平放在垫子上。","正手握住手柄，肘部呈 90 度角。","向前推动手柄，直到手臂完全伸展，运动过程中呼气。","动作结束时短暂暂停，然后慢慢回到起始位置，同时吸气。","重复所需的重复次数。"]},{"id":"0578","name":"lever deadlift","nameZh":"杠杆机硬拉","equipment":"leverage machine","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0578-GUT8I22.jpg","gifPath":"exercises/videos/0578-GUT8I22.gif","instructionSteps":["将座椅高度和脚踏板调整到您想要的位置。","坐在机器上，背部靠在垫子上，双脚平放在脚踏板上。","抓住把手或座椅侧面以保持稳定性。","收紧臀肌和腿筋，并通过脚后跟推动举重。","保持背部挺直，避免圆肩。","在动作的最高点完全伸展臀部，挤压臀部。","以受控的方式降低重量，保持臀肌和腿筋的张力。","重复所需的重复次数。"]},{"id":"0579","name":"lever front pulldown","nameZh":"杠杆机前下拉","equipment":"leverage machine","bodyPart":"back","target":"lats","imagePath":"exercises/images/0579-7F1DVzn.jpg","gifPath":"exercises/videos/0579-7F1DVzn.gif","instructionSteps":["调整座椅高度，将自己放在机器上，膝盖位于垫子下方，双脚平放在地面上。","正手握住手柄，握距略宽于肩宽。","坐直，胸部抬起，肩膀向后，保持下背部轻微的拱形。","收紧背阔肌，将手柄向下拉向胸部，将肩胛骨挤压在一起。","在动作底部暂停片刻，然后慢慢松开手柄回到起始位置。","重复所需的重复次数。"]},{"id":"0580","name":"lever gripless shrug","nameZh":"杠杆机无握耸肩","equipment":"leverage machine","bodyPart":"back","target":"traps","imagePath":"exercises/images/0580-f91FwXG.jpg","gifPath":"exercises/videos/0580-f91FwXG.gif","instructionSteps":["调整座椅高度并将自己放在杠杆机上。","手掌朝内，抓住手柄，双臂完全伸展。","保持背部挺直，呼气并尽可能抬高肩膀。","保持收缩一会儿，然后吸气并慢慢将肩膀放回起始位置。","重复所需的重复次数。"]},{"id":"0581","name":"lever high row","nameZh":"杠杆机高位划船","equipment":"leverage machine","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0581-nZZZy9m.jpg","gifPath":"exercises/videos/0581-nZZZy9m.gif","instructionSteps":["将座椅高度和脚踏板调整至舒适的位置。","坐在机器上，胸部靠在垫子上，双脚平放在脚踏平台上。","正手握住手柄，握距略宽于肩宽。","保持背部挺直并启动核心肌群。","将手柄拉向身体，将肩胛骨挤压在一起。","在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。","重复所需的重复次数。"]},{"id":"0582","name":"lever kneeling leg curl","nameZh":"杠杆机跪姿腿弯举","equipment":"leverage machine","bodyPart":"upper legs","target":"hamstrings","imagePath":"exercises/images/0582-nnmCTLN.jpg","gifPath":"exercises/videos/0582-nnmCTLN.gif","instructionSteps":["调整机器以适合您的身体并选择所需的重量。","面朝下跪在机器上，膝盖放在垫子上，双脚固定在脚垫下。","抓住机器的手柄或侧面以保持稳定性。","保持上半身静止，呼气，弯曲膝盖，将双腿向臀肌方向卷起。","在动作的最高点暂停片刻，挤压你的腿筋。","吸气，慢慢将双腿放回起始位置，充分伸展膝盖。","重复所需的重复次数。"]},{"id":"0583","name":"lever kneeling twist","nameZh":"杠杆机跪姿转体","equipment":"leverage machine","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0583-sZOR9EV.jpg","gifPath":"exercises/videos/0583-sZOR9EV.gif","instructionSteps":["调整座椅高度，将自己放在机器上，膝盖放在垫子上，上半身朝前。","抓住机器的手柄或侧面以保持稳定性。","保持核心参与，将躯干尽可能舒适地向一侧扭转。","暂停片刻，然后慢慢回到起始位置。","向另一侧重复扭转。","继续交替进行所需的重复次数。"]},{"id":"0584","name":"lever lateral raise","nameZh":"杠杆机侧平举","equipment":"leverage machine","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0584-dRTfGZT.jpg","gifPath":"exercises/videos/0584-dRTfGZT.gif","instructionSteps":["调整座椅高度并将自己放在机器上，背部靠在垫子上。","正手握住手柄并保持手臂伸直。","呼气并将手臂向两侧抬起，直到与地板平行。","在顶部停顿片刻，然后吸气，慢慢将手臂放回起始位置。","重复所需的重复次数。"]},{"id":"0585","name":"lever leg extension","nameZh":"杠杆机腿伸展","equipment":"leverage machine","bodyPart":"upper legs","target":"quads","imagePath":"exercises/images/0585-my33uHU.jpg","gifPath":"exercises/videos/0585-my33uHU.gif","instructionSteps":["调整机器的座椅高度和靠背以适合您的身体。","坐在机器上，背部靠在靠背上，双脚放在脚垫上。","抓住手柄或侧杆以保持稳定性。","伸直膝盖，举起重物，向前伸展双腿。","在顶部暂停片刻，然后慢慢将重量放回起始位置。","重复所需的重复次数。"]},{"id":"0586","name":"lever lying leg curl","nameZh":"俯卧腿弯举","equipment":"leverage machine","bodyPart":"upper legs","target":"hamstrings","imagePath":"exercises/images/0586-17lJ1kr.jpg","gifPath":"exercises/videos/0586-17lJ1kr.gif","instructionSteps":["调整机器以适合您的身体并选择所需的重量。","面朝下躺在机器上，双腿伸直，脚跟靠在带衬垫的杠杆上。","抓住机器的手柄或侧面以保持稳定性。","保持上半身静止，呼气并尽可能向上弯曲双腿，但不要将臀部抬离垫子。","挤压腿筋时，保持收缩位置短暂停顿。","吸气并缓慢地将控制杆降低回起始位置。","重复所需的重复次数。"]},{"id":"0587","name":"lever military press","nameZh":"杠杆机军事推举","equipment":"leverage machine","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0587-CggQhII.jpg","gifPath":"exercises/videos/0587-CggQhII.gif","instructionSteps":["调整座椅高度并将自己放在机器上，背部靠在靠背上。","正手握住手柄，双手之间的距离略大于肩宽。","向上推动手柄，直到手臂完全伸展，但不要锁住肘部。","在顶部暂停片刻，然后慢慢将手柄放回起始位置。","重复所需的重复次数。"]},{"id":"0588","name":"lever narrow grip seated row","nameZh":"杠杆机窄握坐姿划船","equipment":"leverage machine","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0588-IGjKj1v.jpg","gifPath":"exercises/videos/0588-IGjKj1v.gif","instructionSteps":["调整座椅高度和脚踏板以确保形状正确。","坐在机器上，双脚平放在脚踏板上，膝盖稍微弯曲。","紧紧握住手柄，手掌相对。","保持背部挺直并稍微向前倾斜。","将手柄拉向躯干，将肩胛骨挤压在一起。","在动作的最高点停顿片刻。","慢慢松开手柄并返回到起始位置。","重复所需的重复次数。"]},{"id":"0589","name":"lever one arm bent over row","nameZh":"杠杆机单臂俯身划船","equipment":"barbell","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0589-Fhdtwf3.jpg","gifPath":"exercises/videos/0589-Fhdtwf3.gif","instructionSteps":["双脚分开与肩同宽站立，膝盖稍微弯曲，正手握住杠铃。","臀部向前弯曲，保持背部挺直，头部抬起。","让杠铃悬挂在你面前，双臂完全伸展。","将杠铃拉向胸部，保持肘部靠近身体。","在动作的最高点将肩胛骨挤压在一起。","将杠铃降低回到起始位置。","重复所需的重复次数。"]},{"id":"0590","name":"lever one arm shoulder press","nameZh":"杠杆机单臂肩推","equipment":"leverage machine","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0590-2KGnL6M.jpg","gifPath":"exercises/videos/0590-2KGnL6M.gif","instructionSteps":["调整座椅高度并将自己放在机器上，背部靠在垫子上。","用一只手抓住杠杆手柄，并将肘部置于 90 度角。","向上按下控制杆，直到手臂完全伸过头顶。","在顶部暂停片刻，然后慢慢将控制杆放回起始位置。","重复所需的重复次数，然后换到另一只手臂。"]},{"id":"0591","name":"lever overhand triceps dip","nameZh":"杠杆机上方手肱三头肌臂屈伸","equipment":"leverage machine","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0591-D5yqP2p.jpg","gifPath":"exercises/videos/0591-D5yqP2p.gif","instructionSteps":["将机器调整到合适的高度并将身体固定到位。","正手握住手柄，调整身体位置，使手臂完全伸展。","弯曲肘部降低身体，保持上臂靠近身体两侧。","继续降低，直到上臂与地板平行。","暂停片刻，然后伸展肘部将自己推回起始位置。","重复所需的重复次数。"]},{"id":"0592","name":"lever preacher curl","nameZh":"杠杆机牧师凳弯举","equipment":"leverage machine","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0592-b6hQYMb.jpg","gifPath":"exercises/videos/0592-b6hQYMb.gif","instructionSteps":["调整座椅高度并将自己放在杠杆机上。","将上臂放在垫子上，并用反手握住手柄。","保持背部挺直，并将肘部放在垫子上。","呼气并将前臂向上臂弯曲，收缩二头肌。","在动作的最高点暂停片刻，挤压你的二头肌。","吸气并慢慢将手柄放回起始位置。","重复所需的重复次数。"]},{"id":"0593","name":"lever reverse hyperextension","nameZh":"杠杆机反向过度伸展","equipment":"leverage machine","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0593-Krmb3cB.jpg","gifPath":"exercises/videos/0593-Krmb3cB.gif","instructionSteps":["调整杠杆机以适合您的身体并将双脚固定在脚垫中。","面朝下躺在机器上，上半身悬在机器边缘，臀部放在垫子上。","双臂交叉放在胸前或放在脑后。","用臀部和腿筋将双腿向上抬起，直到它们与地面平行。","在顶部暂停片刻，然后慢慢将双腿放回起始位置。","重复所需的重复次数。"]},{"id":"0594","name":"lever seated calf raise","nameZh":"杠杆机坐姿提踵","equipment":"leverage machine","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/0594-bOOdeyc.jpg","gifPath":"exercises/videos/0594-bOOdeyc.gif","instructionSteps":["调整座椅高度，使膝盖稍微弯曲，双脚平放在踏板上。","将脚趾放在踏板上，脚跟悬在踏板边缘。","抓住把手或座椅侧面以保持稳定性。","推动脚掌，将脚后跟尽可能抬高。","在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。","重复所需的重复次数。"]},{"id":"0595","name":"lever seated crunch (chest pad)","nameZh":"杠杆机坐姿卷腹 (胸部垫)","equipment":"leverage machine","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0595-ZnJHhMk.jpg","gifPath":"exercises/videos/0595-ZnJHhMk.gif","instructionSteps":["根据您的舒适度调整座椅高度和胸垫位置。","坐在机器上，背部靠在胸垫上，双脚平放在地板上。","抓住手柄或侧杆以保持稳定性。","收紧腹肌并慢慢向后倾斜，让胸垫随着您一起移动。","在最大收缩时暂停片刻，感受腹肌的紧张感。","收缩腹肌并将自己拉回来，慢慢回到起始位置。","重复所需的重复次数。"]},{"id":"0596","name":"lever seated fly","nameZh":"杠杆机坐姿飞鸟","equipment":"leverage machine","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0596-v3xmPAR.jpg","gifPath":"exercises/videos/0596-v3xmPAR.gif","instructionSteps":["调整座椅高度并将自己放在机器上，背部靠在垫子上。","旋前抓住手柄，并保持肘部稍微弯曲。","呼气并将手柄向前推，将它们放在胸前。","暂停片刻，挤压胸部肌肉。","吸气并慢慢回到起始位置，让胸部肌肉伸展。","重复所需的重复次数。"]},{"id":"0597","name":"lever seated hip abduction","nameZh":"杠杆机坐姿髋外展","equipment":"leverage machine","bodyPart":"upper legs","target":"abductors","imagePath":"exercises/images/0597-CHpahtl.jpg","gifPath":"exercises/videos/0597-CHpahtl.gif","instructionSteps":["调整座椅高度，使膝盖成 90 度角。","坐在机器上，背部靠在靠背上，双脚放在脚踏板上。","将手放在侧手柄上以保持稳定性。","启动外展肌并慢慢将双腿分开，远离身体中线。","动作结束时暂停片刻，然后慢慢将双腿放回到起始位置。","重复所需的重复次数。"]},{"id":"0598","name":"lever seated hip adduction","nameZh":"杠杆机坐姿髋内收","equipment":"leverage machine","bodyPart":"upper legs","target":"adductors","imagePath":"exercises/images/0598-oHsrypV.jpg","gifPath":"exercises/videos/0598-oHsrypV.gif","instructionSteps":["调整座椅高度并将自己放在机器上，背部靠在靠背上。","将脚放在脚踏板上并抓住手柄以保持稳定。","收紧内收肌，慢慢将双腿并拢，挤压大腿内侧。","在收缩高峰时暂停片刻，然后慢慢回到起始位置。","重复所需的重复次数。"]},{"id":"0599","name":"lever seated leg curl","nameZh":"杠杆机坐姿腿弯举","equipment":"leverage machine","bodyPart":"upper legs","target":"hamstrings","imagePath":"exercises/images/0599-Zg3XY7P.jpg","gifPath":"exercises/videos/0599-Zg3XY7P.gif","instructionSteps":["调整机器以适合您的身体，然后坐在机器上，背部靠在靠背上。","将小腿放在带衬垫的杠杆下方，就在脚踝上方。","抓住机器两侧的手柄以提供支撑。","保持大腿不动，呼气并尽可能向上弯曲双腿。","挤压腿筋时，保持收缩位置短暂停顿。","吸气并缓慢地将控制杆降低回起始位置。","重复所需的重复次数。"]},{"id":"0600","name":"lever seated leg raise crunch","nameZh":"杠杆机坐姿抬腿卷腹","equipment":"leverage machine","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0600-PQ2AtC3.jpg","gifPath":"exercises/videos/0600-PQ2AtC3.gif","instructionSteps":["坐在杠杆机上，背部靠在靠背上，双脚放在脚踏板上。","抓住手柄或侧杆以保持稳定性。","收紧腹肌，慢慢地将双腿抬向胸部，同时向前卷曲躯干。","在顶部停顿片刻，然后慢慢降低双腿和躯干回到起始位置。","重复所需的重复次数。"]},{"id":"0601","name":"lever seated reverse fly (parallel grip)","nameZh":"杠杆机坐姿反向飞鸟 (平行握距)","equipment":"leverage machine","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0601-xiHiJcA.jpg","gifPath":"exercises/videos/0601-xiHiJcA.gif","instructionSteps":["调整座椅高度，将自己放在机器上，胸部靠在垫子上，双脚平放在地板上。","平行握住手柄，手掌相对，并保持手臂稍微弯曲。","呼气并将肩胛骨挤压在一起，同时向后和向外拉动手柄，使其远离身体。","在收缩峰值时停顿片刻，然后吸气，慢慢回到起始位置。","重复所需的重复次数。"]},{"id":"0602","name":"lever seated reverse fly","nameZh":"杠杆机坐姿反向飞鸟","equipment":"leverage machine","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0602-myfUsKf.jpg","gifPath":"exercises/videos/0602-myfUsKf.gif","instructionSteps":["调整座椅高度，将自己放在机器上，胸部靠在垫子上，双脚平放在地板上。","正手握住手柄，并保持手臂稍微弯曲。","呼气并将肩胛骨挤压在一起，同时向后和向外拉动手柄，使其远离身体。","在收缩峰值时停顿片刻，然后吸气，慢慢回到起始位置。","重复所需的重复次数。"]},{"id":"0603","name":"lever shoulder press","nameZh":"杠杆机肩推","equipment":"leverage machine","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0603-67n3r98.jpg","gifPath":"exercises/videos/0603-67n3r98.gif","instructionSteps":["调整座椅高度并将自己放在机器上，背部靠在靠背上。","正手握住手柄，并将双手置于肩部水平。","向上推动手柄，直到手臂完全伸展，但不要锁住肘部。","在顶部暂停片刻，然后慢慢将手柄放回起始位置。","重复所需的重复次数。"]},{"id":"0604","name":"lever shrug","nameZh":"杠杆机耸肩","equipment":"leverage machine","bodyPart":"back","target":"traps","imagePath":"exercises/images/0604-ZZKbeMw.jpg","gifPath":"exercises/videos/0604-ZZKbeMw.gif","instructionSteps":["调整座椅高度，将自己放在杠杆机上，背部靠在垫子上。","正手握住手柄并保持手臂伸直。","保持背部挺直，将肩膀尽可能高地抬向耳朵。","保持收缩一会儿，然后慢慢将肩膀放回起始位置。","重复所需的重复次数。"]},{"id":"0605","name":"lever standing calf raise","nameZh":"站姿提踵","equipment":"leverage machine","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/0605-ykUOVze.jpg","gifPath":"exercises/videos/0605-ykUOVze.gif","instructionSteps":["将机器调整到您的高度，双脚分开与肩同宽站立。","将肩膀放在护垫下方，并握住手柄以保持稳定。","伸展脚踝，将脚后跟尽可能抬高。","在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。","重复所需的重复次数。"]},{"id":"0606","name":"lever t bar row","nameZh":"杠杆机 T 杆划船","equipment":"leverage machine","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0606-aaXr7ld.jpg","gifPath":"exercises/videos/0606-aaXr7ld.gif","instructionSteps":["调整座椅高度和踏板位置以确保正确对齐。","坐在机器上，胸部靠在垫子上，双脚平放在踏板上。","正手握住手柄，握距略宽于肩宽。","保持背部挺直并启动核心肌群。","将手柄拉向躯干，将肩胛骨挤压在一起。","在收缩峰值时暂停片刻，然后慢慢松开手柄回到起始位置。","重复所需的重复次数。"]},{"id":"0607","name":"lever triceps extension","nameZh":"杠杆机肱三头肌伸展","equipment":"leverage machine","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0607-Ser9eQp.jpg","gifPath":"exercises/videos/0607-Ser9eQp.gif","instructionSteps":["调整座椅高度并将自己放在机器上，背部靠在垫子上。","正手握住手柄，并将手臂完全伸展到身前。","保持上臂不动，弯曲肘部，慢慢将手柄向前额降低。","在底部暂停片刻，然后伸展双臂将手柄推回起始位置。","重复所需的重复次数。"]},{"id":"0609","name":"london bridge","nameZh":"伦敦桥","equipment":"rope","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0609-bLyQokI.jpg","gifPath":"exercises/videos/0609-bLyQokI.gif","instructionSteps":["将绳子连接到高锚点。","背对锚点站立，双脚与肩同宽。","正手握住绳子，手掌朝下。","稍微向前倾，保持背部挺直，核心参与。","将绳子拉向身体，将肩胛骨挤压在一起。","在动作的最高点停顿片刻，然后慢慢释放张力，回到起始位置。","重复所需的重复次数。"]},{"id":"0613","name":"lying (side) quads stretch","nameZh":"仰卧 (侧) 股四头肌拉伸","equipment":"body weight","bodyPart":"upper legs","target":"quads","imagePath":"exercises/images/0613-BWnJR72.jpg","gifPath":"exercises/videos/0613-BWnJR72.gif","instructionSteps":["侧躺，双腿伸直。","弯曲上面的那条腿，用手抓住脚踝或脚。","轻轻地将脚踝或脚拉向臀部，直到感觉到股四头肌有拉伸感。","保持拉伸 20-30 秒。","松开拉伸并在另一侧重复。"]},{"id":"0620","name":"lying leg raise flat bench","nameZh":"仰卧抬腿平板凳","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0620-WhuFnR7.jpg","gifPath":"exercises/videos/0620-WhuFnR7.gif","instructionSteps":["平躺在平坦的长凳上，背部紧贴长凳。","将双手放在臀部下方以获得支撑。","保持双腿伸直并拢，然后将它们抬向天花板。","在顶部暂停片刻，然后慢慢将双腿放回起始位置。","重复所需的重复次数。"]},{"id":"0624","name":"march sit (wall)","nameZh":"行军步坐 (墙)","equipment":"body weight","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0624-sVQCCeG.jpg","gifPath":"exercises/videos/0624-sVQCCeG.gif","instructionSteps":["背靠墙站立，双脚分开与臀部同宽。","慢慢地将背部滑下墙壁，直到膝盖弯曲成 90 度角。","将右脚抬离地面，并将膝盖靠近胸部。","将右脚放低，将左脚抬离地面，将膝盖靠近胸部。","继续交替抬起右脚和左脚，达到所需的重复次数。"]},{"id":"0627","name":"mixed grip chin-up","nameZh":"混合握距反握引体向上","equipment":"body weight","bodyPart":"back","target":"lats","imagePath":"exercises/images/0627-T8UpLkb.jpg","gifPath":"exercises/videos/0627-T8UpLkb.gif","instructionSteps":["反握（手掌朝向自己）抓住引体向上杆，双手之间的距离略大于肩宽。","悬挂在杠上，双臂完全伸展，双脚离开地面。","调动背部肌肉，将身体拉向杠铃杆，以胸部为主导。","继续拉，直到下巴位于杠铃上方。","在顶部停顿片刻，然后有控制地慢慢将身体放回起始位置。","重复所需的重复次数。"]},{"id":"0628","name":"monster walk","nameZh":"怪物行走","equipment":"body weight","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0628-O95afRA.jpg","gifPath":"exercises/videos/0628-O95afRA.gif","instructionSteps":["在脚踝周围放置一根阻力带。","双脚分开与肩同宽站立，稍微弯曲膝盖。","右脚向一侧迈出一步，保持阻力带的张力。","左脚跟随，向一侧迈步以返回起始位置。","重复所需的重复次数，然后换边。"]},{"id":"0631","name":"muscle up","nameZh":"双力臂","equipment":"body weight","bodyPart":"back","target":"lats","imagePath":"exercises/images/0631-yJUHKTn.jpg","gifPath":"exercises/videos/0631-yJUHKTn.gif","instructionSteps":["首先悬挂在引体向上杆上，手掌背向自己，手臂完全伸展。","启动核心肌群，将身体拉向杠铃杆，以胸部为主导。","当你到达动作的最高点时，改变你的握力，使你的手掌朝向你。","继续将自己向上拉，直到胸部位于杠铃上方并且手臂完全弯曲。","通过慢慢降低自己回到起始位置来反转动作。","重复所需的重复次数。"]},{"id":"0634","name":"negative crunch","nameZh":"负向卷腹","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0634-szIn2UK.jpg","gifPath":"exercises/videos/0634-szIn2UK.gif","instructionSteps":["平躺，膝盖弯曲，双脚平放在地上。","将双手放在脑后，肘部朝外。","收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。","在顶部停顿片刻，然后慢慢将上半身放回起始位置。","重复所需的重复次数。"]},{"id":"0635","name":"oblique crunches floor","nameZh":"腹斜肌卷腹地面","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0635-QUDd8WS.jpg","gifPath":"exercises/videos/0635-QUDd8WS.gif","instructionSteps":["仰卧，膝盖弯曲，双脚平放在地板上。","将双手放在脑后或交叉放在胸前。","收紧腹肌，将肩胛骨抬离地面，将躯干旋转到一侧。","暂停片刻，然后将肩胛骨放回到地板上。","在另一侧重复，每次重复时交替进行。"]},{"id":"0636","name":"olympic barbell hammer curl","nameZh":"奥林匹克杠铃锤式弯举","equipment":"olympic barbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0636-o1ntciW.jpg","gifPath":"exercises/videos/0636-o1ntciW.gif","instructionSteps":["站直，双脚分开与肩同宽，正手握住奥林匹克杠铃。","让杠铃悬挂在大腿前面，手掌与身体保持一臂距离。","保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。","继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气并慢慢开始将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0637","name":"olympic barbell triceps extension","nameZh":"奥林匹克杠铃肱三头肌伸展","equipment":"olympic barbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0637-wu5LXwz.jpg","gifPath":"exercises/videos/0637-wu5LXwz.gif","instructionSteps":["首先，双脚分开与肩同宽站立，并用正手握住杠铃。","将杠铃举过头顶，充分伸展双臂。","保持上臂靠近头部，弯曲肘部，慢慢将杠铃降低到脑后。","暂停片刻，然后将手臂伸回到起始位置。","重复所需的重复次数。"]},{"id":"0638","name":"one arm chin-up","nameZh":"单臂反握引体向上","equipment":"body weight","bodyPart":"back","target":"lats","imagePath":"exercises/images/0638-HjdqmZa.jpg","gifPath":"exercises/videos/0638-HjdqmZa.gif","instructionSteps":["面向引体向上杆站立，双脚分开与肩同宽。","抬起手，用反握方式抓住杠铃，一只手握住杠铃，另一只手握住手腕以提供支撑。","悬挂在杠上，手臂完全伸展，保持身体伸直，核心肌群参与。","弯曲肘部并挤压背部肌肉，将自己拉向杠铃。","继续拉，直到下巴高于杠铃，然后慢慢降低回到起始位置。","重复所需的重复次数，然后换臂重复。"]},{"id":"0639","name":"one arm dip","nameZh":"单臂臂屈伸","equipment":"body weight","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0639-FAoIFMw.jpg","gifPath":"exercises/videos/0639-FAoIFMw.gif","instructionSteps":["背对长凳或椅子站立，双脚分开与肩同宽。","将一只手放在身后的长凳或椅子上，手指指向您的身体。","将双腿向前方伸展，脚跟保持在地面上。","弯曲肘部，将身体放低至地面，使背部靠近长凳或椅子。","在底部停顿片刻，然后用手掌推直手臂，回到起始位置。","重复所需的重复次数，然后换边并用另一只手臂重复。"]},{"id":"0640","name":"one arm slam (with medicine ball)","nameZh":"单臂砸 (带药球)","equipment":"medicine ball","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0640-jCrtE9b.jpg","gifPath":"exercises/videos/0640-jCrtE9b.gif","instructionSteps":["双脚分开与肩同宽站立，一只手将健身球放在腰前。","稍微弯曲膝盖并启动核心。","将健身球举过头顶，充分伸展手臂。","用力将药球摔到地上，用你的核心和肩膀产生力量。","抓住弹起的实心球，然后重复所需的重复次数。"]},{"id":"0641","name":"otis up","nameZh":"奥蒂斯起身","equipment":"weighted","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0641-UVL20oz.jpg","gifPath":"exercises/videos/0641-UVL20oz.gif","instructionSteps":["平躺，膝盖弯曲，双脚平放在地上。","将双手放在脑后，肘部朝外。","收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。","在顶部停顿片刻，然后慢慢将上半身放回起始位置。","重复所需的重复次数。"]},{"id":"0642","name":"outside leg kick push-up","nameZh":"外侧踢腿俯卧撑","equipment":"body weight","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0642-jNU1gFQ.jpg","gifPath":"exercises/videos/0642-jNU1gFQ.gif","instructionSteps":["从俯卧撑位置开始，双手分开略宽于肩宽，双脚并拢。","弯曲肘部，将身体降低到地面，保持背部挺直，核心参与。","当你向后推时，将一条腿踢向一侧，完全伸展并启动臀部。","将腿恢复到起始位置并重复俯卧撑，每次重复时交替腿。","继续交替踢腿和俯卧撑，达到所需的重复次数。"]},{"id":"0643","name":"overhead triceps stretch","nameZh":"过头肱三头肌拉伸","equipment":"body weight","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0643-Z5YStHW.jpg","gifPath":"exercises/videos/0643-Z5YStHW.gif","instructionSteps":["站立或坐直，双脚分开与肩同宽。","将一只手臂伸过头顶，弯曲肘部，使手伸向对面的肩胛骨。","用另一只手轻轻地将伸出的手臂的肘部拉向头部的另一侧，感受三头肌的拉伸。","保持拉伸 15-30 秒，然后放松。","在另一侧重复。"]},{"id":"0648","name":"power clean","nameZh":"高翻","equipment":"barbell","bodyPart":"upper legs","target":"hamstrings","imagePath":"exercises/images/0648-SiWCcTN.jpg","gifPath":"exercises/videos/0648-SiWCcTN.gif","instructionSteps":["首先将杠铃放在你面前的地面上，双脚分开与肩同宽。","弯腰，正手握住杠铃，握距略宽于肩宽。","将杠铃提离地面时，保持背部挺直，挺胸，伸展臀部和膝盖。","当杠铃到达大腿中部时，爆发性地将其向上拉，耸肩并将肘部拉高并向两侧拉。","当杠铃到达最高点时，迅速下降到其下方，旋转肘部，以前蹲姿势将杠铃接在肩膀上。","握住杠铃站起来，充分伸展臀部和膝盖。","将杠铃放回起始位置，在整个运动过程中保持对重量的控制。","重复所需的重复次数。"]},{"id":"0650","name":"pull-in (on stability ball)","nameZh":"内收 (在稳定球)","equipment":"stability ball","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0650-UQr48Oi.jpg","gifPath":"exercises/videos/0650-UQr48Oi.gif","instructionSteps":["首先坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。","将双手放在稳定球的两侧以获得支撑。","收紧腹肌，慢慢向前滚动臀部，使膝盖靠近胸部。","在动作的最高点停顿片刻，然后慢慢将双腿伸展回起始位置。","重复所需的重复次数。"]},{"id":"0651","name":"pull up (neutral grip)","nameZh":"引体向上 (中立握距)","equipment":"body weight","bodyPart":"back","target":"lats","imagePath":"exercises/images/0651-0V2YQjW.jpg","gifPath":"exercises/videos/0651-0V2YQjW.gif","instructionSteps":["用中立握法（手掌相对）悬挂在引体向上杆上，双臂完全伸展。","启动你的核心并将肩胛骨挤压在一起。","弯曲肘部并将肘部向下推向臀部，将身体向上拉向杠铃。","继续拉，直到下巴位于杠铃上方。","在顶部停顿片刻，然后有控制地慢慢将身体放回起始位置。","重复所需的重复次数。"]},{"id":"0652","name":"pull-up","nameZh":"引体向上","equipment":"body weight","bodyPart":"back","target":"lats","imagePath":"exercises/images/0652-lBDjFxJ.jpg","gifPath":"exercises/videos/0652-lBDjFxJ.gif","instructionSteps":["悬挂在引体向上杆上，手掌背向自己，手臂完全伸展。","启动你的核心并将肩胛骨挤压在一起。","弯曲肘部并将胸部拉向杠铃杆，将身体向上拉向杠铃杆。","在动作的最高点暂停，然后慢慢降低身体回到起始位置。","重复所需的重复次数。"]},{"id":"0653","name":"push-up (bosu ball)","nameZh":"俯卧撑 (波速球)","equipment":"bosu ball","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0653-2kr2lWy.jpg","gifPath":"exercises/videos/0653-2kr2lWy.gif","instructionSteps":["将博苏球平放在地上，平面朝上。","将自己置于俯卧撑位置，双手放在博苏球的外边缘。","弯曲肘部，调动核心力量，将身体向博苏球方向降低。","伸展双臂，将自己推回到起始位置。","重复所需的重复次数。"]},{"id":"0655","name":"push-up (on stability ball)","nameZh":"俯卧撑 (在稳定球)","equipment":"stability ball","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0655-Y4BRNQF.jpg","gifPath":"exercises/videos/0655-Y4BRNQF.gif","instructionSteps":["将稳定球放在地上，面朝下，双手放在球上，与肩同宽。","将双腿伸直在身后，用脚趾保持平衡。","弯曲肘部，调动核心力量，将胸部向球方向降低，保持身体呈一条直线。","在底部暂停片刻，然后伸直手臂将自己推回起始位置。","重复所需的重复次数。"]},{"id":"0656","name":"push-up (on stability ball)","nameZh":"俯卧撑 (在稳定球)","equipment":"stability ball","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0656-tgryw5Y.jpg","gifPath":"exercises/videos/0656-tgryw5Y.gif","instructionSteps":["将稳定球放在地上，面朝下，双手放在球上，与肩同宽。","将双腿伸直在身后，用脚趾保持平衡。","弯曲肘部，调动核心力量，将胸部向球方向降低，保持身体呈一条直线。","在底部暂停片刻，然后伸直手臂将自己推回起始位置。","重复所需的重复次数。"]},{"id":"0658","name":"push-up (wall) v. 2","nameZh":"俯卧撑 (墙) 版本 2","equipment":"body weight","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0658-NCmbLCw.jpg","gifPath":"exercises/videos/0658-NCmbLCw.gif","instructionSteps":["面向墙壁站立，距离大约一臂距离。","将双手放在墙上，与肩同高，距离略宽于肩宽。","双脚向后退一步，保持与臀部同宽。","收紧核心肌群，保持身体从头到脚跟呈一条直线。","弯曲肘部，将胸部向墙壁降低，保持身体挺直。","暂停片刻，然后将自己推回到起始位置。","重复所需的重复次数。"]},{"id":"0659","name":"push-up (wall)","nameZh":"俯卧撑 (墙)","equipment":"body weight","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0659-LEH9jxP.jpg","gifPath":"exercises/videos/0659-LEH9jxP.gif","instructionSteps":["面向墙壁站立，距离大约一臂距离。","将双手放在墙上，与肩同高，距离略宽于肩宽。","后退几英尺，保持身体挺直，双脚分开与臀部同宽。","弯曲肘部，将胸部向墙壁降低，保持身体呈一条直线。","推回起始位置，伸直手臂。","重复所需的重复次数。"]},{"id":"0660","name":"push-up close-grip off dumbbell","nameZh":"俯卧撑窄距离哑铃","equipment":"dumbbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0660-KZXAtKQ.jpg","gifPath":"exercises/videos/0660-KZXAtKQ.gif","instructionSteps":["从俯卧撑位置开始，双手并拢，直接放在肩膀下方。","每只手握住一个哑铃，将其放在地上。","弯曲肘部，使肘部靠近身体两侧，将身体降低到地面。","推动手掌以伸展手臂并返回到起始位置。","重复所需的重复次数。"]},{"id":"0661","name":"push-up inside leg kick","nameZh":"俯卧撑内侧腿踢","equipment":"body weight","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0661-0br45wL.jpg","gifPath":"exercises/videos/0661-0br45wL.gif","instructionSteps":["从俯卧撑位置开始，双手分开略宽于肩宽，双脚并拢。","弯曲肘部，将身体降低到地面，保持背部挺直，核心肌群参与。","当你向后推时，将一条腿抬离地面并将其踢向一侧，保持伸直。","将腿放下并重复俯卧撑，然后换另一条腿。","每次重复俯卧撑时继续交替踢腿。"]},{"id":"0662","name":"push-up","nameZh":"俯卧撑","equipment":"body weight","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0662-I4hDWkc.jpg","gifPath":"exercises/videos/0662-I4hDWkc.gif","instructionSteps":["从高位平板支撑开始，双手分开略宽于肩宽，双脚并拢。","弯曲肘部，调动核心力量，将身体压向地面，保持身体呈一条直线。","当你的胸部刚好高于地面时，暂停片刻，然后伸直手臂，将自己推回起始位置。","重复所需的重复次数。"]},{"id":"0663","name":"push-up medicine ball","nameZh":"俯卧撑药球","equipment":"medicine ball","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0663-W8KAlkI.jpg","gifPath":"exercises/videos/0663-W8KAlkI.gif","instructionSteps":["从高平板支撑位置开始，双手放在健身球上，距离与肩同宽。","弯曲肘部，保持背部挺直，调动核心力量，将身体降低至地面。","推动手掌以伸展手臂并返回到起始位置。","重复所需的重复次数。"]},{"id":"0664","name":"push-up to side plank","nameZh":"俯卧撑至侧平板支撑","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0664-KhHJ338.jpg","gifPath":"exercises/videos/0664-KhHJ338.gif","instructionSteps":["从俯卧撑位置开始，双手分开与肩同宽，身体呈一条直线。","弯曲肘部，将身体降低到地面，保持核心参与。","推回到起始位置。","将体重转移到左手上，然后将身体向右旋转，将右臂举向天花板。","保持侧板姿势几秒钟，然后返回到起始位置。","在另一侧重复俯卧撑和侧板支撑。","继续交替进行所需的重复次数。"]},{"id":"0666","name":"raise single arm push-up","nameZh":"抬举单臂俯卧撑","equipment":"body weight","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0666-13TpY4H.jpg","gifPath":"exercises/videos/0666-13TpY4H.gif","instructionSteps":["从俯卧撑位置开始，双手分开略宽于肩宽，双脚并拢。","将一只手臂伸直至一侧，与地面平行。","弯曲肘部，将身体降低到地面，保持背部挺直，核心参与。","推回起始位置，使用胸部肌肉抬起身体。","另一只手臂伸出，重复上述动作。"]},{"id":"0668","name":"rear decline bridge","nameZh":"后下斜桥式","equipment":"body weight","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0668-UpAlold.jpg","gifPath":"exercises/videos/0668-UpAlold.gif","instructionSteps":["仰卧，双脚平放在地上，膝盖弯曲。","将手臂放在身体两侧，手掌朝下。","收紧臀肌和腿筋，将臀部抬离地面，直到身体从膝盖到肩膀形成一条直线。","保持这个姿势几秒钟，然后慢慢地将臀部放回起始位置。","重复所需的重复次数。"]},{"id":"0669","name":"rear deltoid stretch","nameZh":"后三角肌拉伸","equipment":"body weight","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0669-xifhB5W.jpg","gifPath":"exercises/videos/0669-xifhB5W.gif","instructionSteps":["站直，双脚分开与肩同宽。","将右臂伸过胸部，将左手放在右肘上。","轻轻地将右臂拉向左肩，感受右肩的拉伸。","保持拉伸 15-30 秒，然后放松。","在另一侧重复。"]},{"id":"0670","name":"rear pull-up","nameZh":"后引体向上","equipment":"body weight","bodyPart":"back","target":"lats","imagePath":"exercises/images/0670-CbFSYC1.jpg","gifPath":"exercises/videos/0670-CbFSYC1.gif","instructionSteps":["正手握住引体向上杆，握距略宽于肩宽。","悬挂在杠上，双臂完全伸展，身体伸直。","收紧背部肌肉，将身体拉向杠铃杆，保持肘部靠近身体。","继续拉，直到下巴位于杠铃上方。","在顶部停顿片刻，然后慢慢将身体放回起始位置。","重复所需的重复次数。"]},{"id":"0672","name":"reverse dip","nameZh":"反向臂屈伸","equipment":"body weight","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0672-NZ5Qqkz.jpg","gifPath":"exercises/videos/0672-NZ5Qqkz.gif","instructionSteps":["将自己定位在两个双杠之间，双臂完全伸展，身体伸直。","弯曲肘部降低身体，直到上臂与地面平行。","暂停片刻，然后伸直手臂，将自己推回起始位置。","重复所需的重复次数。"]},{"id":"0673","name":"reverse grip machine lat pulldown","nameZh":"反握器械背阔肌下拉","equipment":"leverage machine","bodyPart":"back","target":"lats","imagePath":"exercises/images/0673-ecpY0rH.jpg","gifPath":"exercises/videos/0673-ecpY0rH.gif","instructionSteps":["调整座椅高度，将自己放在机器上，膝盖位于垫子下方，双脚平放在地面上。","反手握住手柄，握距略宽于肩宽。","坐直，挺胸，肩膀向后，保持下背部轻微的拱形。","将手柄向下拉向胸部，将肩胛骨挤压在一起。","在动作底部暂停片刻，然后慢慢松开手柄回到起始位置。","重复所需的重复次数。"]},{"id":"0674","name":"reverse grip pull-up","nameZh":"反握引体向上","equipment":"body weight","bodyPart":"back","target":"lats","imagePath":"exercises/images/0674-YAk5dIw.jpg","gifPath":"exercises/videos/0674-YAk5dIw.gif","instructionSteps":["双手分开与肩同宽，反握抓住引体向上杆。","悬挂在杠上，双臂完全伸展，身体伸直。","调动背部肌肉，将身体拉向杠铃杆，以胸部为主导。","继续拉，直到下巴位于杠铃上方。","在顶部停顿片刻，然后慢慢将身体放回起始位置。","重复所需的重复次数。"]},{"id":"0675","name":"reverse hyper extension (on stability ball)","nameZh":"反向过度伸展伸展 (在稳定球)","equipment":"stability ball","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0675-vM5YS2g.jpg","gifPath":"exercises/videos/0675-vM5YS2g.gif","instructionSteps":["面朝下躺在稳定球上，臀部放在球上，双腿伸直在身后。","将双手放在身前的地面上以保持稳定。","调动臀肌和腿筋，将双腿尽可能高地抬向天花板。","在顶部暂停片刻，然后慢慢将双腿放回起始位置。","重复所需的重复次数。"]},{"id":"0677","name":"ring dips","nameZh":"吊环臂屈伸","equipment":"body weight","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0677-ezTvXcr.jpg","gifPath":"exercises/videos/0677-ezTvXcr.gif","instructionSteps":["首先，将手臂完全伸展，身体伸直，挂在吊环上。","弯曲肘部，降低身体，直到肩膀低于肘部。","伸直手臂，将自己推回起始位置。","重复所需的重复次数。"]},{"id":"0678","name":"rocky pull-up pulldown","nameZh":"洛奇式引体向上下拉","equipment":"body weight","bodyPart":"back","target":"lats","imagePath":"exercises/images/0678-cQ19bBP.jpg","gifPath":"exercises/videos/0678-cQ19bBP.gif","instructionSteps":["站在引体向上杆前，双脚分开与肩同宽。","向上伸手，正手握住杠铃，握距略宽于肩宽。","悬挂在杠上，双臂完全伸展，身体伸直。","调动背部肌肉，将身体拉向杠铃杆，以胸部为主导。","在顶部停顿片刻，然后慢慢将身体放回起始位置。","重复所需的重复次数。"]},{"id":"0680","name":"rope climb","nameZh":"爬绳","equipment":"rope","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0680-yaAxcQr.jpg","gifPath":"exercises/videos/0680-yaAxcQr.gif","instructionSteps":["面向绳子站立，双脚分开与肩同宽。","用双手抓住绳子，手掌朝向自己。","稍微弯曲膝盖并启动核心。","开始通过交替的双手动作将自己拉上绳子。","用双腿协助向上运动。","继续攀爬，直到到达所需的高度或绳索的顶部。","要下降，请在控制下降的同时反转双手的动作。","重复所需的重复次数。"]},{"id":"0687","name":"russian twist","nameZh":"俄罗斯转体","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0687-XVDdcoj.jpg","gifPath":"exercises/videos/0687-XVDdcoj.gif","instructionSteps":["坐在地上，膝盖弯曲，双脚平放在地板上。","稍微向后倾斜，同时保持背部挺直并且核心参与。","如果需要，双手合拢放在胸前或举重物。","将脚抬离地面，在坐骨上保持平衡。","将你的躯干向右扭转，将你的手或重量移向身体的右侧。","暂停片刻，然后将躯干向左扭转，将手或体重移向身体的左侧。","继续交替进行所需的重复次数。"]},{"id":"0688","name":"scapular pull-up","nameZh":"肩胛引体向上","equipment":"body weight","bodyPart":"back","target":"traps","imagePath":"exercises/images/0688-uTBt1HV.jpg","gifPath":"exercises/videos/0688-uTBt1HV.gif","instructionSteps":["首先悬挂在引体向上杆上，手掌背向自己，手臂完全伸展。","通过向下拉和向后拉动肩胛骨来缩回肩胛骨。","启动背部肌肉，将身体拉向杠铃杆，重点是将肩胛骨挤压在一起。","在动作的最高点停顿片刻，然后慢慢降低身体回到起始位置。","重复所需的重复次数。"]},{"id":"0689","name":"seated leg raise","nameZh":"坐姿抬腿","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0689-Hgs6Nl1.jpg","gifPath":"exercises/videos/0689-Hgs6Nl1.gif","instructionSteps":["坐在平坦的长凳上，背部挺直，双脚平放在地面上。","将双手放在长凳两侧以获得支撑。","保持双腿伸直，慢慢将它们抬起到您面前，直到它们与地面平行。","在顶部暂停片刻，然后慢慢将双腿放回起始位置。","重复所需的重复次数。"]},{"id":"0690","name":"seated lower back stretch","nameZh":"坐姿下背拉伸","equipment":"body weight","bodyPart":"back","target":"lats","imagePath":"exercises/images/0690-QFmz6ch.jpg","gifPath":"exercises/videos/0690-QFmz6ch.gif","instructionSteps":["坐在椅子边缘，双脚平放在地面上。","将双手放在大腿上或椅子两侧以获得支撑。","从臀部开始慢慢向前倾斜，保持背部挺直。","感受下背部的拉伸并保持 20-30 秒。","慢慢回到起始位置并重复所需的重复次数。"]},{"id":"0691","name":"seated side crunch (wall)","nameZh":"坐姿侧卷腹 (墙)","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0691-Y9hNPcN.jpg","gifPath":"exercises/videos/0691-Y9hNPcN.gif","instructionSteps":["坐在地板上，背靠墙，双腿在身前伸展。","弯曲膝盖，将双脚平放在地板上，与臀部同宽。","将双手放在脑后，肘部朝外。","收紧腹肌并向一侧倾斜，将肘部靠近臀部。","暂停片刻，然后回到起始位置。","在另一侧重复。","继续交替进行所需的重复次数。"]},{"id":"0696","name":"self assisted inverse leg curl (on floor)","nameZh":"自我辅助反向腿弯举 (在地面)","equipment":"body weight","bodyPart":"upper legs","target":"hamstrings","imagePath":"exercises/images/0696-E4PwJqI.jpg","gifPath":"exercises/videos/0696-E4PwJqI.gif","instructionSteps":["平躺，双腿伸展，双臂放在身体两侧。","弯曲膝盖，将双脚平放在地面上，距离与臀部同宽。","将臀部抬离地面，锻炼臀肌和腿筋。","慢慢地将双腿向臀部弯曲，保持臀部抬起。","在顶部停顿片刻，然后慢慢将双腿伸展回起始位置。","将臀部放回地面。","重复所需的重复次数。"]},{"id":"0697","name":"self assisted inverse leg curl","nameZh":"自我辅助反向腿弯举","equipment":"body weight","bodyPart":"upper legs","target":"hamstrings","imagePath":"exercises/images/0697-GwYwElT.jpg","gifPath":"exercises/videos/0697-GwYwElT.gif","instructionSteps":["平躺在垫子或长凳上，双腿伸展。","将双手放在身体两侧或臀部下方以获得支撑。","弯曲膝盖，将脚抬离地面，将大腿靠近胸部。","在顶部暂停片刻，然后慢慢将双腿放回起始位置。","重复所需的重复次数。"]},{"id":"0699","name":"shoulder tap push-up","nameZh":"肩轻拍俯卧撑","equipment":"body weight","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0699-qEse6fe.jpg","gifPath":"exercises/videos/0699-qEse6fe.gif","instructionSteps":["从高位平板支撑开始，双手分开略宽于肩宽，身体从头到脚跟呈一条直线。","弯曲肘部，使肘部靠近身体两侧，将身体降低到地面。","当你向后推时，将右手抬离地面并轻拍左肩。","将右手放回地面并重复俯卧撑，这次抬起左手并拍打右肩。","每次重复俯卧撑时，继续交替拍肩。","在整个练习过程中保持核心稳定并避免臀部过度旋转。","重复所需的重复次数。"]},{"id":"0705","name":"side bridge v. 2","nameZh":"侧桥版本 2","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0705-RKjH6Lt.jpg","gifPath":"exercises/videos/0705-RKjH6Lt.gif","instructionSteps":["侧躺，双腿伸展并叠放在一起。","将前臂放在肩膀正下方的地面上，肘部弯曲成 90 度角。","启动你的核心并将臀部抬离地面，从头到脚形成一条直线。","保持此位置所需的时间。","将臀部放低至起始位置。","在另一侧重复。"]},{"id":"0709","name":"side hip (on parallel bars)","nameZh":"侧髋 (在双杠)","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0709-jTkSc6o.jpg","gifPath":"exercises/videos/0709-jTkSc6o.gif","instructionSteps":["站在两根平行杠之间，双脚分开与肩同宽。","将双手放在横杆上，将身体抬离地面，用手臂支撑体重。","收紧腹肌，慢慢将双腿向一侧抬起，保持伸直。","在顶部暂停片刻，然后慢慢将双腿放回起始位置。","重复所需的重复次数。"]},{"id":"0710","name":"side hip abduction","nameZh":"侧髋外展","equipment":"body weight","bodyPart":"upper legs","target":"abductors","imagePath":"exercises/images/0710-7WaDzyL.jpg","gifPath":"exercises/videos/0710-7WaDzyL.gif","instructionSteps":["双脚分开与肩同宽站立，双手放在臀部。","将重心转移到一条腿上，并将另一条腿向一侧抬起，保持伸直。","在顶部暂停片刻，然后慢慢将腿放回起始位置。","在另一侧重复。","继续交替进行所需的重复次数。"]},{"id":"0716","name":"side push neck stretch","nameZh":"侧推颈部拉伸","equipment":"body weight","bodyPart":"neck","target":"levator scapulae","imagePath":"exercises/images/0716-oQRJYkC.jpg","gifPath":"exercises/videos/0716-oQRJYkC.gif","instructionSteps":["站直或坐直，肩膀放松。","将头向右倾斜，将右耳靠近右肩。","将右手放在头部左侧，轻轻施加压力以增加拉伸。","保持拉伸 15-30 秒。","在另一侧重复，将头向左倾斜并用左手施加压力。","每侧重复拉伸 2-3 次。"]},{"id":"0717","name":"side push-up","nameZh":"侧俯卧撑","equipment":"body weight","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0717-wpbD28t.jpg","gifPath":"exercises/videos/0717-wpbD28t.gif","instructionSteps":["首先侧躺，双腿伸展并叠放在一起。","将下面的手放在肩膀正下方的地面上，手指指向前方。","用下面的手将身体抬离地面，保持双腿伸直，核心肌群参与。","将上臂伸向天花板，形成从头部到脚后跟的直线。","有控制地降低身体回到起始位置。","重复所需的重复次数，然后换边。"]},{"id":"0720","name":"side-to-side chin","nameZh":"左右下巴","equipment":"body weight","bodyPart":"back","target":"lats","imagePath":"exercises/images/0720-isAAZWA.jpg","gifPath":"exercises/videos/0720-isAAZWA.gif","instructionSteps":["双脚分开与肩同宽站立，膝盖稍微弯曲。","正手握住引体向上杆，双手之间的距离略大于肩宽。","悬挂在杠上，双臂完全伸展，身体放松。","弯曲肘部并将下巴朝向杠铃杆，将自己拉起，同时保持身体挺直。","一旦你的下巴高于杠铃，就将自己放低回到起始位置。","重复所需的重复次数。"]},{"id":"0721","name":"side wrist pull stretch","nameZh":"侧手腕拉拉伸","equipment":"body weight","bodyPart":"lower arms","target":"forearms","imagePath":"exercises/images/0721-UtmIqcI.jpg","gifPath":"exercises/videos/0721-UtmIqcI.gif","instructionSteps":["双脚分开与肩同宽站立，双臂在身前伸展。","将右臂向侧面伸出，与地面平行，手掌朝下。","用左手抓住右手，轻轻地将其拉向身体，感觉右前臂有拉伸感。","保持拉伸 15-30 秒，然后放松。","在另一侧重复。"]},{"id":"0725","name":"single arm push-up","nameZh":"单臂俯卧撑","equipment":"body weight","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0725-MUic5zN.jpg","gifPath":"exercises/videos/0725-MUic5zN.gif","instructionSteps":["从俯卧撑位置开始，双手分开与肩同宽，一只手比另一只手稍宽。","弯曲肘部，保持背部挺直，调动核心力量，将身体降低至地面。","当你降低身体时，将你的重心转移到一侧，并将另一只手臂抬离地面，将其笔直延伸到一侧。","推动胸部和三头肌，将身体抬回到起始位置，同时将伸出的手臂放回地面。","重复该动作，每次重复时交替伸展手臂。"]},{"id":"0727","name":"single leg calf raise (on a dumbbell)","nameZh":"单腿提踵 (在a 哑铃)","equipment":"dumbbell","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/0727-fKZgDEO.jpg","gifPath":"exercises/videos/0727-fKZgDEO.gif","instructionSteps":["双脚分开与臀部同宽站立，一只手握住哑铃。","将一只脚抬离地面并用另一只脚保持平衡。","使用小腿肌肉，慢慢地将脚跟抬高，尽可能高。","在顶部停顿片刻，然后慢慢降低脚跟。","重复所需的重复次数，然后换另一条腿。"]},{"id":"0730","name":"single leg platform slide","nameZh":"单腿平台滑行","equipment":"body weight","bodyPart":"upper legs","target":"hamstrings","imagePath":"exercises/images/0730-LNE3wfo.jpg","gifPath":"exercises/videos/0730-LNE3wfo.gif","instructionSteps":["首先将一只脚站在平台或滑板上。","稍微弯曲膝盖，将脚向后滑动到平台上，伸展腿。","在整个运动过程中保持核心参与并保持笔直姿势。","将脚滑回初始位置，慢慢返回起始位置。","重复该动作达到所需的重复次数，然后换腿。"]},{"id":"0735","name":"sit-up v. 2","nameZh":"仰卧起坐版本 2","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0735-Bn6TXyO.jpg","gifPath":"exercises/videos/0735-Bn6TXyO.gif","instructionSteps":["平躺，膝盖弯曲，双脚平放在地上。","将双手放在脑后，肘部朝外。","收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。","在顶部停顿片刻，然后慢慢将上半身放回起始位置。","重复所需的重复次数。"]},{"id":"0738","name":"sled 45в° calf press","nameZh":"雪橇机 45в° 小腿推举","equipment":"sled machine","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/0738-qCNVnaU.jpg","gifPath":"exercises/videos/0738-qCNVnaU.gif","instructionSteps":["将雪橇机调整至 45 度角。","将脚放在雪橇平台上，脚趾朝前。","伸展脚踝和小腿，将雪橇平台推离您。","在顶部暂停片刻，然后慢慢将雪橇平台放回起始位置。","重复所需的重复次数。"]},{"id":"0739","name":"sled 45в° leg press","nameZh":"腿举","equipment":"sled machine","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0739-10Z2DXU.jpg","gifPath":"exercises/videos/0739-10Z2DXU.gif","instructionSteps":["将雪橇机的座椅和脚踏板调整到舒适的位置。","坐在雪橇机上，背部靠在靠背上，双脚与肩同宽放在踏板上。","握住座椅两侧的把手以保持稳定性。","伸展双腿，将脚踏板推离身体，脚后跟保持在脚踏板上。","继续推动，直到双腿几乎完全伸展，但不要锁住膝盖。","在动作的最高点暂停片刻，然后弯曲膝盖，慢慢地将踏板放回到身体的方向。","重复所需的重复次数。"]},{"id":"0740","name":"sled 45в° leg wide press","nameZh":"雪橇机 45в° 腿宽推举","equipment":"sled machine","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0740-tj41Nu6.jpg","gifPath":"exercises/videos/0740-tj41Nu6.gif","instructionSteps":["将雪橇机调整至 45 度角。","坐在雪橇机上，背部靠在垫子上，双脚放在脚踏平台上。","双脚分开的距离比肩宽。","推动脚部平台以伸展双腿并伸直膝盖。","动作结束时暂停片刻，然后慢慢弯曲膝盖回到起始位置。","重复所需的重复次数。"]},{"id":"0741","name":"sled closer hack squat","nameZh":"雪橇机窄距哈克深蹲","equipment":"sled machine","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0741-gf3ZjB9.jpg","gifPath":"exercises/videos/0741-gf3ZjB9.gif","instructionSteps":["将雪橇机调整到舒适的重量，并将背部靠在垫子上。","将双脚分开与肩同宽放在平台上，脚趾稍微向外。","握住机器两侧的手柄以保持稳定性。","弯曲膝盖和臀部，调动核心力量，慢慢降低身体，保持背部挺直。","继续降低，直到大腿与地面平行或略低于地面。","在底部停顿片刻，然后用脚跟推动双腿并返回到起始位置。","重复所需的重复次数。"]},{"id":"0742","name":"sled forward angled calf raise","nameZh":"雪橇机前倾提踵","equipment":"sled machine","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/0742-XDOiFns.jpg","gifPath":"exercises/videos/0742-XDOiFns.gif","instructionSteps":["将雪橇机调整到舒适的重量，然后将自己放在机器上，脚趾放在平台上，脚后跟悬空。","将手放在机器的手柄或侧面上以获得支撑。","收紧小腿，慢慢地尽可能高地抬起脚后跟，克服雪橇的阻力。","在动作的最高点暂停片刻，然后慢慢降低脚跟回到起始位置。","重复所需的重复次数。"]},{"id":"0743","name":"sled hack squat","nameZh":"雪橇机哈克深蹲","equipment":"sled machine","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0743-Qa55kX1.jpg","gifPath":"exercises/videos/0743-Qa55kX1.gif","instructionSteps":["将雪橇机调整到适合您身高的舒适位置。","双脚与肩同宽站立在平台上，脚趾稍微向外。","握住手柄或杆以保持稳定性。","弯曲膝盖和臀部，降低身体，保持背部挺直，挺胸。","继续降低，直到大腿与地面平行或略低于地面。","暂停片刻，然后用脚后跟将身体抬回到起始位置。","重复所需的重复次数。"]},{"id":"0744","name":"sled lying squat","nameZh":"雪橇机仰卧深蹲","equipment":"sled machine","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0744-9n2149Z.jpg","gifPath":"exercises/videos/0744-9n2149Z.gif","instructionSteps":["将雪橇机调整至舒适的重量。","仰卧在雪橇机上，双脚放在踏板上。","双脚分开与肩同宽，并稍微向外倾斜。","握住雪橇机的手柄以保持稳定。","调动你的臀肌和核心肌肉。","脚后跟用力，双腿伸直，抬起雪橇。","弯曲膝盖和臀部，将雪橇放回原位。","重复所需的重复次数。"]},{"id":"0746","name":"smith back shrug","nameZh":"史密斯背部耸肩","equipment":"smith machine","bodyPart":"back","target":"traps","imagePath":"exercises/images/0746-MzNnwx9.jpg","gifPath":"exercises/videos/0746-MzNnwx9.gif","instructionSteps":["双脚分开与肩同宽站立，膝盖稍微弯曲。","正手握住杠铃，双手间距略宽于肩宽。","保持手臂伸直，让杠铃挂在大腿前面。","将肩膀向耳朵方向伸直，挤压斜方肌顶部。","保持一会儿，然后将肩膀放回起始位置。","重复所需的重复次数。"]},{"id":"0747","name":"smith behind neck press","nameZh":"史密斯颈后推举","equipment":"smith machine","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0747-Gpn4ADc.jpg","gifPath":"exercises/videos/0747-Gpn4ADc.gif","instructionSteps":["调整史密斯机的座椅高度，使杠铃与肩部齐平。","双脚分开与肩同宽站立，膝盖稍微弯曲。","正手握住杠铃，握距略宽于肩宽。","将杠铃从架子上抬起并向后退一步，保持稳定的姿势。","将杠铃降低到颈后，保持肘部向前。","将杠铃向上推过头顶，直到双臂完全伸展。","在顶部暂停片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0748","name":"smith bench press","nameZh":"史密斯卧推","equipment":"smith machine","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0748-trqKQv2.jpg","gifPath":"exercises/videos/0748-trqKQv2.gif","instructionSteps":["将史密斯机杆的高度调整至胸部水平。","平躺在长凳上，双脚牢牢踩在地上。","正手握住杠铃，握距略宽于肩宽。","松开杠铃并将其向胸部降低，保持肘部内收。","当杠铃接触到你的胸部时暂停片刻。","将杠铃推回到起始位置，完全伸展双臂。","重复所需的重复次数。"]},{"id":"0749","name":"smith bent knee good morning","nameZh":"史密斯屈膝早安式","equipment":"smith machine","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0749-1bQkKZK.jpg","gifPath":"exercises/videos/0749-1bQkKZK.gif","instructionSteps":["首先站立，双脚分开与肩同宽，脚趾指向前方。","将杠铃放在上背部，放在斜方肌上。","稍微弯曲膝盖，髋部向前转动，保持背部挺直。","降低躯干直到与地面平行，感觉腿筋被拉伸。","启动臀肌和腿筋，将躯干抬回到起始位置。","重复所需的重复次数。"]},{"id":"0750","name":"smith chair squat","nameZh":"史密斯椅子深蹲","equipment":"smith machine","bodyPart":"upper legs","target":"quads","imagePath":"exercises/images/0750-Gu2rNJd.jpg","gifPath":"exercises/videos/0750-Gu2rNJd.gif","instructionSteps":["将史密斯机杆的高度调整到舒适的位置。","站立，双脚分开与肩同宽，脚趾稍微向外。","将杠铃放在上背部，放在斜方肌上。","通过弯曲膝盖和臀部慢慢降低身体，收紧核心并保持挺胸。","继续降低，直到大腿与地面平行，或者尽可能低。","暂停片刻，然后用力推动脚后跟，回到起始位置。","重复所需的重复次数。"]},{"id":"0751","name":"smith close-grip bench press","nameZh":"史密斯窄距卧推","equipment":"smith machine","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0751-WcHl7ru.jpg","gifPath":"exercises/videos/0751-WcHl7ru.gif","instructionSteps":["调整座椅高度，将自己放在长凳上，双脚平放在地面上。","紧紧握住杠铃，握距略窄于肩宽。","将杠铃向胸部降低，保持肘部靠近身体。","在底部停顿片刻，然后将杠铃推回到起始位置。","重复所需的重复次数。"]},{"id":"0752","name":"smith deadlift","nameZh":"史密斯硬拉","equipment":"smith machine","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0752-UfePqpx.jpg","gifPath":"exercises/videos/0752-UfePqpx.gif","instructionSteps":["将史密斯机设置为与臀部高度相同的杠铃。","双脚分开与肩同宽站立，脚趾稍微向外。","弯曲臀部和膝盖，保持背部挺直，挺胸，正手握住杠铃，握距略宽于肩宽。","伸展臀部和膝盖，调动核心力量并举起杠铃，保持杠铃靠近身体。","站直，充分伸展臀部和膝盖。","通过弯曲臀部和膝盖来降低杠铃，保持控制并保持背部挺直。","重复所需的重复次数。"]},{"id":"0753","name":"smith decline bench press","nameZh":"史密斯下斜卧推","equipment":"smith machine","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0753-ETZfAbZ.jpg","gifPath":"exercises/videos/0753-ETZfAbZ.gif","instructionSteps":["将下斜凳调整至所需角度。","躺在长凳上，双脚固定在脚垫下。","正手握住杠铃，握距略宽于肩宽。","松开杠铃，慢慢将其降低到胸部，保持肘部内收。","在底部停顿片刻，然后将杠铃推回到起始位置。","重复所需的重复次数。"]},{"id":"0754","name":"smith decline reverse-grip press","nameZh":"史密斯下斜反向-握推举","equipment":"smith machine","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0754-MY9P1WA.jpg","gifPath":"exercises/videos/0754-MY9P1WA.gif","instructionSteps":["将史密斯机调整至下降位置。","躺在长凳上，双脚固定在脚垫下。","反握抓住杠铃，双手分开略宽于肩宽。","松开杠铃并将其向胸部降低，保持肘部内收。","在底部停顿片刻，然后将杠铃推回到起始位置。","重复所需的重复次数。"]},{"id":"0755","name":"smith hack squat","nameZh":"史密斯哈克深蹲","equipment":"smith machine","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0755-ZuPXtCK.jpg","gifPath":"exercises/videos/0755-ZuPXtCK.gif","instructionSteps":["将史密斯机上的杠铃调整到适合您身体的高度。","双脚分开与肩同宽站立，脚趾稍微向外。","将自己置于杠铃下方，将其放在斜方肌上部和肩膀上。","正手握住杠铃，握距略宽于肩宽。","当你打开杠铃时，启动你的核心并保持挺胸。","后退一步，双脚分开的距离略大于肩宽。","弯曲膝盖，降低身体，保持挺胸、背部挺直。","继续下降，直到大腿与地面平行或略低于地面。","在底部停顿片刻，然后推动脚后跟回到起始位置。","重复所需的重复次数。"]},{"id":"0756","name":"smith hip raise","nameZh":"史密斯髋部上提","equipment":"smith machine","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0756-CqhoytW.jpg","gifPath":"exercises/videos/0756-CqhoytW.gif","instructionSteps":["将自己放在史密斯机上，背部靠在垫子上，双脚分开与肩同宽。","将双手放在杠铃上，距离略宽于肩宽。","启动你的核心肌群和臀大肌，然后通过脚后跟将臀部抬离地面。","继续提升，直到身体从膝盖到肩膀形成一条直线。","在顶部保持片刻，然后慢慢将臀部放回起始位置。","重复所需的重复次数。"]},{"id":"0757","name":"smith incline bench press","nameZh":"史密斯上斜卧推","equipment":"smith machine","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0757-5v7KYld.jpg","gifPath":"exercises/videos/0757-5v7KYld.gif","instructionSteps":["将长凳调整至 30-45 度倾斜。","坐在长凳上，背部平放在垫子上，双脚牢牢踩在地上。","正手握住杠铃，握距略宽于肩宽。","松开杠铃，慢慢地将其降低到上胸部，保持肘部稍微内收。","在底部停顿片刻，然后将杠铃推回起始位置，充分伸展双臂。","重复所需的重复次数。"]},{"id":"0758","name":"smith incline reverse-grip press","nameZh":"史密斯上斜反向-握推举","equipment":"smith machine","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0758-78VqWQK.jpg","gifPath":"exercises/videos/0758-78VqWQK.gif","instructionSteps":["将史密斯机的座椅调整到舒适的倾斜角度。","坐在机器上，背部靠在垫子上，双脚平放在地面上。","正手握住杠铃，握距略宽于肩宽。","松开杠铃并将其缓慢降低至胸部，同时保持肘部内收。","当杠铃位于胸部正上方时，暂停片刻。","将杠铃推回到起始位置，完全伸展双臂。","重复所需的重复次数。"]},{"id":"0759","name":"smith incline shoulder raises","nameZh":"史密斯上斜肩部抬举s","equipment":"smith machine","bodyPart":"chest","target":"serratus anterior","imagePath":"exercises/images/0759-ayAHcEm.jpg","gifPath":"exercises/videos/0759-ayAHcEm.gif","instructionSteps":["将史密斯机调整至倾斜位置。","面向机器站立，双脚分开与肩同宽。","正手握住杠铃，握距略宽于肩宽。","保持背部挺直，核心参与。","将杠铃举向天花板，用肘部引导。","在顶部停顿片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0760","name":"smith leg press","nameZh":"史密斯腿举","equipment":"smith machine","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0760-7zdxRTl.jpg","gifPath":"exercises/videos/0760-7zdxRTl.gif","instructionSteps":["将史密斯机的座椅和脚踏板调整到舒适的位置。","坐在机器上，背部靠在靠背上，双脚与肩同宽放在踏板上。","抓住机器的手柄或侧面以保持稳定性。","伸展双腿，使背部紧靠靠背，将脚踏板推离您。","在完全伸展的位置暂停片刻。","慢慢弯曲膝盖，将脚踏板向您的方向放低，回到起始位置。","重复所需的重复次数。"]},{"id":"0761","name":"smith narrow row","nameZh":"史密斯窄划船","equipment":"smith machine","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0761-JGKowMS.jpg","gifPath":"exercises/videos/0761-JGKowMS.gif","instructionSteps":["调整座椅高度并将自己放在机器上，双脚平放在地板上。","正手握住手柄，握距略窄于肩宽。","当您将手柄拉向身体时，保持背部挺直，挺胸，将肩胛骨挤压在一起。","在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。","重复所需的重复次数。"]},{"id":"0762","name":"smith rear delt row","nameZh":"史密斯后三角肌划船","equipment":"smith machine","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0762-nFUwqG6.jpg","gifPath":"exercises/videos/0762-nFUwqG6.gif","instructionSteps":["调整座椅高度，将自己放在机器上，胸部靠在垫子上，双脚平放在地面上。","正手握住手柄，握距略宽于肩宽。","将手柄拉向胸部，将肩胛骨挤压在一起，保持背部挺直，核心肌群参与。","在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。","重复所需的重复次数。"]},{"id":"0763","name":"smith reverse calf raises","nameZh":"史密斯反向提踵s","equipment":"smith machine","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/0763-ywaNfuh.jpg","gifPath":"exercises/videos/0763-ywaNfuh.gif","instructionSteps":["将史密斯机杆调整到略低于肩膀的高度。","面向杠铃站立，双脚分开与臀部同宽，脚趾向前。","将脚掌放在台阶或平台的边缘，脚后跟悬空。","握住杠铃以提供支撑，保持背部挺直，核心肌群参与。","尽可能高地抬高脚后跟，将身体重量转移到脚掌上。","在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。","重复所需的重复次数。"]},{"id":"0764","name":"smith reverse-grip press","nameZh":"史密斯反向-握推举","equipment":"smith machine","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0764-zK8Fu1W.jpg","gifPath":"exercises/videos/0764-zK8Fu1W.gif","instructionSteps":["将史密斯机杆的高度调整至胸部水平。","面向杠铃站立，双脚分开与肩同宽。","正手握住杠铃，双手距离略宽于肩宽。","退后一步，膝盖稍微弯曲。","在整个练习过程中保持挺胸并保持核心参与。","将杠铃向胸部方向降低，保持肘部内收。","在底部暂停片刻，然后将杠铃推回到起始位置。","重复所需的重复次数。"]},{"id":"0765","name":"smith seated shoulder press","nameZh":"史密斯坐姿肩推","equipment":"smith machine","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0765-xUwnBMT.jpg","gifPath":"exercises/videos/0765-xUwnBMT.gif","instructionSteps":["调整座椅高度，使手柄与肩部齐平。","坐在机器上，背部靠在垫子上，双脚平放在地板上。","正手握住手柄，将其提离支撑物，充分伸展双臂。","将手柄降低至肩部水平，保持肘部稍微弯曲。","将手柄向上推过头顶，直到手臂完全伸展。","在顶部暂停片刻，然后慢慢将手柄放回至肩部水平。","重复所需的重复次数。"]},{"id":"0766","name":"smith shoulder press","nameZh":"史密斯肩推","equipment":"smith machine","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0766-903mzG8.jpg","gifPath":"exercises/videos/0766-903mzG8.gif","instructionSteps":["调整座椅高度，将自己放在史密斯机上，双脚分开与肩同宽。","正手握住杠铃，握距略宽于肩宽。","将杠铃从架子上提起，并将其置于与肩同高的位置，肘部弯曲，手掌朝前。","向上推杠铃，直到手臂完全伸过头顶。","在顶部暂停片刻，然后慢慢将杠铃放回至肩部水平。","重复所需的重复次数。"]},{"id":"0767","name":"smith shrug","nameZh":"史密斯耸肩","equipment":"smith machine","bodyPart":"back","target":"traps","imagePath":"exercises/images/0767-OUQ0ZyW.jpg","gifPath":"exercises/videos/0767-OUQ0ZyW.gif","instructionSteps":["双脚分开与肩同宽站立，膝盖稍微弯曲。","正手握住杠铃，双手间距略宽于肩宽。","保持双臂伸直，肩膀放松。","将肩膀向耳朵方向抬起，在顶部挤压斜方肌。","保持一会儿，然后慢慢将肩膀放回起始位置。","重复所需的重复次数。"]},{"id":"0768","name":"smith single leg split squat","nameZh":"史密斯单腿分腿深蹲","equipment":"smith machine","bodyPart":"upper legs","target":"quads","imagePath":"exercises/images/0768-wWFspEi.jpg","gifPath":"exercises/videos/0768-wWFspEi.gif","instructionSteps":["站在史密斯机前，双脚分开与肩同宽。","将一只脚放在身后的长凳或台阶上，脚趾向前。","握住史密斯机杆以保持稳定性。","弯曲前膝盖，将身体降低到弓步位置，保持背部挺直。","在底部停顿片刻，然后推动前脚跟回到起始位置。","重复所需的重复次数，然后换腿。"]},{"id":"0769","name":"smith sprint lunge","nameZh":"史密斯冲刺弓步","equipment":"smith machine","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0769-HsjbB1z.jpg","gifPath":"exercises/videos/0769-HsjbB1z.gif","instructionSteps":["将杠铃置于臀部高度的史密斯机上。","背对机器站立，双脚与肩同宽。","右脚向后退一步，将其放在杠铃上，将脚尖放在杠上。","弯曲左膝，将身体降低到弓步位置，保持背部挺直。","推动左脚跟返回到起始位置。","在另一侧重复，左脚向后退一步。","继续交替进行所需的重复次数。"]},{"id":"0770","name":"smith squat","nameZh":"史密斯深蹲","equipment":"smith machine","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0770-jFtipLl.jpg","gifPath":"exercises/videos/0770-jFtipLl.gif","instructionSteps":["将史密斯机和杠铃设置在适合深蹲的高度。","站立，双脚分开与肩同宽，脚趾稍微向外。","将自己置于杠铃下方，将其放在斜方肌上部和肩膀上。","宽握距握住杠铃，握距略宽于肩宽。","启动你的核心并打开杠铃，后退以清理架子。","保持胸部挺直，背部挺直，通过弯曲臀部和膝盖开始深蹲。","降低身体，直到大腿与地面平行或稍低于地面。","在底部停顿片刻，然后用脚后跟恢复到起始位置。","重复所需的重复次数。"]},{"id":"0771","name":"smith standing back wrist curl","nameZh":"史密斯站姿背部手腕弯举","equipment":"smith machine","bodyPart":"lower arms","target":"forearms","imagePath":"exercises/images/0771-hfmQ0Tz.jpg","gifPath":"exercises/videos/0771-hfmQ0Tz.gif","instructionSteps":["面对史密斯机站立，双脚与肩同宽。","正手握住杠铃，双手与肩同宽。","保持背部挺直，肘部靠近身体。","慢慢向上弯曲手腕，将杠铃拉向身体。","在顶部停顿片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0772","name":"smith standing behind head military press","nameZh":"史密斯站姿头后军事推举","equipment":"smith machine","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0772-ht8xDrP.jpg","gifPath":"exercises/videos/0772-ht8xDrP.gif","instructionSteps":["调整史密斯机的座椅高度，使杠铃与肩部齐平。","双脚分开与肩同宽站立，膝盖稍微弯曲。","正手握住杠铃，握距略宽于肩宽。","将杠铃从架子上抬起并向后退一步，保持稳定的姿势。","将杠铃放在脑后，放在斜方肌上部。","在整个练习过程中保持核心收紧并抬起胸部。","伸展双臂，完全伸直，将杠铃推过头顶。","在动作的最高点稍作停顿，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0773","name":"smith standing leg calf raise","nameZh":"史密斯站姿腿提踵","equipment":"smith machine","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/0773-6MaEjVA.jpg","gifPath":"exercises/videos/0773-6MaEjVA.gif","instructionSteps":["将史密斯机杆调整到一个高度，使您能够双脚平放在地面上且肩膀位于杆下方。","将自己置于杠铃下方，双脚分开与肩同宽，脚趾向前。","将双手放在横杆上以保持稳定。","收紧小腿，慢慢将脚跟抬离地面，将身体抬起到脚趾上。","在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。","重复所需的重复次数。"]},{"id":"0774","name":"smith standing military press","nameZh":"史密斯站姿军事推举","equipment":"smith machine","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0774-jjUPrze.jpg","gifPath":"exercises/videos/0774-jjUPrze.gif","instructionSteps":["双脚分开与肩同宽站立，膝盖稍微弯曲。","正手握住杠铃，握距略宽于肩宽。","将杠铃从架子上提起，并将其降至与肩同高，手掌朝前。","向上推杠铃，直到手臂完全伸过头顶。","在顶部停顿片刻，然后慢慢将杠铃放回至肩部水平。","重复所需的重复次数。"]},{"id":"0775","name":"smith upright row","nameZh":"史密斯直立划船","equipment":"smith machine","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0775-1DN3iz4.jpg","gifPath":"exercises/videos/0775-1DN3iz4.gif","instructionSteps":["双脚分开与肩同宽站立，面向史密斯机。","正手握住杠铃，双手间距略宽于肩宽。","保持背部挺直，核心肌群参与。","将杠铃拉向下巴，用肘部引导。","在顶部停顿片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0776","name":"snatch pull","nameZh":"抓举拉","equipment":"barbell","bodyPart":"upper legs","target":"quads","imagePath":"exercises/images/0776-dG5Smob.jpg","gifPath":"exercises/videos/0776-dG5Smob.gif","instructionSteps":["双脚分开与肩同宽站立，杠铃放在你面前的地面上。","弯曲膝盖并以臀部为铰链，降低至下蹲位置，用正手握住杠铃。","当你通过脚后跟将杠铃抬离地面时，保持背部挺直，挺胸，伸展臀部和膝盖。","当杠铃到达臀部水平时，爆发性地将其向上拉，耸肩并将肘部向两侧拉高。","当杠铃到达最高点时，迅速落到杠铃下方，将自己拉成深蹲位置。","双臂完全伸展，膝盖弯曲，将杠铃举过头顶。","伸展臀部和膝盖站起来，将杠铃保持在头顶上方。","通过反向运动将杠铃降低回起始位置。","重复所需的重复次数。"]},{"id":"0777","name":"spell caster","nameZh":"咒术师","equipment":"dumbbell","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0777-p9cCe2r.jpg","gifPath":"exercises/videos/0777-p9cCe2r.gif","instructionSteps":["双脚分开与肩同宽站立，一只手握住哑铃。","稍微弯曲膝盖，腰部向前转动，保持背部挺直。","将哑铃伸向另一只脚的手臂，同时旋转躯干。","返回起始位置并在另一侧重复。","继续交替进行所需的重复次数。"]},{"id":"0778","name":"spider crawl push up","nameZh":"蜘蛛爬行俯卧撑","equipment":"body weight","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0778-P9GFBME.jpg","gifPath":"exercises/videos/0778-P9GFBME.gif","instructionSteps":["从俯卧撑位置开始，双手分开略宽于肩宽，双脚并拢。","将右膝靠近右肘，使其离开地面。","当您将右膝向后拉时，同时弯曲肘部将身体降低到地面。","推回起始位置，然后将左膝朝向左肘重复此动作。","继续交替进行所需的重复次数。"]},{"id":"0786","name":"squat jerk","nameZh":"深蹲挺举","equipment":"barbell","bodyPart":"upper legs","target":"quads","imagePath":"exercises/images/0786-IMRsOCn.jpg","gifPath":"exercises/videos/0786-IMRsOCn.gif","instructionSteps":["首先将杠铃放在肩膀上，双脚分开与肩同宽。","将身体降低至蹲姿，保持挺胸，膝盖位于脚趾上方。","当你到达深蹲底部时，爆发性地用腿发力，并将杠铃推过头顶。","当杠铃到达最高点时，迅速落入分体位置，一脚向前，一脚向后。","双臂完全伸展，后膝盖稍微接触地面，将杠铃举过头顶。","从分开的位置站起来，将双脚重新并拢。","将杠铃放回肩膀处，然后重复所需的重复次数。"]},{"id":"0788","name":"standing behind neck press","nameZh":"站姿颈后推举","equipment":"barbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0788-xDh0lJr.jpg","gifPath":"exercises/videos/0788-xDh0lJr.gif","instructionSteps":["双脚分开与肩同宽站立，用正手握法将杠铃握在颈后。","保持背部挺直，核心参与。","伸展手臂，充分伸展肘部，将杠铃推过头顶。","在顶部停顿片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0794","name":"standing lateral stretch","nameZh":"站姿侧向拉伸","equipment":"body weight","bodyPart":"back","target":"lats","imagePath":"exercises/images/0794-1jXLYEw.jpg","gifPath":"exercises/videos/0794-1jXLYEw.gif","instructionSteps":["双脚分开与肩同宽站立，膝盖稍微弯曲。","将双臂伸直至两侧，与地面平行。","慢慢将上半身向一侧倾斜，感觉侧面和背阔肌有拉伸感。","保持拉伸 15-30 秒。","返回起始位置并在另一侧重复。","重复所需的重复次数。"]},{"id":"0795","name":"standing single leg curl","nameZh":"站姿单腿弯举","equipment":"body weight","bodyPart":"upper legs","target":"hamstrings","imagePath":"exercises/images/0795-C5jncD2.jpg","gifPath":"exercises/videos/0795-C5jncD2.gif","instructionSteps":["站立，双脚分开与臀部同宽，双手放在臀部。","将体重转移到左腿上，将右脚抬离地面，弯曲膝盖。","慢慢地将右脚跟卷向臀部，挤压腿筋。","在顶部暂停片刻，然后慢慢将右脚放回起始位置。","重复所需的重复次数，然后换腿。"]},{"id":"0796","name":"standing wheel rollerout","nameZh":"站姿健腹轮滚动","equipment":"wheel roller","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0796-KtRomty.jpg","gifPath":"exercises/videos/0796-KtRomty.gif","instructionSteps":["首先，站直，双脚分开与肩同宽，滚轮位于您的前方。","弯腰，慢慢向前滚动轮子，保持背部挺直，核心肌群参与。","继续向前滚动，直到感觉到腹肌拉伸并且身体尽可能伸展。","暂停片刻，然后慢慢地将轮子向身体方向滚动，回到起始位置。","重复所需的重复次数。"]},{"id":"0803","name":"superman push-up","nameZh":"超人式俯卧撑","equipment":"body weight","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0803-4GqRrAk.jpg","gifPath":"exercises/videos/0803-4GqRrAk.gif","instructionSteps":["从高位平板支撑开始，双手分开略宽于肩宽，双脚并拢。","收紧核心，将身体降低到地面，保持肘部靠近身体两侧。","当你降低身体时，同时将右臂和左腿抬离地面，笔直向外伸展。","在顶部暂停片刻，然后放下手臂和腿，同时将自己推回起始位置。","重复该动作，这次抬起左臂和右腿。","继续交替进行所需的重复次数。"]},{"id":"0805","name":"suspended abdominal fallout","nameZh":"悬吊腹部下落","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0805-X3TCNEU.jpg","gifPath":"exercises/videos/0805-X3TCNEU.gif","instructionSteps":["将悬挂训练器连接到高锚点并将带子调整至腰部高度。","背对锚点站立，并握住手柄，双臂向前伸展。","腰部向前倾，保持身体挺直，核心肌群参与。","尽可能降低身体，同时保持腹肌的控制和紧张。","在底部停顿片刻，然后慢慢抬起身体回到起始位置。","重复所需的重复次数。"]},{"id":"0806","name":"suspended push-up","nameZh":"悬吊俯卧撑","equipment":"body weight","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0806-IaGQCrC.jpg","gifPath":"exercises/videos/0806-IaGQCrC.gif","instructionSteps":["找到一个悬挂训练器并将其调整到合适的高度。","背对锚点站立，并用正手握住手柄。","双脚向前走，身体向前倾斜，直到悬架训练器支撑您的体重。","保持身体从头到脚跟伸直，核心部位收紧，胸部朝手柄方向降低。","推动你的胸部和手臂回到起始位置。","重复所需的重复次数。"]},{"id":"0807","name":"suspended reverse crunch","nameZh":"悬吊反向卷腹","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0807-R1WYG5D.jpg","gifPath":"exercises/videos/0807-R1WYG5D.gif","instructionSteps":["悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。","收紧核心肌群，将膝盖抬向胸部，将骨盆卷向胸腔。","在顶部暂停片刻，然后慢慢将膝盖放回起始位置。","重复所需的重复次数。"]},{"id":"0808","name":"suspended row","nameZh":"悬吊划船","equipment":"body weight","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0808-4OaumBr.jpg","gifPath":"exercises/videos/0808-4OaumBr.gif","instructionSteps":["将悬挂训练器设置在适当的高度。","面向锚点站立，双脚分开与肩同宽。","正手握住手柄，手掌相对。","向后倾斜，保持身体挺直，脚后跟着地。","将胸部拉向手柄，将肩胛骨挤压在一起。","在顶部停顿片刻，然后慢慢降低回到起始位置。","重复所需的重复次数。"]},{"id":"0809","name":"suspended split squat","nameZh":"悬吊分腿深蹲","equipment":"body weight","bodyPart":"upper legs","target":"quads","imagePath":"exercises/images/0809-QpXqiq8.jpg","gifPath":"exercises/videos/0809-QpXqiq8.gif","instructionSteps":["背对悬吊训练器站立，双脚与肩同宽。","向前伸展一条腿，将脚背放在悬吊训练器的脚托中。","弯曲站立的腿，将身体降低到弓步位置，保持胸部向上，膝盖与脚趾对齐。","推动脚后跟返回到起始位置。","重复所需的重复次数，然后换腿。"]},{"id":"0811","name":"trap bar deadlift","nameZh":"六角杠铃硬拉","equipment":"trap bar","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0811-jQGwmxN.jpg","gifPath":"exercises/videos/0811-jQGwmxN.gif","instructionSteps":["双脚分开与肩同宽站立，将陷阱杆放在你面前的地面上。","弯曲臀部和膝盖，降低身体高度，并用正手握住陷阱杆的手柄。","当你开始通过伸展臀部和膝盖将陷阱杆抬离地面时，保持背部挺直，挺胸。","当你举起时，专注于通过脚后跟发力，并在运动的最高点挤压臀部。","弯曲臀部和膝盖，将陷阱杆放回地面，在整个运动过程中保持背部挺直。","重复所需的重复次数。"]},{"id":"0812","name":"triceps dip (bench leg)","nameZh":"肱三头肌臂屈伸 (凳腿)","equipment":"body weight","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0812-VuoerH0.jpg","gifPath":"exercises/videos/0812-VuoerH0.gif","instructionSteps":["坐在长凳边缘，双手抓住边缘，手指指向前方。","双脚向前走，将臀部滑离长凳，然后伸直手臂。","弯曲肘部，将身体放低至地面，保持背部靠近长凳。","推动手掌以伸直手臂并返回到起始位置。","重复所需的重复次数。"]},{"id":"0813","name":"triceps dip (between benches)","nameZh":"肱三头肌臂屈伸 (凳间)","equipment":"body weight","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0813-Wgbn9qo.jpg","gifPath":"exercises/videos/0813-Wgbn9qo.gif","instructionSteps":["坐在长凳上，双手抓住长凳边缘，手指指向前方。","将臀部滑离长凳，用手支撑体重。","弯曲肘部，将身体放低至地面，保持背部靠近长凳。","在底部暂停片刻，然后将自己推回到起始位置。","重复所需的重复次数。"]},{"id":"0814","name":"triceps dip","nameZh":"肱三头肌臂屈伸","equipment":"body weight","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0814-X6C6i5Y.jpg","gifPath":"exercises/videos/0814-X6C6i5Y.gif","instructionSteps":["坐在长凳或椅子的边缘，双手抓住边缘，手指指向前方。","将臀部滑离长凳，用手支撑体重。","弯曲肘部，将身体放低至地面，保持背部靠近长凳。","在底部暂停片刻，然后将自己推回到起始位置。","重复所需的重复次数。"]},{"id":"0815","name":"triceps dips floor","nameZh":"肱三头肌臂屈伸s 地面","equipment":"body weight","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0815-7aVz15j.jpg","gifPath":"exercises/videos/0815-7aVz15j.gif","instructionSteps":["坐在椅子或长凳的边缘，双手放在臀部旁边，手指指向前方。","将你的屁股从椅子前面滑下来，双腿伸到你面前。","伸直手臂，保持肘部稍微弯曲，以保持三头肌和肘关节的张力。","慢慢弯曲你的肘部，将你的身体向地板降低，直到你的肘部成大约 90 度角。","一旦到达动作的底部，向下压入椅子以伸直肘部，返回到起始位置。","重复所需的重复次数。"]},{"id":"0816","name":"triceps press","nameZh":"肱三头肌推举","equipment":"body weight","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0816-fSrPP6B.jpg","gifPath":"exercises/videos/0816-fSrPP6B.gif","instructionSteps":["双脚分开与肩同宽站立，膝盖稍微弯曲。","将双臂伸直在身前，与地面平行。","弯曲肘部，将身体放低至地面，保持上臂靠近身体两侧。","在底部暂停片刻，然后将自己推回到起始位置。","重复所需的重复次数。"]},{"id":"0817","name":"triceps stretch","nameZh":"肱三头肌拉伸","equipment":"body weight","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0817-uOV3Itw.jpg","gifPath":"exercises/videos/0817-uOV3Itw.gif","instructionSteps":["站立或坐直，背部挺直。","将一只手臂伸过头顶，肘部弯曲。","将另一只手放在弯曲的肘部上，然后轻轻地将其拉向头部。","保持拉伸 15-30 秒，感受三头肌的轻微拉伸。","松开拉伸并在另一只手臂上重复。"]},{"id":"0818","name":"twin handle parallel grip lat pulldown","nameZh":"双把手平行握距背阔肌下拉","equipment":"cable","bodyPart":"back","target":"lats","imagePath":"exercises/images/0818-rkg41Fb.jpg","gifPath":"exercises/videos/0818-rkg41Fb.gif","instructionSteps":["调整座椅高度并将自己面向电缆机。","正手握住手柄，双手与肩同宽。","坐下来，将大腿放在大腿垫下方，保持双脚平放在地板上。","稍微向后倾斜，挺胸，保持脊柱中立。","将手柄向下拉至上胸部，将肩胛骨挤压在一起。","在动作的底部暂停片刻，感受背阔肌的收缩。","慢慢松开手柄并返回到起始位置。","重复所需的重复次数。"]},{"id":"0826","name":"vertical leg raise (on parallel bars)","nameZh":"垂直抬腿 (在双杠)","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0826-ZNgOYQU.jpg","gifPath":"exercises/videos/0826-ZNgOYQU.gif","instructionSteps":["悬挂在双杠上，双臂完全伸展，身体伸直。","启动你的核心并将双腿抬起到你面前，保持伸直。","继续抬起，直到双腿与地面平行或稍高。","在顶部暂停片刻，然后慢慢将双腿放回起始位置。","重复所需的重复次数。"]},{"id":"0830","name":"weighted bench dip","nameZh":"负重凳上臂屈伸","equipment":"weighted","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0830-MU9HnE7.jpg","gifPath":"exercises/videos/0830-MU9HnE7.gif","instructionSteps":["坐在长凳上，双手抓住边缘，手指指向前方。","将臀部滑离长凳，用手支撑体重。","弯曲肘部降低身体，直到上臂与地板平行。","伸直手臂，将自己推回起始位置。","重复所需的重复次数。"]},{"id":"0832","name":"weighted crunch","nameZh":"负重卷腹","equipment":"weighted","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0832-s8nrDXF.jpg","gifPath":"exercises/videos/0832-s8nrDXF.gif","instructionSteps":["平躺，膝盖弯曲，双脚平放在地上。","将杠铃片或哑铃放在胸前。","收紧腹肌，将上半身抬离地面，向前卷曲，直到肩胛骨离开地面。","在顶部停顿片刻，然后慢慢将上半身放回起始位置。","重复所需的重复次数。"]},{"id":"0833","name":"weighted donkey calf raise","nameZh":"负重驴式提踵","equipment":"weighted","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/0833-LmaFNZS.jpg","gifPath":"exercises/videos/0833-LmaFNZS.gif","instructionSteps":["站在一个升高的平台上，脚趾放在边缘，脚后跟悬垂。","抓住一个稳定的物体作为支撑。","伸展脚踝，将脚后跟尽可能抬高。","在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。","重复所需的重复次数。"]},{"id":"0834","name":"weighted front raise","nameZh":"负重前平举","equipment":"weighted","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0834-e4aFmFY.jpg","gifPath":"exercises/videos/0834-e4aFmFY.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向大腿。","保持双臂伸直，呼气并将哑铃举至身前，直至与肩齐平。","在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0835","name":"weighted hyperextension (on stability ball)","nameZh":"负重过度伸展 (在稳定球)","equipment":"weighted","bodyPart":"back","target":"spine","imagePath":"exercises/images/0835-8urJS9b.jpg","gifPath":"exercises/videos/0835-8urJS9b.gif","instructionSteps":["将自己面朝下放在稳定球上，臀部放在球上，双脚靠在墙上以保持稳定。","将双手放在脑后或交叉放在胸前。","启动你的核心，慢慢地将你的上半身抬离球，伸展你的背部，直到你的身体形成一条直线。","在顶部停顿片刻，然后慢慢将上半身放回起始位置。","重复所需的重复次数。"]},{"id":"0840","name":"weighted overhead crunch (on stability ball)","nameZh":"负重过头卷腹 (在稳定球)","equipment":"weighted","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0840-xmM75XG.jpg","gifPath":"exercises/videos/0840-xmM75XG.gif","instructionSteps":["坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。","双手握住杠铃片或哑铃，并将手臂伸过头顶。","收紧腹肌，慢慢向前弯曲躯干，使胸部靠近膝盖。","在顶部暂停片刻，然后慢慢将躯干放回起始位置。","重复所需的重复次数。"]},{"id":"0841","name":"weighted pull-up","nameZh":"负重引体向上","equipment":"weighted","bodyPart":"back","target":"lats","imagePath":"exercises/images/0841-HMzLjXx.jpg","gifPath":"exercises/videos/0841-HMzLjXx.gif","instructionSteps":["正手握住引体向上杆，握距略宽于肩宽。","悬挂在杠上，双臂完全伸展，身体伸直。","收紧背部肌肉，将身体拉向杠铃杆，保持肘部靠近身体。","继续拉，直到下巴位于杠铃上方。","在顶部停顿片刻，然后慢慢将身体放回起始位置。","重复所需的重复次数。"]},{"id":"0844","name":"weighted round arm","nameZh":"负重绕臂","equipment":"weighted","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0844-VLYXo8S.jpg","gifPath":"exercises/videos/0844-VLYXo8S.gif","instructionSteps":["双脚分开与肩同宽站立，每只手各握一个哑铃。","稍微弯曲膝盖，髋部向前转动，保持背部挺直。","将手臂向两侧举起，肘部保持轻微弯曲。","继续举起手臂，直到它们与地面平行。","在顶部暂停片刻，然后慢慢将手臂放回起始位置。","重复所需的重复次数。"]},{"id":"0845","name":"weighted russian twist (legs up)","nameZh":"负重俄罗斯转体 (腿向上)","equipment":"weighted","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0845-WU9BLIs.jpg","gifPath":"exercises/videos/0845-WU9BLIs.gif","instructionSteps":["坐在地上，膝盖弯曲，双脚离开地面，保持双腿并拢。","用双手将重物放在胸前，保持肘部稍微弯曲。","稍微向后倾斜以锻炼核心肌肉。","将躯干向右扭转，将重量移向右侧地面。","暂停片刻，然后将躯干向左扭转，将重量转移到左侧地面。","继续交替进行所需的重复次数。"]},{"id":"0846","name":"weighted russian twist","nameZh":"负重俄罗斯转体","equipment":"weighted","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0846-fZFZ704.jpg","gifPath":"exercises/videos/0846-fZFZ704.gif","instructionSteps":["坐在地上，膝盖弯曲，双脚平放在地板上。","双手握住重物球或健身球放在胸前。","稍微向后倾斜，保持背部挺直，核心肌群参与。","慢慢地将你的躯干向右扭转，将重物或药球拉向右侧的地板。","暂停片刻，然后将躯干向左扭转，将重物或健身球拉向左侧的地板。","继续交替进行所需的重复次数。"]},{"id":"0847","name":"weighted seated bicep curl (on stability ball)","nameZh":"负重坐姿肱二头肌弯举 (在稳定球)","equipment":"medicine ball","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0847-b4b6afT.jpg","gifPath":"exercises/videos/0847-b4b6afT.gif","instructionSteps":["坐在稳定球上，双脚平放在地面上，背部挺直。","反手握住健身球，手掌朝上，让手臂垂在身体两侧。","保持上臂静止，呼气并将药球向上卷向肩膀。","在顶部暂停片刻，挤压你的二头肌。","吸气并缓慢地将健身球放回起始位置。","重复所需的重复次数。"]},{"id":"0849","name":"weighted seated twist (on stability ball)","nameZh":"负重坐姿转体 (在稳定球)","equipment":"weighted","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0849-s34Y4LR.jpg","gifPath":"exercises/videos/0849-s34Y4LR.gif","instructionSteps":["坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。","双手靠近胸部握住杠铃片或哑铃。","启动你的核心并慢慢地将你的躯干旋转到一侧，保持臀部稳定。","旋转结束时暂停片刻，然后慢慢回到起始位置。","重复旋转到另一侧。","继续交替进行所需的重复次数。"]},{"id":"0850","name":"weighted side bend (on stability ball)","nameZh":"负重体侧屈 (在稳定球)","equipment":"weighted","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0850-6bOA1Oi.jpg","gifPath":"exercises/videos/0850-6bOA1Oi.gif","instructionSteps":["坐在稳定球上，双脚分开与肩同宽，平放在地面上。","一只手握住重物，另一只手放在臀部上。","启动你的核心，慢慢向受重侧侧弯，保持背部挺直。","在底部停顿片刻，然后慢慢回到起始位置。","重复所需的重复次数，然后换边。"]},{"id":"0851","name":"weighted sissy squat","nameZh":"负重西斯深蹲","equipment":"weighted","bodyPart":"upper legs","target":"quads","imagePath":"exercises/images/0851-0lQnxMZ.jpg","gifPath":"exercises/videos/0851-0lQnxMZ.gif","instructionSteps":["双脚分开与肩同宽站立，脚趾稍微向外。","用双手将重物放在胸前，或将杠铃放在上背部。","保持挺胸，核心收紧，弯曲膝盖和臀部，慢慢降低身体。","继续降低，直到大腿与地面平行或尽可能低。","在底部停顿片刻，然后推动脚后跟回到起始位置。","重复所需的重复次数。"]},{"id":"0852","name":"weighted squat","nameZh":"负重深蹲","equipment":"weighted","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0852-JZuApnB.jpg","gifPath":"exercises/videos/0852-JZuApnB.gif","instructionSteps":["双脚分开与肩同宽站立，脚趾稍微向外。","将重物放在胸前或肩膀上。","收紧核心并保持挺胸，同时降低臀部和向后倾斜，就像坐在椅子上一样。","降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。","推动脚后跟站起来，在顶部挤压臀部。","重复所需的重复次数。"]},{"id":"0853","name":"weighted standing curl","nameZh":"负重站姿弯举","equipment":"weighted","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0853-M5Y7GPg.jpg","gifPath":"exercises/videos/0853-M5Y7GPg.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝前。","保持肘部靠近躯干，并在将哑铃弯举至肩部水平时呼气。","在顶部暂停片刻，然后吸气，慢慢将重量放回起始位置。","重复所需的重复次数。"]},{"id":"0854","name":"weighted standing hand squeeze","nameZh":"负重站姿手挤压","equipment":"weighted","bodyPart":"lower arms","target":"forearms","imagePath":"exercises/images/0854-bjqbauy.jpg","gifPath":"exercises/videos/0854-bjqbauy.gif","instructionSteps":["双脚分开与肩同宽站立，每只手各握一个重物。","将双臂伸直在身前，手掌相对。","尽可能用力将双手握在一起，用力接触前臂。","按住挤压几秒钟，然后松开。","重复所需的重复次数。"]},{"id":"0856","name":"weighted svend press","nameZh":"负重斯文德推举","equipment":"weighted","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0856-I1OBLnn.jpg","gifPath":"exercises/videos/0856-I1OBLnn.gif","instructionSteps":["双脚分开与肩同宽站立，双手将杠铃片放在胸前。","保持肘部稍微弯曲，手掌相对。","将配重板直接压在您面前，完全伸展双臂。","动作结束时暂停片刻，然后慢慢将配重板放回起始位置。","重复所需的重复次数。"]},{"id":"0857","name":"wheel rollerout","nameZh":"健腹轮滚动","equipment":"wheel roller","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0857-NAgVB3t.jpg","gifPath":"exercises/videos/0857-NAgVB3t.gif","instructionSteps":["跪在地板上，将滚轮放在您面前。","将双手放在滚轮的手柄上，并将手臂伸直至前方。","调动你的核心肌肉，慢慢向前滚动轮子，保持背部挺直，腹肌紧张。","继续向前滚动，直到身体完全伸展并且手臂举过头顶。","暂停片刻，然后慢慢地将轮子向膝盖方向滚动，保持控制并保持腹肌接合。","重复所需的重复次数。"]},{"id":"0858","name":"wind sprints","nameZh":"冲刺跑","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0858-Qoujh3Q.jpg","gifPath":"exercises/videos/0858-Qoujh3Q.gif","instructionSteps":["找一个空地或跑道来进行练习。","首先站立，双脚分开与肩同宽。","开始尽可能快地跑步，挥动手臂并抬起膝盖。","继续冲刺特定的距离或时间。","休息并重复所需的重复次数。"]},{"id":"0859","name":"wrist rollerer","nameZh":"手腕滚轴","equipment":"weighted","bodyPart":"lower arms","target":"forearms","imagePath":"exercises/images/0859-bd5b860.jpg","gifPath":"exercises/videos/0859-bd5b860.gif","instructionSteps":["将重物固定在绳子或杆的一端。","用双手握住绳子或杆的另一端，手掌朝下。","双脚分开与肩同宽站立，双臂完全伸展在身前。","弯曲手腕，慢慢地将重物向上滚动到手上。","在顶部暂停片刻，然后慢慢将重量放回起始位置。","重复所需的重复次数。"]},{"id":"0860","name":"cable kickback","nameZh":"绳索后摆臂屈伸","equipment":"cable","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0860-HEJ6DIX.jpg","gifPath":"exercises/videos/0860-HEJ6DIX.gif","instructionSteps":["面向缆绳机站立，双脚与肩同宽。","用右手握住电缆手柄并后退以在电缆中产生张力。","稍微弯曲膝盖，髋部向前转动，保持背部挺直。","保持上臂靠近身体，肘部弯曲成 90 度角。","向后伸展前臂，完全伸直手臂。","暂停片刻，然后慢慢回到起始位置。","重复所需的重复次数，然后换边。"]},{"id":"0861","name":"cable seated row","nameZh":"坐姿划船","equipment":"cable","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0861-fUBheHs.jpg","gifPath":"exercises/videos/0861-fUBheHs.gif","instructionSteps":["坐在电缆划船机上，双脚平放在脚踏板上，膝盖稍微弯曲。","正手握住手柄，保持背部挺直，肩膀放松。","将手柄拉向身体，将肩胛骨挤压在一起。","在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。","重复所需的重复次数。"]},{"id":"0862","name":"cable twist (up-down)","nameZh":"绳索转体 (向上-向下)","equipment":"cable","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0862-fhZQPlV.jpg","gifPath":"exercises/videos/0862-fhZQPlV.gif","instructionSteps":["双脚分开与肩同宽站立，面向绳索机。","双手握住电缆手柄于胸前，保持双臂略微弯曲。","启动你的核心并慢慢地将你的躯干旋转到一侧，保持你的臀部和腿部稳定。","旋转结束时暂停片刻，然后慢慢回到起始位置。","向另一侧重复旋转。","继续交替进行所需的重复次数。"]},{"id":"0863","name":"dumbbell lying external shoulder rotation","nameZh":"哑铃仰卧外肩旋转","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0863-bmBf7LN.jpg","gifPath":"exercises/videos/0863-bmBf7LN.gif","instructionSteps":["侧躺在平坦的长凳上，上臂靠在身体两侧，肘部弯曲 90 度。","手中握住哑铃，手掌朝下。","保持上臂靠在身体两侧，尽可能缓慢地向上旋转前臂。","在顶部暂停片刻，然后慢慢将前臂放回起始位置。","重复所需的重复次数，然后换边。"]},{"id":"0864","name":"dumbbell upright shoulder external rotation","nameZh":"哑铃直立肩外旋","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0864-x306lCW.jpg","gifPath":"exercises/videos/0864-x306lCW.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。","将手臂向两侧抬起，直到与地面平行，保持肘部稍微弯曲。","向外旋转手臂，将哑铃举向头部，同时保持肘部处于同一位置。","在最高点暂停片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0865","name":"lying leg-hip raise","nameZh":"仰卧腿髋上抬","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0865-9IxJdtC.jpg","gifPath":"exercises/videos/0865-9IxJdtC.gif","instructionSteps":["平躺，双腿伸展，双臂放在身体两侧。","将双手放在臀部下方以获得支撑。","启动你的核心并将双腿抬离地面，将它们抬向天花板。","在顶部暂停片刻，然后慢慢将双腿放回起始位置。","重复所需的重复次数。"]},{"id":"0866","name":"weighted hanging leg-hip raise","nameZh":"负重悬垂腿髋上抬","equipment":"weighted","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0866-QOA0FD0.jpg","gifPath":"exercises/videos/0866-QOA0FD0.gif","instructionSteps":["悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。","启动你的核心并将双腿抬起到你面前，保持伸直。","继续抬起，直到双腿与地面平行或稍高。","在顶部暂停片刻，然后慢慢将双腿放回起始位置。","重复所需的重复次数。"]},{"id":"0868","name":"cable curl","nameZh":"绳索弯举","equipment":"cable","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0868-G08RZcQ.jpg","gifPath":"exercises/videos/0868-G08RZcQ.gif","instructionSteps":["面对电缆机站立，双脚与肩同宽。","用手握住电缆附件，手掌朝上。","保持肘部靠近身体两侧，上臂保持静止。","呼气并将电缆附件卷向肩膀，收缩二头肌。","在动作的最高点暂停片刻，挤压你的二头肌。","吸气并缓慢地将电缆附件放回起始位置。","重复所需的重复次数。"]},{"id":"0869","name":"lever shoulder press v. 2","nameZh":"杠杆机肩推版本 2","equipment":"leverage machine","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0869-vqsbmL0.jpg","gifPath":"exercises/videos/0869-vqsbmL0.gif","instructionSteps":["将杠杆机的座椅高度和靠背调整到舒适的位置。","坐在机器上，背部靠在靠背上，双脚平放在地板上。","正手握住机器的手柄，握距略宽于肩宽。","向上和向前推动手柄，直到手臂完全伸展，但未锁定。","在顶部暂停片刻，然后慢慢将手柄放回起始位置。","重复所需的重复次数。"]},{"id":"0870","name":"butt-ups","nameZh":"臀冲","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0870-qcNN2FN.jpg","gifPath":"exercises/videos/0870-qcNN2FN.gif","instructionSteps":["平躺，膝盖弯曲，双脚平放在地上。","将双手放在身体两侧，掌心朝下。","收紧腹肌，将双腿抬离地面，将膝盖靠近胸部。","在动作的最高点，挤压腹肌并暂停片刻。","慢慢地将双腿放回起始位置。","重复所需的重复次数。"]},{"id":"0871","name":"tuck crunch","nameZh":"蜷身卷腹","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0871-BMMolZ3.jpg","gifPath":"exercises/videos/0871-BMMolZ3.gif","instructionSteps":["平躺，膝盖弯曲，双脚平放在地上。","将双手放在脑后，肘部朝外。","收紧腹肌，将肩胛骨抬离地面，将膝盖靠近胸部，同时将上半身卷向膝盖。","在顶部停顿片刻，然后慢慢降低肩胛骨并将双腿伸展回起始位置。","重复所需的重复次数。"]},{"id":"0872","name":"reverse crunch","nameZh":"反向卷腹","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0872-nCU1Ekp.jpg","gifPath":"exercises/videos/0872-nCU1Ekp.gif","instructionSteps":["平躺，双臂沿着身体两侧伸展。","弯曲膝盖，将脚抬离地面，使大腿垂直于地板。","收缩腹肌，将臀部卷离地板，使膝盖靠近胸部。","在顶部暂停片刻，然后慢慢将臀部放回起始位置。","重复所需的重复次数。"]},{"id":"0873","name":"cable reverse crunch","nameZh":"绳索反向卷腹","equipment":"cable","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0873-RqOtqD7.jpg","gifPath":"exercises/videos/0873-RqOtqD7.gif","instructionSteps":["将电缆连接到低滑轮上，然后面朝上躺在垫子上。","用双手握住电缆，并将双臂伸向天花板。","弯曲膝盖并抬起双腿，使大腿靠近胸部。","在保持上半身稳定的同时，将骨盆向胸部弯曲，将臀部抬离垫子。","在顶部暂停片刻，然后慢慢将臀部放回起始位置。","重复所需的重复次数。"]},{"id":"0874","name":"cable standing crunch (with rope attachment)","nameZh":"绳索站姿卷腹 (带绳索附件)","equipment":"cable","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0874-XU3ePuv.jpg","gifPath":"exercises/videos/0874-XU3ePuv.gif","instructionSteps":["将一根绳子连接到胸部高度的缆绳机上。","背对机器站立，双脚与肩同宽。","双手握住绳子并将其放在脑后，保持肘部弯曲。","收紧腹肌，慢慢向前挤压躯干，使肘部靠近膝盖。","在卷腹的最高点暂停片刻，然后慢慢回到起始位置。","重复所需的重复次数。"]},{"id":"0968","name":"band alternating biceps curl","nameZh":"弹力带交替肱二头肌弯举","equipment":"band","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0968-3omWx6P.jpg","gifPath":"exercises/videos/0968-3omWx6P.gif","instructionSteps":["双脚分开与肩同宽站立，反手握住弹力带，手掌朝上。","保持肘部靠近身体两侧，慢慢地将一只手臂向肩膀弯曲，在顶部挤压二头肌。","将手臂放回起始位置，然后用另一只手臂重复此动作。","继续交替手臂进行所需的重复次数。"]},{"id":"0969","name":"band alternating v-up","nameZh":"弹力带交替 V 字起身","equipment":"band","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0969-ztAa1RK.jpg","gifPath":"exercises/videos/0969-ztAa1RK.gif","instructionSteps":["平躺，双腿伸直，手臂伸过头顶，握住弹力带。","收紧腹肌，同时将双腿和上半身抬离地面，将双手伸向脚趾。","当你降低双腿和上半身时，交换双腿的位置，将一条腿交叉在另一条腿上。","重复该动作，每次重复时交替变换双腿的位置。","继续进行所需的重复次数。"]},{"id":"0970","name":"band assisted pull-up","nameZh":"弹力带辅助引体向上","equipment":"band","bodyPart":"back","target":"lats","imagePath":"exercises/images/0970-r1XNRYB.jpg","gifPath":"exercises/videos/0970-r1XNRYB.gif","instructionSteps":["将弹力带固定在上拉杆或坚固的锚点上。","踏上弹力带，手掌背向自己，握住杠铃，双手之间的距离略宽于肩宽。","双臂完全伸展，保持核心收紧，肩膀向下并向后倾斜。","将肩胛骨挤压在一起并将肘部向下推向臀部，将身体向上拉向杠铃杆。","继续拉，直到下巴高于杠铃，然后慢慢降低回到起始位置。","重复所需的重复次数。"]},{"id":"0971","name":"band assisted wheel rollerout","nameZh":"弹力带辅助健腹轮滚动","equipment":"band","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0971-zhF9lW4.jpg","gifPath":"exercises/videos/0971-zhF9lW4.gif","instructionSteps":["跪在地板上，双手握住弹力带的手柄，手掌朝下。","将弹力带放在您面前的地面上，双手分开与肩同宽。","启动你的核心并缓慢地向前滚动轮子，在保持控制的同时尽可能地伸展你的身体。","在最远点暂停片刻，然后慢慢地将轮子向膝盖方向滚动，回到起始位置。","重复所需的重复次数。"]},{"id":"0972","name":"band bicycle crunch","nameZh":"弹力带空中蹬车卷腹","equipment":"band","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0972-tZkGYZ9.jpg","gifPath":"exercises/videos/0972-tZkGYZ9.gif","instructionSteps":["平躺，双手放在脑后，膝盖弯曲。","将脚抬离地面，将右膝盖靠近胸部，同时扭转躯干，将左肘靠近右膝盖。","伸直右腿，同时将左膝靠近胸部，并扭转躯干，使右肘靠近左膝。","继续交替扭转运动，就像踩自行车一样，同时在整个运动过程中保持核心参与。","重复所需的重复次数。"]},{"id":"0974","name":"band close-grip pulldown","nameZh":"弹力带窄距下拉","equipment":"band","bodyPart":"back","target":"lats","imagePath":"exercises/images/0974-DptumMx.jpg","gifPath":"exercises/videos/0974-DptumMx.gif","instructionSteps":["将弹力带固定在较高的锚点上，例如上拉杆或坚固的横梁。","面向锚点站立，用反手抓住弹力带，双手与肩同宽。","后退一步，在弹力带上产生张力，双脚分开与臀部同宽。","当你将弹力带向下拉向胸部时，收紧你的核心并保持背部挺直，将肩胛骨挤压在一起。","在动作底部暂停片刻，然后慢慢松开弹力带回到起始位置。","重复所需的重复次数。"]},{"id":"0975","name":"band close-grip push-up","nameZh":"弹力带窄距俯卧撑","equipment":"band","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0975-ufaxB52.jpg","gifPath":"exercises/videos/0975-ufaxB52.gif","instructionSteps":["将一条带子绕在你的上臂上，就在肘部上方。","采取俯卧撑姿势，双手直接放在肩膀下方，身体从头到脚跟呈一条直线。","弯曲肘部，将胸部降低到地面，保持肘部靠近身体两侧。","推动手掌以伸展手臂并返回到起始位置。","重复所需的重复次数。"]},{"id":"0976","name":"band concentration curl","nameZh":"弹力带集中弯举","equipment":"band","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0976-kmVVAfu.jpg","gifPath":"exercises/videos/0976-kmVVAfu.gif","instructionSteps":["坐在长凳或椅子上，双腿分开，双脚平放在地上。","用手握住带子的一端，用脚踩在另一端上，同时将脚放在同一侧。","稍微向前倾，将肘部放在大腿内侧，膝盖上方。","手掌朝上，慢慢地将手向肩膀弯曲，保持上臂静止。","在顶部暂停片刻，然后慢慢将手放回起始位置。","重复所需的重复次数，然后换边。"]},{"id":"0977","name":"band front lateral raise","nameZh":"弹力带前侧平举","equipment":"band","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0977-sTg7iys.jpg","gifPath":"exercises/videos/0977-sTg7iys.gif","instructionSteps":["双脚分开与肩同宽站立，将弹力带放在大腿前面，手掌朝下。","保持双臂伸直，将弹力带举到身前，直到双臂与地面平行。","在顶部暂停片刻，然后慢慢将弹力带放回起始位置。","重复所需的重复次数。"]},{"id":"0978","name":"band front raise","nameZh":"弹力带前平举","equipment":"band","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0978-TFA88iB.jpg","gifPath":"exercises/videos/0978-TFA88iB.gif","instructionSteps":["双脚分开与肩同宽站立，将弹力带放在大腿前面，手掌朝下。","保持手臂伸直，慢慢向前举起，直到与地面平行。","在顶部暂停片刻，然后慢慢将手臂放回起始位置。","重复所需的重复次数。"]},{"id":"0979","name":"band horizontal pallof press","nameZh":"弹力带水平帕洛夫推举","equipment":"band","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0979-9pa4H5m.jpg","gifPath":"exercises/videos/0979-9pa4H5m.gif","instructionSteps":["将带子固定在腰部高度的坚固锚点上。","垂直于锚点站立，双脚分开与肩同宽。","用双手抓住带子手柄并远离锚点以在带子中产生张力。","将双手放在胸前，保持肘部弯曲并靠近身体。","调动你的核心并保持稳定的姿势。","将手臂伸直至前方，将弹力带推离身体。","保持伸展姿势几秒钟，专注于保持核心紧张。","慢慢地将双手放回胸前，抵抗弹力带的拉力。","重复所需的重复次数。"]},{"id":"0980","name":"band bent-over hip extension","nameZh":"弹力带俯身髋伸展","equipment":"band","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0980-wSScovH.jpg","gifPath":"exercises/videos/0980-wSScovH.gif","instructionSteps":["将带子固定在脚踝高度的坚固锚点上。","背对锚点站立，双脚与肩同宽。","向后退一步，在弹力带上产生张力，保持膝盖稍微弯曲。","铰接臀部并向前倾斜，保持脊柱中立。","将右腿向后伸直，在顶部挤压臀部。","将右腿放回原位，然后换左腿重复此动作。","继续交替双腿达到所需的重复次数。"]},{"id":"0981","name":"band jack knife sit-up","nameZh":"弹力带折刀式仰卧起坐","equipment":"band","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0981-KCBKjma.jpg","gifPath":"exercises/videos/0981-KCBKjma.gif","instructionSteps":["平躺，双腿伸直，手臂伸过头顶，握住弹力带。","收紧腹肌，同时抬起双腿和上半身，将双手移向脚部。","在顶部停顿片刻，然后慢慢放下双腿和上半身回到起始位置。","重复所需的重复次数。"]},{"id":"0983","name":"band kneeling one arm pulldown","nameZh":"弹力带跪姿单臂下拉","equipment":"band","bodyPart":"back","target":"lats","imagePath":"exercises/images/0983-pmnrOp0.jpg","gifPath":"exercises/videos/0983-pmnrOp0.gif","instructionSteps":["将带子固定在头顶上方坚固的锚点上。","跪下，用一只手握住弹力带，手掌朝下。","将手臂完全伸过头顶，保持肘部稍微弯曲。","调动你的背阔肌，将弹力带拉向你的一侧，使你的肘部靠近你的胸腔。","在底部停顿片刻，然后慢慢释放张力，回到起始位置。","重复所需的重复次数，然后换边。"]},{"id":"0984","name":"band lying hip internal rotation","nameZh":"弹力带仰卧髋内旋","equipment":"band","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0984-vIICElP.jpg","gifPath":"exercises/videos/0984-vIICElP.gif","instructionSteps":["仰卧，双腿伸直，将阻力带绕在脚上。","弯曲膝盖并将其靠近胸部，双脚并拢。","慢慢向外旋转膝盖，使膝盖彼此远离，同时保持双脚并拢。","旋转结束时暂停片刻，然后慢慢回到起始位置。","重复所需的重复次数。"]},{"id":"0985","name":"band kneeling twisting crunch","nameZh":"弹力带跪姿扭转卷腹","equipment":"band","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0985-225x2Vd.jpg","gifPath":"exercises/videos/0985-225x2Vd.gif","instructionSteps":["将带子固定在腰部高度的坚固锚点上。","面向远离锚点的方向跪下，用双手握住弹力带，保持肘部弯曲并靠近身体两侧。","收紧腹肌，慢慢地将躯干扭向一侧，将双手移向另一侧的臀部。","暂停片刻，然后慢慢回到起始位置。","在另一侧重复。","继续交替进行所需的重复次数。"]},{"id":"0986","name":"band one arm overhead biceps curl","nameZh":"弹力带单臂过头肱二头肌弯举","equipment":"band","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0986-UNAB8ak.jpg","gifPath":"exercises/videos/0986-UNAB8ak.gif","instructionSteps":["双脚分开与肩同宽站立，将弹力带的一端放在脚下。","握住弹力带的另一端，手臂完全伸过头顶，手掌朝前。","保持上臂静止，将前臂向肩膀弯曲，挤压二头肌。","在顶部停顿片刻，然后慢慢将前臂放回起始位置。","重复所需的重复次数，然后换臂。"]},{"id":"0987","name":"band one arm single leg split squat","nameZh":"弹力带单臂单腿分腿深蹲","equipment":"band","bodyPart":"upper legs","target":"quads","imagePath":"exercises/images/0987-arsYEd3.jpg","gifPath":"exercises/videos/0987-arsYEd3.gif","instructionSteps":["双脚分开站立，与臀部同宽，将阻力带绕在脚踝上。","向前伸出一条腿，将脚尖放在长凳上或身后的一步上。","用一只手握住支撑物以保持平衡。","弯曲站立的腿，将身体降低到蹲姿，保持膝盖与脚趾在一条直线上。","推动脚后跟返回到起始位置。","重复所需的重复次数，然后换腿。"]},{"id":"0988","name":"band one arm standing low row","nameZh":"弹力带单臂站姿低位划船","equipment":"band","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0988-km0sQC0.jpg","gifPath":"exercises/videos/0988-km0sQC0.gif","instructionSteps":["将带子固定在腰部高度的稳定锚点上。","面向锚点站立，双脚分开与肩同宽。","用一只手握住弹力带，手掌朝内，然后后退以在弹力带中产生张力。","稍微弯曲膝盖，髋部向前转动，保持背部挺直。","将带子拉向腰部，将肩胛骨挤压在一起。","在动作的最高点暂停片刻，然后慢慢松开弹力带回到起始位置。","重复所需的重复次数，然后换边。"]},{"id":"0989","name":"band one arm twisting chest press","nameZh":"弹力带单臂扭转胸部推举","equipment":"band","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0989-c16nYGA.jpg","gifPath":"exercises/videos/0989-c16nYGA.gif","instructionSteps":["将带子固定在胸部高度的坚固锚点上。","站立，一侧面向锚点，用一只手抓住带子。","远离锚点以在带子中产生张力。","将双脚分开与肩同宽，并稍微弯曲膝盖。","将握住弹力带的手穿过身体，朝向对侧的肩膀。","在保持弹力带张力的同时，将手向前推离身体，伸展手臂。","慢慢回到起始位置并重复所需的重复次数。","换边并用另一只手重复练习。"]},{"id":"0990","name":"band one arm twisting seated row","nameZh":"弹力带单臂扭转坐姿划船","equipment":"band","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0990-DKBwJrL.jpg","gifPath":"exercises/videos/0990-DKBwJrL.gif","instructionSteps":["坐在长凳或椅子上，双脚平放在地上，背部挺直。","用一只手握住弹力带，并将手臂完全伸到身前。","保持背部挺直，弯曲肘部并将肩胛骨挤压在一起，将弹力带拉向身体。","同时，将躯干向拉动手臂的一侧扭转。","在顶部暂停片刻，然后慢慢释放弹力带的张力并返回到起始位置。","重复所需的重复次数，然后换到另一只手臂。"]},{"id":"0991","name":"band pull through","nameZh":"弹力带穿腿后拉","equipment":"band","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0991-VtTbiP3.jpg","gifPath":"exercises/videos/0991-VtTbiP3.gif","instructionSteps":["将阻力带连接到地面上坚固的锚点上。","背对锚点站立，双脚与肩同宽。","向前迈一步，在弹力带中产生张力，保持膝盖稍微弯曲。","铰接臀部并将臀部向后推，保持膝盖轻微弯曲。","降低躯干直到与地面平行，感觉腿筋被拉伸。","向前推动臀部并挤压臀部以返回起始位置。","重复所需的重复次数。"]},{"id":"0992","name":"band push sit-up","nameZh":"弹力带推仰卧起坐","equipment":"band","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0992-zFzbBfL.jpg","gifPath":"exercises/videos/0992-zFzbBfL.gif","instructionSteps":["将带子牢固地固定在稳定的锚点上。","平躺，膝盖弯曲，双脚平放在地上。","用双手握住弹力带，并将双臂伸向天花板。","收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。","在顶部停顿片刻，然后慢慢将上半身放回起始位置。","重复所需的重复次数。"]},{"id":"0993","name":"band reverse fly","nameZh":"弹力带反向飞鸟","equipment":"band","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0993-sTfvVsG.jpg","gifPath":"exercises/videos/0993-sTfvVsG.gif","instructionSteps":["将带子固定在胸部高度的固定物体上。","双脚分开与肩同宽站立，双手握住弹力带放在身前。","保持手臂伸直并将其向两侧抬起，直到与地面平行。","在动作的最高点将肩胛骨挤压在一起。","慢慢地将手臂放回起始位置。","重复所需的重复次数。"]},{"id":"0994","name":"band reverse wrist curl","nameZh":"弹力带反手腕弯举","equipment":"band","bodyPart":"lower arms","target":"forearms","imagePath":"exercises/images/0994-Ezpnw9d.jpg","gifPath":"exercises/videos/0994-Ezpnw9d.gif","instructionSteps":["坐在长凳或椅子上，双脚平放在地面上。","正手握住弹力带，手掌朝下，然后将其缠绕在手指上。","将前臂放在大腿上，手腕悬在边缘上。","慢慢向上弯曲手腕，挤压前臂。","在顶部暂停片刻，然后慢慢将手腕放回起始位置。","重复所需的重复次数。"]},{"id":"0996","name":"band seated hip internal rotation","nameZh":"弹力带坐姿髋内旋","equipment":"band","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0996-9gbyYKk.jpg","gifPath":"exercises/videos/0996-9gbyYKk.gif","instructionSteps":["坐在椅子或长凳上，背部挺直，双脚平放在地面上。","在大腿周围、膝盖上方放置一条阻力带。","保持膝盖弯曲 90 度，双脚分开与肩同宽。","收紧臀肌，慢慢向外旋转膝盖，克服弹力带的阻力。","动作结束时暂停片刻，然后慢慢回到起始位置。","重复所需的重复次数。"]},{"id":"0997","name":"band shoulder press","nameZh":"弹力带肩推","equipment":"band","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0997-peAeMR3.jpg","gifPath":"exercises/videos/0997-peAeMR3.gif","instructionSteps":["双脚分开与肩同宽站立，将弹力带放在脚下。","手掌朝前握住弹力带，将双手举至肩高，肘部弯曲。","将弹力带压过头顶，充分伸展双臂。","在顶部暂停片刻，然后慢慢将阻力带降低至肩部高度。","重复所需的重复次数。"]},{"id":"0998","name":"band side triceps extension","nameZh":"弹力带侧肱三头肌伸展","equipment":"band","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0998-obe5LMq.jpg","gifPath":"exercises/videos/0998-obe5LMq.gif","instructionSteps":["双脚分开与肩同宽站立，双手握住弹力带，掌心朝下。","将手臂伸直至两侧，保持与地面平行。","慢慢弯曲肘部，将双手放在肩膀上，保持上臂不动。","暂停片刻，然后慢慢将手臂伸回起始位置。","重复所需的重复次数。"]},{"id":"0999","name":"band single leg calf raise","nameZh":"弹力带单腿提踵","equipment":"band","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/0999-9JprnPh.jpg","gifPath":"exercises/videos/0999-9JprnPh.gif","instructionSteps":["双脚分开站立，与臀部同宽，将弹力带绕在左脚掌上。","如果需要，请抓住一个稳定的物体以保持平衡。","慢慢地将左脚跟抬离地面，将身体重量转移到脚掌上。","在顶部暂停片刻，然后慢慢将左脚跟放回起始位置。","重复所需的重复次数，然后换右腿。"]},{"id":"1000","name":"band single leg reverse calf raise","nameZh":"弹力带单腿反向提踵","equipment":"band","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/1000-QsSQWbf.jpg","gifPath":"exercises/videos/1000-QsSQWbf.gif","instructionSteps":["双脚分开站立，与臀部同宽，将弹力带放在脚掌周围。","抓住稳定的物体以保持平衡。","慢慢地将脚跟抬离地面，将身体重量转移到脚掌上。","在顶部暂停片刻，然后慢慢将脚跟放回起始位置。","重复所需的重复次数，然后换另一条腿。"]},{"id":"1001","name":"band single leg split squat","nameZh":"弹力带单腿分腿深蹲","equipment":"band","bodyPart":"upper legs","target":"quads","imagePath":"exercises/images/1001-y8bYM8w.jpg","gifPath":"exercises/videos/1001-y8bYM8w.gif","instructionSteps":["双脚分开站立，与臀部同宽，将阻力带绕在脚踝上。","右脚向前迈一大步，左脚向后退一小步。","弯曲膝盖并降低身体，直到右大腿与地面平行，保持左膝盖略高于地面。","推动右脚跟回到起始位置。","在另一侧重复。"]},{"id":"1002","name":"band lying straight leg raise","nameZh":"弹力带仰卧直腿抬举","equipment":"band","bodyPart":"waist","target":"abs","imagePath":"exercises/images/1002-bbLR7fB.jpg","gifPath":"exercises/videos/1002-bbLR7fB.gif","instructionSteps":["平躺，双腿伸直，双脚并拢。","将带子放在脚弓周围，并用手握住带子的末端。","收紧腹肌，将双腿抬离地面，直到它们垂直于地板。","在顶部暂停片刻，然后慢慢将双腿放回起始位置。","重复所需的重复次数。"]},{"id":"1003","name":"band squat row","nameZh":"弹力带深蹲划船","equipment":"band","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/1003-w1NOByi.jpg","gifPath":"exercises/videos/1003-w1NOByi.gif","instructionSteps":["将带子固定在腰部高度的坚固锚点上。","面向锚点站立，双脚分开与肩同宽。","双手握住弹力带手柄，手掌相对，双臂向前伸展。","弯曲膝盖并蹲下，保持背部挺直，挺胸。","从蹲姿开始，将弹力带手柄拉向身体，将肩胛骨挤压在一起。","在最高点停顿片刻，然后慢慢释放张力，回到起始位置。","重复所需的重复次数。"]},{"id":"1004","name":"band squat","nameZh":"弹力带深蹲","equipment":"band","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/1004-TUZLh71.jpg","gifPath":"exercises/videos/1004-TUZLh71.gif","instructionSteps":["双脚分开站立，与肩同宽，弹力带放在膝盖上方。","保持挺胸、核心收紧，将臀部向后推，弯曲膝盖，形成下蹲姿势。","确保膝盖位于脚趾上方，并且重量位于脚后跟。","在底部停顿片刻，然后推动脚后跟回到起始位置。","重复所需的重复次数。"]},{"id":"1005","name":"band standing crunch","nameZh":"弹力带站姿卷腹","equipment":"band","bodyPart":"waist","target":"abs","imagePath":"exercises/images/1005-Kzg30R7.jpg","gifPath":"exercises/videos/1005-Kzg30R7.gif","instructionSteps":["将带子固定在腰部高度的坚固锚点上。","背对锚点站立，双脚与肩同宽。","用双手握住弹力带并将其举至胸前，保持肘部弯曲并靠近身体。","收紧腹肌，慢慢向前挺胸，使胸部靠近膝盖。","在卷腹的最高点暂停片刻，然后慢慢回到起始位置。","重复所需的重复次数。"]},{"id":"1007","name":"band standing twisting crunch","nameZh":"弹力带站姿扭转卷腹","equipment":"band","bodyPart":"waist","target":"abs","imagePath":"exercises/images/1007-euq4pwp.jpg","gifPath":"exercises/videos/1007-euq4pwp.gif","instructionSteps":["双脚分开与肩同宽站立，将弹力带绕在上背部，穿过胸前。","用手握住带子的末端，保持肘部弯曲并靠近身体两侧。","收紧腹肌并将躯干向一侧扭转，将肘部移向另一侧的膝盖。","暂停片刻，然后回到起始位置。","在另一侧重复。","继续交替进行所需的重复次数。"]},{"id":"1008","name":"band step-up","nameZh":"弹力带登阶","equipment":"band","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/1008-d5bTEPV.jpg","gifPath":"exercises/videos/1008-d5bTEPV.gif","instructionSteps":["将一条带子绕在大腿上，就在膝盖上方。","面向台阶或平台站立，双脚分开与臀部同宽。","用右脚踩上平台，用脚后跟推动。","将左腿伸到身后，保持伸直。","将左脚放回地面。","重复左脚踩上平台的动作。","继续交替双腿达到所需的重复次数。"]},{"id":"1009","name":"band stiff leg deadlift","nameZh":"弹力带直腿硬拉","equipment":"band","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/1009-kuMiR2T.jpg","gifPath":"exercises/videos/1009-kuMiR2T.gif","instructionSteps":["双脚分开站立，与肩同宽，将弹力带绕在脚踝上。","用双手将弹力带放在大腿前面，手掌朝向身体。","保持背部挺直，核心收紧，铰接臀部，慢慢将上半身降低到地面。","当你降低时，将臀部向后推，并让膝盖稍微弯曲。","将弹力带降低至地面，感受腿筋的拉伸。","在底部暂停片刻，然后启动臀肌和腿筋，将上半身抬回到起始位置。","重复所需的重复次数。"]},{"id":"1010","name":"band straight leg deadlift","nameZh":"弹力带直腿硬拉","equipment":"band","bodyPart":"back","target":"spine","imagePath":"exercises/images/1010-KUaoUV8.jpg","gifPath":"exercises/videos/1010-KUaoUV8.gif","instructionSteps":["双脚分开与肩同宽站立，将弹力带绕在脚上。","双手握住弹力带，手掌朝向身体，手臂伸直。","收紧核心并保持膝盖轻微弯曲。","慢慢地以臀部为中心向前转动，保持背部挺直，挺胸。","将弹力带降低至地面，同时保持双腿伸直。","在底部暂停片刻，然后挤压臀肌和腿筋，回到起始位置。","重复所需的重复次数。"]},{"id":"1011","name":"band seated twist","nameZh":"弹力带坐姿转体","equipment":"band","bodyPart":"waist","target":"abs","imagePath":"exercises/images/1011-S1JXDAG.jpg","gifPath":"exercises/videos/1011-S1JXDAG.gif","instructionSteps":["坐在地上，双腿向前伸展，背部挺直。","将带子绕在腰上，并用双手握住两端。","收紧腹肌，慢慢将躯干扭向一侧，保持背部挺直，双脚着地。","扭转结束时暂停片刻，然后慢慢回到起始位置。","重复扭转到另一侧。","继续交替进行所需的重复次数。"]},{"id":"1012","name":"band twisting overhead press","nameZh":"弹力带扭转过头推举","equipment":"band","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/1012-u4bAmKp.jpg","gifPath":"exercises/videos/1012-u4bAmKp.gif","instructionSteps":["双脚分开与肩同宽站立，将弹力带放在脚下。","将弹力带手柄保持在与肩同高的位置，手掌朝前。","启动你的核心并将弹力带压过头顶，充分伸展你的手臂。","当你按压时，将你的躯干扭转到一侧，保持臀部稳定。","在顶部暂停片刻，然后回到起始位置。","在另一侧重复按压和扭转。","继续交替进行所需的重复次数。"]},{"id":"1013","name":"band underhand pulldown","nameZh":"弹力带反手下拉","equipment":"band","bodyPart":"back","target":"lats","imagePath":"exercises/images/1013-k6tUeqS.jpg","gifPath":"exercises/videos/1013-k6tUeqS.gif","instructionSteps":["将弹力带固定在较高的锚点上，例如上拉杆或坚固的横梁。","面向锚点站立，双脚分开与肩同宽。","反手握住弹力带，双手间距略宽于肩宽。","将手臂完全伸过头顶，保持肘部稍微弯曲。","收紧背阔肌，将弹力带向下拉向胸部，将肩胛骨挤压在一起。","在动作底部停顿片刻，然后慢慢释放张力，回到起始位置。","重复所需的重复次数。"]},{"id":"1014","name":"band v-up","nameZh":"弹力带 V 字起身","equipment":"band","bodyPart":"waist","target":"abs","imagePath":"exercises/images/1014-H6ETwO9.jpg","gifPath":"exercises/videos/1014-H6ETwO9.gif","instructionSteps":["平躺，双腿伸直，手臂伸过头顶，握住弹力带。","收紧腹肌，同时将双腿和上半身抬离地面，双手伸向脚趾。","在顶部停顿片刻，然后慢慢放下双腿和上半身回到起始位置。","重复所需的重复次数。"]},{"id":"1015","name":"band vertical pallof press","nameZh":"弹力带垂直帕洛夫推举","equipment":"band","bodyPart":"waist","target":"abs","imagePath":"exercises/images/1015-G7PXMlT.jpg","gifPath":"exercises/videos/1015-G7PXMlT.gif","instructionSteps":["双脚分开与肩同宽站立，将弹力带缠绕在胸部高度的坚固物体上。","用双手握住弹力带并远离锚点，在弹力带中产生张力。","使自己垂直于锚点，一侧面向弹力带。","将双臂伸直在身前，保持双手与胸同高。","收紧核心肌群，将弹力带压离胸部，充分伸展手臂。","保持该姿势几秒钟，然后慢慢将弹力带拉回到胸部。","重复所需的重复次数，然后换边。"]},{"id":"1016","name":"band wrist curl","nameZh":"弹力带手腕弯举","equipment":"band","bodyPart":"lower arms","target":"forearms","imagePath":"exercises/images/1016-vUTfFHw.jpg","gifPath":"exercises/videos/1016-vUTfFHw.gif","instructionSteps":["坐在长凳或椅子上，双脚平放在地面上。","双手握住弹力带，手掌朝上，前臂放在大腿上。","慢慢向上弯曲手腕，挤压前臂。","在顶部暂停片刻，然后慢慢将手腕放回起始位置。","重复所需的重复次数。"]},{"id":"1017","name":"band y-raise","nameZh":"弹力带 Y 字抬举","equipment":"band","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/1017-aHDy5O5.jpg","gifPath":"exercises/videos/1017-aHDy5O5.gif","instructionSteps":["双脚分开与肩同宽站立，将弹力带放在大腿前面，手掌朝内。","保持双臂伸直，将其向上举至两侧，与身体形成“Y”形。","在动作的最高点将肩胛骨挤压在一起。","慢慢地将手臂放回起始位置。","重复所需的重复次数。"]},{"id":"1018","name":"band shrug","nameZh":"弹力带耸肩","equipment":"band","bodyPart":"back","target":"traps","imagePath":"exercises/images/1018-trmte8s.jpg","gifPath":"exercises/videos/1018-trmte8s.gif","instructionSteps":["双脚分开与肩同宽站立，将弹力带放在脚下，用手握住两端。","保持手臂伸直并放松，让弹力带悬挂在大腿前面。","向上耸肩，尽可能高地举起弹力带，以启动斜方肌。","保持收缩一会儿，然后慢慢将肩膀放回起始位置。","重复所需的重复次数。"]},{"id":"1022","name":"band standing rear delt row","nameZh":"弹力带站姿后三角肌划船","equipment":"band","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/1022-tc5dYrf.jpg","gifPath":"exercises/videos/1022-tc5dYrf.gif","instructionSteps":["双脚分开与肩同宽站立，将弹力带放在脚下。","双手握住弹力带手柄，手掌相对，双臂向前伸展。","稍微弯曲膝盖，髋部向前转动，保持背部挺直。","将弹力带拉向胸部，将肩胛骨挤压在一起。","在最高点停顿片刻，然后慢慢释放张力，回到起始位置。","重复所需的重复次数。"]},{"id":"1023","name":"band straight back stiff leg deadlift","nameZh":"弹力带直背直腿硬拉","equipment":"band","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/1023-lHeUULr.jpg","gifPath":"exercises/videos/1023-lHeUULr.gif","instructionSteps":["双脚分开与肩同宽站立，将弹力带绕在大腿上。","用双手将弹力带放在大腿前面，手掌朝向身体。","保持背部挺直，膝盖稍微弯曲，铰接臀部并将弹力带降低到地面。","当你降低弹力带时，感受腿筋的拉伸。","启动臀肌和腿筋，将身体抬回到起始位置。","重复所需的重复次数。"]},{"id":"1167","name":"dynamic chest stretch (male)","nameZh":"动态胸部拉伸 （男）","equipment":"body weight","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1167-3uj0Ozg.jpg","gifPath":"exercises/videos/1167-3uj0Ozg.gif","instructionSteps":["站直，双脚分开与肩同宽。","将双臂伸直至两侧，与地面平行。","慢慢地将双臂向前伸，交叉在身体前面。","感受胸部肌肉的伸展。","保持拉伸 10-30 秒。","返回起始位置并重复所需的重复次数。"]},{"id":"1253","name":"lever donkey calf raise","nameZh":"杠杆机驴式提踵","equipment":"leverage machine","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/1253-C9LuR4A.jpg","gifPath":"exercises/videos/1253-C9LuR4A.gif","instructionSteps":["将杠杆机调节至适合您身体的高度。","面向机器定位，脚趾放在脚踏平台上，脚后跟悬在边缘。","将手放在手柄或支撑杆上以保持稳定性。","用脚掌收紧小腿并尽可能高地抬起脚后跟。","在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。","重复所需的重复次数。"]},{"id":"1254","name":"band bench press","nameZh":"弹力带卧推","equipment":"band","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1254-khlHMqs.jpg","gifPath":"exercises/videos/1254-khlHMqs.gif","instructionSteps":["平躺在长凳上，双脚平放在地上，背部紧贴长凳。","正手握住带子手柄，间距略宽于肩宽。","充分伸展双臂，将弹力带推离胸部。","慢慢将弹力带放回到胸部，保持肘部呈 90 度角。","重复所需的重复次数。"]},{"id":"1255","name":"barbell decline pullover","nameZh":"杠铃下斜仰卧屈臂上拉","equipment":"barbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1255-9sgNE2O.jpg","gifPath":"exercises/videos/1255-9sgNE2O.gif","instructionSteps":["躺在倾斜的长凳上，头部低于臀部，双脚固定。","旋前握住杠铃（手掌背向自己），双手之间的距离略宽于肩宽。","将手臂伸至胸部上方，保持肘部轻微弯曲。","以弧线动作将杠铃降低到头后，感受胸部和肩膀的伸展。","暂停片刻，然后反向动作将杠铃恢复到起始位置。","重复所需的重复次数。"]},{"id":"1256","name":"barbell reverse grip decline bench press","nameZh":"杠铃反握下斜卧推","equipment":"barbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1256-DotAgEF.jpg","gifPath":"exercises/videos/1256-DotAgEF.gif","instructionSteps":["躺在倾斜的长凳上，双脚固定，头部低于臀部。","反握抓住杠铃，握距略宽于肩宽。","松开杠铃，慢慢将其降低到胸部，保持肘部内收。","在底部停顿片刻，然后将杠铃推回到起始位置。","重复所需的重复次数。"]},{"id":"1257","name":"barbell reverse grip incline bench press","nameZh":"杠铃反握上斜卧推","equipment":"barbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1257-DU7I633.jpg","gifPath":"exercises/videos/1257-DU7I633.gif","instructionSteps":["设置一个 45 度角的上斜凳。","躺在长凳上，双脚平放在地上。","反握抓住杠铃，双手分开略宽于肩宽。","松开杠铃，慢慢将其降低到胸部，保持肘部内收。","当杠铃触及胸部时暂停片刻。","将杠铃推回到起始位置，完全伸展双臂。","重复所需的重复次数。"]},{"id":"1258","name":"barbell wide reverse grip bench press","nameZh":"杠铃宽反握卧推","equipment":"barbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1258-945zpRg.jpg","gifPath":"exercises/videos/1258-945zpRg.gif","instructionSteps":["平躺在长凳上，双脚平放在地上，背部紧贴长凳。","反握宽握杠铃，握距略宽于肩宽。","将杠铃从架子上提起，并将其直接放在胸部上方，双臂完全伸展。","将杠铃慢慢降低到胸部，保持肘部内收，手腕伸直。","当杠铃接触胸部时暂停片刻，然后将其推回到起始位置。","重复所需的重复次数。"]},{"id":"1259","name":"behind head chest stretch","nameZh":"头后胸部拉伸","equipment":"assisted","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1259-QoHIhPl.jpg","gifPath":"exercises/videos/1259-QoHIhPl.gif","instructionSteps":["站直，双脚分开与肩同宽。","将手指交叉放在脑后，肘部朝外。","慢慢地将肩胛骨挤压在一起，并将胸部向前推。","保持拉伸 15-30 秒。","松开拉伸并根据需要重复。"]},{"id":"1260","name":"cable decline one arm press","nameZh":"绳索下斜单臂推举","equipment":"cable","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1260-KHGNa16.jpg","gifPath":"exercises/videos/1260-KHGNa16.gif","instructionSteps":["将拉线机调整至下降位置。","背对机器站立，用一只手抓住手柄。","将背部靠在下斜长凳上，手臂伸直在身前。","弯曲肘部，将手柄向胸部方向降低，同时保持上臂静止。","在底部暂停片刻，然后将手柄推回到起始位置。","重复所需的重复次数，然后换臂。"]},{"id":"1261","name":"cable decline press","nameZh":"绳索下斜推举","equipment":"cable","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1261-2Pya1cP.jpg","gifPath":"exercises/videos/1261-2Pya1cP.gif","instructionSteps":["将拉线机调整至下降位置。","坐在面向缆绳机的下降长凳上。","正手握住手柄并将其置于胸部水平。","将双脚平放在地面上，并将背部牢牢靠在长凳上。","呼气并将手柄推离身体，充分伸展双臂。","动作结束时暂停片刻，挤压胸部肌肉。","吸气并慢慢地将手柄放回起始位置。","重复所需的重复次数。"]},{"id":"1262","name":"cable one arm decline chest fly","nameZh":"绳索单臂下斜胸部飞鸟","equipment":"cable","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1262-w4dLzSx.jpg","gifPath":"exercises/videos/1262-w4dLzSx.gif","instructionSteps":["将 D 形手柄连接到低滑轮绳索机器上，并将长凳设置为下降角度。","躺在长凳上，头朝向机器，用右手抓住手柄。","将手臂伸直至胸部上方，保持肘部轻微弯曲。","控制动作，将手臂向一侧放低，直到手与肩膀在一条直线上。","暂停片刻，然后反转动作并将手臂恢复到起始位置。","重复所需的重复次数，然后切换到左臂并重复练习。"]},{"id":"1263","name":"cable one arm fly on exercise ball","nameZh":"绳索单臂飞鸟在健身球","equipment":"cable","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1263-hHy8tQG.jpg","gifPath":"exercises/videos/1263-hHy8tQG.gif","instructionSteps":["坐在健身球上，双脚平放在地上，背部挺直。","一只手握住电缆手柄，并将手臂向一侧伸出，与地面平行。","保持肘部稍微弯曲，手掌朝前。","慢慢地将手臂放在身体上，挤压胸部肌肉。","动作结束时暂停片刻，然后慢慢回到起始位置。","重复所需的重复次数，然后换边。"]},{"id":"1264","name":"cable one arm incline fly on exercise ball","nameZh":"绳索单臂上斜飞鸟在健身球","equipment":"cable","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1264-P14Dz9D.jpg","gifPath":"exercises/videos/1264-P14Dz9D.gif","instructionSteps":["坐在健身球上，双脚平放在地面上，背部靠在倾斜的长凳上。","一只手握住电缆手柄，手臂伸展，手掌朝内。","保持肘部轻微弯曲，慢慢地将手臂向一侧放低，直到手与肩膀在一条直线上。","暂停片刻，然后挤压胸部肌肉，使手臂回到起始位置。","重复所需的重复次数，然后换臂。"]},{"id":"1265","name":"cable one arm incline press","nameZh":"绳索单臂上斜推举","equipment":"cable","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1265-GKEH6jj.jpg","gifPath":"exercises/videos/1265-GKEH6jj.gif","instructionSteps":["将拉索机调整至低滑轮位置。","坐在倾斜的长凳上，背对缆绳机。","用一只手抓住手柄并将其举至肩膀高度。","将双脚牢牢放在地面上并保持稳定的位置。","向前和向上按下手柄，充分伸展手臂。","在最高点暂停片刻，然后慢慢将手柄放回起始位置。","重复所需的重复次数，然后换边。"]},{"id":"1266","name":"cable one arm incline press on exercise ball","nameZh":"绳索单臂上斜推举在健身球","equipment":"cable","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1266-6t00BsF.jpg","gifPath":"exercises/videos/1266-6t00BsF.gif","instructionSteps":["坐在健身球上，双脚平放在地上，背部靠在倾斜的长凳上。","一只手握住电缆手柄，将手臂呈 90 度角，肘部弯曲。","向前和向上按下电缆手柄，完全伸展手臂。","在顶部暂停片刻，然后慢慢将拉索手柄放回起始位置。","重复所需的重复次数，然后换到另一只手臂。"]},{"id":"1267","name":"cable one arm press on exercise ball","nameZh":"绳索单臂推举在健身球","equipment":"cable","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1267-MKIelrR.jpg","gifPath":"exercises/videos/1267-MKIelrR.gif","instructionSteps":["坐在健身球上，双脚平放在地上，背部挺直。","一只手握住电缆手柄，将手臂置于胸部高度，肘部弯曲。","将另一只手放在臀部上以保持稳定。","向前按电缆手柄，完全伸展手臂。","暂停片刻，然后慢慢回到起始位置。","重复所需的重复次数，然后换臂。"]},{"id":"1268","name":"cable press on exercise ball","nameZh":"绳索推举在健身球","equipment":"cable","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1268-vAwm6rK.jpg","gifPath":"exercises/videos/1268-vAwm6rK.gif","instructionSteps":["坐在健身球上，双脚平放在地上，膝盖呈 90 度角。","将电缆手柄保持在胸部高度，手掌朝下，肘部弯曲。","收紧核心并向前按压缆索手柄，直到手臂完全伸展。","暂停片刻，然后慢慢释放张力，并将电缆手柄拉回起始位置。","重复所需的重复次数。"]},{"id":"1269","name":"cable standing up straight crossovers","nameZh":"绳索站姿向上直交叉","equipment":"cable","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1269-UKWTJWR.jpg","gifPath":"exercises/videos/1269-UKWTJWR.gif","instructionSteps":["站在缆绳机中间，双脚分开与肩同宽。","手掌朝下握住电缆手柄，手臂伸直至两侧。","保持双臂伸直，将双手放在身体前面，相互交叉。","暂停片刻，然后慢慢回到起始位置，保持双臂伸展。","重复所需的重复次数。"]},{"id":"1270","name":"cable upper chest crossovers","nameZh":"绳索上胸交叉","equipment":"cable","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1270-j7XMAyn.jpg","gifPath":"exercises/videos/1270-j7XMAyn.gif","instructionSteps":["将手柄连接到胸部高度的电缆上。","站在绳索机的中央，一只脚稍微在另一只脚前面。","手掌朝下抓住手柄，手臂向两侧伸展。","保持肘部轻微弯曲并启动核心肌群。","将电缆在胸前拉到一起，使它们相互交叉。","在运动的最高点挤压胸部肌肉。","慢慢地将电缆释放回起始位置。","重复所需的重复次数。"]},{"id":"1271","name":"chest and front of shoulder stretch","nameZh":"胸部和前的肩拉伸","equipment":"body weight","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1271-Uto7l43.jpg","gifPath":"exercises/videos/1271-Uto7l43.gif","instructionSteps":["站直，双脚分开与肩同宽。","将双臂伸直至前方，与肩同高。","双臂交叉在身体前方，右臂放在左臂上方。","手指交叉并将手掌压在一起。","轻轻地将肩胛骨挤压在一起，然后将双手向前推，感觉胸部和肩膀前部有拉伸感。","保持拉伸 20-30 秒，然后放松。","重复所需的重复次数。"]},{"id":"1272","name":"chest stretch with exercise ball","nameZh":"胸部拉伸带健身球","equipment":"stability ball","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1272-ykA5tU7.jpg","gifPath":"exercises/videos/1272-ykA5tU7.gif","instructionSteps":["坐在稳定球上，双脚平放在地面上，背部挺直。","双手握住健身球，并将双臂伸直至身前。","慢慢地将健身球移向胸部，感受胸部肌肉的拉伸。","保持伸展几秒钟，然后慢慢回到起始位置。","重复所需的重复次数。"]},{"id":"1273","name":"clap push up","nameZh":"拍手俯卧撑","equipment":"body weight","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1273-wigSg76.jpg","gifPath":"exercises/videos/1273-wigSg76.gif","instructionSteps":["从高平板支撑位置开始，双手分开略宽于肩宽。","弯曲肘部，将身体降低到地面，保持核心参与。","爆发性地推动手掌，将身体推离地面。","在半空中时，拍手，然后回到起始位置。","重复所需的重复次数。"]},{"id":"1274","name":"deep push up","nameZh":"深度俯卧撑","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1274-vptOQ4N.jpg","gifPath":"exercises/videos/1274-vptOQ4N.gif","instructionSteps":["从高平板支撑位置开始，双手分开略宽于肩宽，身体呈一条直线。","弯曲肘部，使胸部靠近地面，使胸部靠近地面。","推动手掌以伸展手臂并返回到起始位置。","重复所需的重复次数。"]},{"id":"1275","name":"drop push up","nameZh":"爆发俯卧撑","equipment":"body weight","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1275-Q497lAE.jpg","gifPath":"exercises/videos/1275-Q497lAE.gif","instructionSteps":["从高平板支撑位置开始，双手分开略宽于肩宽。","将胸部压向地面，保持肘部靠近身体。","当你的胸部刚好高于地面时，迅速将膝盖放在地上。","伸展双臂，将自己推回到起始位置。","重复所需的重复次数。"]},{"id":"1276","name":"dumbbell decline one arm fly","nameZh":"哑铃下斜单臂飞鸟","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1276-NL6YBwN.jpg","gifPath":"exercises/videos/1276-NL6YBwN.gif","instructionSteps":["躺在斜凳上，一只手拿着哑铃，将其放在大腿上。","用大腿帮助举起哑铃，将其举至与肩同宽，手掌朝向躯干。","旋转手腕，使手掌朝前。","吸气时，将哑铃慢慢降低到一侧，直到感觉到胸部有拉伸感。","呼气并使用胸部肌肉将哑铃拉回到起始位置。","重复所需的重复次数，然后换臂。"]},{"id":"1277","name":"dumbbell fly on exercise ball","nameZh":"哑铃飞鸟在健身球","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1277-Lt3iWnf.jpg","gifPath":"exercises/videos/1277-Lt3iWnf.gif","instructionSteps":["坐在健身球上，每只手各握一个哑铃。","双脚向前走，身体向下滚动，直到头部、颈部和上背部得到球的支撑。","将双臂伸直至胸部上方，手掌相对。","稍微弯曲肘部，将手臂以宽弧线向两侧放低，直到感觉到胸部有拉伸感。","暂停片刻，然后反向运动并挤压胸部肌肉，同时将​​哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"1278","name":"dumbbell incline fly on exercise ball","nameZh":"哑铃上斜飞鸟在健身球","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1278-HYe1ZqR.jpg","gifPath":"exercises/videos/1278-HYe1ZqR.gif","instructionSteps":["设置一个 45 度角的上斜凳。","坐在健身球上，向前滚动，直到上背部靠在倾斜的长凳上。","双手各握一个哑铃，手掌相对，双臂伸至胸部上方。","将哑铃以宽弧线向两侧放低，直到感觉到胸部有拉伸感。","暂停片刻，然后挤压胸部肌肉，使哑铃回到起始位置。","重复所需的重复次数。"]},{"id":"1279","name":"dumbbell incline one arm fly","nameZh":"哑铃上斜单臂飞鸟","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1279-Gw2HFvW.jpg","gifPath":"exercises/videos/1279-Gw2HFvW.gif","instructionSteps":["将倾斜凳调整至 30-45 度角。","坐在长凳上，一只手拿着哑铃，将其放在大腿上。","向后躺在长凳上，双脚平放在地面上。","握住哑铃，手臂伸直越过胸部。","将哑铃以宽弧线向一侧放低，保持肘部轻微弯曲。","当手臂与地面平行时暂停，然后反向运动，使哑铃回到起始位置。","重复所需的重复次数，然后换臂。"]},{"id":"1280","name":"dumbbell incline one arm fly on exercise ball","nameZh":"哑铃上斜单臂飞鸟在健身球","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1280-LLNh6q5.jpg","gifPath":"exercises/videos/1280-LLNh6q5.gif","instructionSteps":["坐在健身球上，一只手拿着哑铃。","双脚向前走，身体向下滚动，直到头部、颈部和上背部得到球的支撑。","握住哑铃，手臂伸直越过胸部，手掌朝内。","慢慢地将哑铃向一侧放低，保持肘部轻微弯曲。","当手臂与地面平行时暂停片刻。","启动胸部肌肉，将哑铃拉回到起始位置。","重复所需的重复次数，然后换臂。"]},{"id":"1281","name":"dumbbell incline one arm press","nameZh":"哑铃上斜单臂推举","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1281-rDAiRf9.jpg","gifPath":"exercises/videos/1281-rDAiRf9.gif","instructionSteps":["坐在上斜凳上，一只手拿着哑铃，放在大腿上。","仰卧在长凳上，将哑铃置于与肩同高的位置，手掌朝前。","将哑铃向上并稍微向内推，充分伸展手臂。","在最高点暂停片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数，然后换到另一只手臂。"]},{"id":"1282","name":"dumbbell incline one arm press on exercise ball","nameZh":"哑铃上斜单臂推举在健身球","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1282-Bg5JKSH.jpg","gifPath":"exercises/videos/1282-Bg5JKSH.gif","instructionSteps":["坐在健身球上，一只手拿着哑铃，双脚平放在地上。","慢慢地向前移动你的脚，滚动球，直到你的头、脖子和上背部得到球的支撑。","将哑铃握在与肩同高的位置，手掌朝前。","向上推哑铃，直到手臂完全伸展。","在最高点暂停片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数，然后换到另一只手臂。"]},{"id":"1283","name":"dumbbell incline press on exercise ball","nameZh":"哑铃上斜推举在健身球","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1283-bfiHMpI.jpg","gifPath":"exercises/videos/1283-bfiHMpI.gif","instructionSteps":["坐在健身球上，每只手各握一个哑铃，手掌朝前。","双脚慢慢向前移动，身体沿着球滚动，直到头部、颈部和上背部得到球的支撑。","将哑铃保持在与肩同高的位置，肘部弯曲并指向两侧。","向上推哑铃，充分伸展手臂。","在最高点暂停片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"1284","name":"dumbbell lying pullover on exercise ball","nameZh":"哑铃仰卧仰卧屈臂上拉在健身球","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1284-iK59oEA.jpg","gifPath":"exercises/videos/1284-iK59oEA.gif","instructionSteps":["坐在健身球上，向前滚动，直到上背部靠在球上。","双手握住哑铃，将手臂伸直至胸部上方。","慢慢地将哑铃放到脑后，同时保持手臂伸直。","暂停片刻，然后将哑铃举回到起始位置。","重复所需的重复次数。"]},{"id":"1285","name":"dumbbell one arm bench fly","nameZh":"哑铃单臂凳飞鸟","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1285-o5Jsk92.jpg","gifPath":"exercises/videos/1285-o5Jsk92.gif","instructionSteps":["坐在平坦的长凳上，一只手拿着哑铃，将其放在大腿上方。","向后躺在长凳上，将哑铃压在大腿上。","用空着的那只手帮助将哑铃举至起始位置。","将哑铃握在肩膀正上方，手臂伸展，手掌朝内。","将哑铃以宽弧线向一侧放低，保持肘部轻微弯曲。","当手臂与地面平行时暂停，然后反向运动并将哑铃带回起始位置。","重复所需的重复次数，然后换臂重复。"]},{"id":"1286","name":"dumbbell one arm chest fly on exercise ball","nameZh":"哑铃单臂胸部飞鸟在健身球","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1286-Bpkf41o.jpg","gifPath":"exercises/videos/1286-Bpkf41o.gif","instructionSteps":["坐在健身球上，一只手拿着哑铃，双脚平放在地上。","双脚向前走，滚动球，直到你的上背部受到球的支撑，并且你的头、脖子和肩膀离开球。","将手臂伸直，将哑铃举至胸部上方，手掌朝内。","慢慢地将哑铃向一侧放低，保持肘部轻微弯曲。","当手臂与地面平行时暂停片刻。","启动胸部肌肉，将哑铃拉回到起始位置。","重复所需的重复次数，然后换臂。"]},{"id":"1287","name":"dumbbell one arm decline chest press","nameZh":"哑铃单臂下斜胸部推举","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1287-REGM1dE.jpg","gifPath":"exercises/videos/1287-REGM1dE.gif","instructionSteps":["躺在下斜长凳上，一只手握住哑铃，放在胸前。","将双脚平放在地面上，并将背部压在长凳上。","伸展手臂，将哑铃推向天花板，充分伸展肘部。","在顶部停顿片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数，然后换到另一只手臂。"]},{"id":"1288","name":"dumbbell one arm fly on exercise ball","nameZh":"哑铃单臂飞鸟在健身球","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1288-Am02iPd.jpg","gifPath":"exercises/videos/1288-Am02iPd.gif","instructionSteps":["坐在健身球上，一只手拿着哑铃，双脚平放在地上。","双脚向前走，身体向下滚动，直到上背部靠在健身球上。","将手臂伸直，将哑铃举至胸部上方，手掌朝内。","慢慢地将哑铃向一侧放低，保持肘部轻微弯曲。","暂停片刻，然后挤压胸部肌肉，使哑铃回到起始位置。","重复所需的重复次数，然后换臂。"]},{"id":"1289","name":"dumbbell one arm incline chest press","nameZh":"哑铃单臂上斜胸部推举","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1289-PDaMuyV.jpg","gifPath":"exercises/videos/1289-PDaMuyV.gif","instructionSteps":["将上斜凳调整至 45 度角。","坐在长凳上，背部靠在垫子上，双脚平放在地面上。","一只手握住哑铃，正手握住，将其放在肩膀上。","将哑铃向上推离身体，完全伸展手臂。","在顶部停顿片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数，然后换到另一只手臂。"]},{"id":"1290","name":"dumbbell one arm press on exercise ball","nameZh":"哑铃单臂推举在健身球","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1290-QZFv5ui.jpg","gifPath":"exercises/videos/1290-QZFv5ui.gif","instructionSteps":["坐在健身球上，双脚平放在地上，膝盖弯曲成 90 度角。","一只手握住哑铃，将其置于与肩同高的位置，肘部弯曲，手掌朝前。","慢慢向上推哑铃，直到手臂完全伸展，同时保持核心收紧并在健身球上保持平衡。","在最高点暂停片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数，然后换到另一只手臂。"]},{"id":"1291","name":"dumbbell one arm pullover on exercise ball","nameZh":"哑铃单臂仰卧屈臂上拉在健身球","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1291-bQHPBU3.jpg","gifPath":"exercises/videos/1291-bQHPBU3.gif","instructionSteps":["坐在健身球上，双脚平放在地上，膝盖弯曲成 90 度角。","用一只手握住哑铃，将手臂伸直至胸部上方。","慢慢地将哑铃放到脑后，同时保持手臂伸直。","暂停片刻，然后将哑铃举回到起始位置。","重复所需的重复次数，然后换臂。"]},{"id":"1292","name":"dumbbell one leg fly on exercise ball","nameZh":"哑铃单腿飞鸟在健身球","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1292-pH2x2jj.jpg","gifPath":"exercises/videos/1292-pH2x2jj.gif","instructionSteps":["坐在健身球上，双手各握一个哑铃，手掌相对。","将一只脚放在地面上，并将另一条腿伸直到您面前。","稍微向前倾，将手臂向两侧伸出，保持肘部轻微弯曲。","慢慢地将哑铃向两侧放低，感觉胸部有拉伸感。","在底部暂停片刻，然后挤压胸部肌肉，使哑铃回到起始位置。","重复所需的重复次数，然后换腿并重复。"]},{"id":"1293","name":"dumbbell press on exercise ball","nameZh":"哑铃推举在健身球","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1293-O8o7q4d.jpg","gifPath":"exercises/videos/1293-O8o7q4d.gif","instructionSteps":["坐在健身球上，双脚平放在地上，双手各握哑铃，放在大腿上。","慢慢地向前移动双脚，滚动健身球，直到下背部受到球的支撑并且膝盖呈 90 度角。","将哑铃举至肩高，手掌朝前。","向上推哑铃，直到手臂完全伸展。","在最高点暂停片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"1294","name":"dumbbell pullover hip extension on exercise ball","nameZh":"哑铃仰卧屈臂上拉髋伸展在健身球","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1294-lI7easp.jpg","gifPath":"exercises/videos/1294-lI7easp.gif","instructionSteps":["坐在健身球上，双脚平放在地面上，哑铃放在大腿上。","慢慢地向前移动你的脚，将健身球沿着你的背部滚动，直到你的头部、颈部和上背部得到球的支撑。","双手握住哑铃，将手臂伸直至胸部上方，肘部保持轻微弯曲。","将哑铃放在脑后，保持手臂伸直并保持控制。","暂停片刻，然后将哑铃举回到起始位置。","在保持双臂伸展的同时，将臀部抬离地面，挤压臀肌并启动核心肌群。","将臀部放低至起始位置。","重复所需的重复次数。"]},{"id":"1295","name":"dumbbell pullover on exercise ball","nameZh":"哑铃仰卧屈臂上拉在健身球","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1295-FSD6PGL.jpg","gifPath":"exercises/videos/1295-FSD6PGL.gif","instructionSteps":["坐在健身球上，双手握住哑铃，置于胸前，双臂伸展。","慢慢地将哑铃放到脑后，同时保持手臂伸直。","暂停片刻，然后将哑铃举回到起始位置。","重复所需的重复次数。"]},{"id":"1296","name":"exercise ball pike push up","nameZh":"健身球派克式俯卧撑","equipment":"stability ball","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1296-sVvXT5J.jpg","gifPath":"exercises/videos/1296-sVvXT5J.gif","instructionSteps":["从俯卧撑位置开始，双手放在地板上，小腿放在稳定球上。","收紧核心肌群，将臀部抬向天花板，将球滚向双手。","保持双腿伸直，身体呈屈体姿势，形成倒V字形。","弯曲肘部，将上半身降低到地板上，保持头部与双手在一条直线上。","用手推动并伸展双臂以返回到起始位置。","重复所需的重复次数。"]},{"id":"1297","name":"isometric chest squeeze","nameZh":"等长胸部挤压","equipment":"body weight","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1297-HbSG1Pw.jpg","gifPath":"exercises/videos/1297-HbSG1Pw.gif","instructionSteps":["双脚分开与肩同宽站立，膝盖稍微弯曲。","将双臂伸直在身前，与地面平行，手掌相对。","尽可能用力挤压胸部肌肉，同时保持手臂伸直。","保持这个姿势几秒钟，专注于收缩胸部肌肉。","释放挤压并放松胸部肌肉。","重复所需的重复次数。"]},{"id":"1298","name":"kettlebell one arm floor press","nameZh":"壶铃单臂地面推举","equipment":"kettlebell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1298-rg59QCH.jpg","gifPath":"exercises/videos/1298-rg59QCH.gif","instructionSteps":["仰卧在地板上，膝盖弯曲，双脚平放在地面上。","一只手握住壶铃，手掌朝向脚部，手臂笔直向上伸向天花板。","弯曲肘部，慢慢将壶铃降低到胸部，保持上臂靠近身体。","当壶铃位于胸部正上方时暂停片刻，然后通过伸展肘部将壶铃推回起始位置。","重复所需的重复次数，然后换到另一只手臂。"]},{"id":"1299","name":"lever incline chest press","nameZh":"杠杆机上斜胸部推举","equipment":"leverage machine","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1299-jHAnWmT.jpg","gifPath":"exercises/videos/1299-jHAnWmT.gif","instructionSteps":["将杠杆机的座椅和靠背调整到舒适的位置。","坐在机器上，背部靠在靠背上，双脚平放在地板上。","正手握住手柄，双手之间的距离略大于肩宽。","向前推动手柄并使其远离身体，直到双臂完全伸展。","暂停片刻，然后慢慢弯曲肘部，将手柄放回到胸部。","重复所需的重复次数。"]},{"id":"1300","name":"lever decline chest press","nameZh":"杠杆机下斜胸部推举","equipment":"leverage machine","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1300-vsVoPHt.jpg","gifPath":"exercises/videos/1300-vsVoPHt.gif","instructionSteps":["将杠杆机的座椅高度和靠背调整到舒适的位置。","坐在机器上，背部靠在靠背上，双脚平放在地板上。","正手握住手柄，双手之间的距离略大于肩宽。","向前推动手柄并使其远离身体，直到双臂完全伸展。","慢慢地将手柄放回胸部，保持肘部稍微弯曲。","在底部暂停片刻，然后将手柄推回起始位置。","重复所需的重复次数。"]},{"id":"1301","name":"machine inner chest press","nameZh":"器械内侧胸部推举","equipment":"leverage machine","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1301-wDN97Ca.jpg","gifPath":"exercises/videos/1301-wDN97Ca.gif","instructionSteps":["调整座椅高度，将自己放在机器上，背部平放在垫子上。","正手握住手柄，肘部呈 90 度角。","向前推动手柄，直到手臂完全伸展，运动过程中呼气。","动作结束时暂停片刻，然后慢慢回到起始位置，同时吸气。","重复所需的重复次数。"]},{"id":"1302","name":"medicine ball chest pass","nameZh":"药球胸部传","equipment":"medicine ball","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1302-aDoFKrE.jpg","gifPath":"exercises/videos/1302-aDoFKrE.gif","instructionSteps":["双脚分开与肩同宽站立，将健身球保持在胸部水平。","向前伸展双臂，用力将药球推离胸部。","当你释放球时，用你的手臂和躯干将球从后脚转移到前脚。","当球从墙壁或伙伴身上反弹时接住球，并立即重复该动作。","继续进行所需的重复次数。"]},{"id":"1303","name":"medicine ball chest push from 3 point stance","nameZh":"药球胸部推从3 点支撑","equipment":"medicine ball","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1303-dCJnuVq.jpg","gifPath":"exercises/videos/1303-dCJnuVq.gif","instructionSteps":["以三点姿势开始，一只手放在健身球上，另一只手放在地上。","伸展双腿并将身体摆成一条直线。","将胸部压向地面，同时保持背部挺直。","将药球推离身体，完全伸展手臂。","返回起始位置并重复所需的重复次数。"]},{"id":"1304","name":"medicine ball chest push multiple response","nameZh":"药球胸部推多次反应","equipment":"medicine ball","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1304-7aolH9D.jpg","gifPath":"exercises/videos/1304-7aolH9D.gif","instructionSteps":["双脚分开与肩同宽站立，将药球举至胸部水平。","向前伸展双臂，将药球推离胸部。","暂停片刻，然后慢慢地将健身球放回胸前。","重复所需的重复次数。"]},{"id":"1305","name":"medicine ball chest push single response","nameZh":"药球胸部推单次反应","equipment":"medicine ball","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1305-jeHtrlO.jpg","gifPath":"exercises/videos/1305-jeHtrlO.gif","instructionSteps":["双脚分开与肩同宽站立，将健身球保持在胸部水平。","向前伸展双臂，将药球推离胸部。","暂停片刻，然后慢慢地将健身球放回胸前。","重复所需的重复次数。"]},{"id":"1306","name":"plyo push up","nameZh":"爆发式俯卧撑","equipment":"body weight","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1306-Snj1wSv.jpg","gifPath":"exercises/videos/1306-Snj1wSv.gif","instructionSteps":["从高平板支撑位置开始，双手分开略宽于肩宽。","弯曲肘部，将胸部压向地面，保持身体呈一条直线。","爆发性地推离地面，利用胸部肌肉将上半身推离地面。","双手回到起始位置，轻轻落地。","重复所需的重复次数。"]},{"id":"1307","name":"push up on bosu ball","nameZh":"俯卧撑在波速球","equipment":"bosu ball","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1307-wVompEp.jpg","gifPath":"exercises/videos/1307-wVompEp.gif","instructionSteps":["将博苏球平放在地上，平面朝上。","将自己置于俯卧撑位置，双手放在博苏球的外边缘。","弯曲肘部，调动核心力量，将身体向博苏球方向降低。","伸展双臂，将自己推回到起始位置。","重复所需的重复次数。"]},{"id":"1308","name":"smith wide grip bench press","nameZh":"史密斯宽距卧推","equipment":"smith machine","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1308-zoOvPcx.jpg","gifPath":"exercises/videos/1308-zoOvPcx.gif","instructionSteps":["将史密斯机上的长凳调整到舒适的位置。","躺在长凳上，双脚平放在地上。","宽握距抓住杠铃，握距略宽于肩宽。","松开杠铃并将其慢慢降低到胸部，保持肘部向两侧伸出。","当杠铃触及胸部时暂停片刻。","将杠铃推回到起始位置，完全伸展双臂。","重复所需的重复次数。"]},{"id":"1309","name":"smith wide grip decline bench press","nameZh":"史密斯宽距下斜卧推","equipment":"smith machine","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1309-wi2H9QX.jpg","gifPath":"exercises/videos/1309-wi2H9QX.gif","instructionSteps":["将下斜凳调整至所需角度。","躺在长凳上，双脚固定在脚垫下。","宽握距抓住杠铃，握距略宽于肩宽。","松开杠铃并将其慢慢降低到胸部，保持肘部朝外。","当杠铃触及胸部时暂停片刻。","将杠铃推回到起始位置，完全伸展双臂。","重复所需的重复次数。"]},{"id":"1310","name":"weighted drop push up","nameZh":"负重爆发俯卧撑","equipment":"weighted","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1310-PSlvNMs.jpg","gifPath":"exercises/videos/1310-PSlvNMs.gif","instructionSteps":["从高位平板支撑开始，双手分开略宽于肩宽，双脚并拢。","将胸部压向地面，保持肘部靠近身体。","一旦你的胸部刚好高于地面，爆发性地把自己推起来，将双手抬离地面。","当你向上推时，快速将双手移至两侧并稍微向前，让你的身体向地面落下。","将双手置于更宽的位置，然后立即再次将胸部降低到地面。","重复俯卧撑动作，下降并用双手抓住自己在较窄的位置。","继续在更宽和更窄的手位置之间交替，以达到所需的重复次数。"]},{"id":"1311","name":"wide hand push up","nameZh":"宽手俯卧撑","equipment":"body weight","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1311-JmMVpR3.jpg","gifPath":"exercises/videos/1311-JmMVpR3.gif","instructionSteps":["从高平板支撑位置开始，双手分开比肩宽。","保持身体从头到脚呈一条直线。","弯曲肘部，将胸部压向地面，使其靠近身体两侧。","推动手掌以伸展手臂并返回到起始位置。","重复所需的重复次数。"]},{"id":"1312","name":"medicine ball chest push with run release","nameZh":"药球胸部推带跑动释放","equipment":"medicine ball","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1312-pX9Elbe.jpg","gifPath":"exercises/videos/1312-pX9Elbe.gif","instructionSteps":["双脚分开与肩同宽站立，将药球举至胸部水平。","右脚向前迈出一步，同时向前推动药球，充分伸展双臂。","当你向前推动球时，松开它并让它向前滚动。","快速向前跑，在球落地之前接住球。","接住球后，将其放回胸前，左脚向前重复该动作。","继续交替双腿并重复练习达到所需的重复次数。"]},{"id":"1313","name":"lever unilateral row","nameZh":"杠杆机单侧划船","equipment":"leverage machine","bodyPart":"back","target":"upper back","imagePath":"exercises/images/1313-oROuvrX.jpg","gifPath":"exercises/videos/1313-oROuvrX.gif","instructionSteps":["调整座椅高度并将自己面向机器。","正手握住手柄并保持背部挺直。","将手柄拉向身体，将肩胛骨挤压在一起。","在动作的最高点停顿片刻，然后慢慢松开并伸展手臂回到起始位置。","重复所需的重复次数。"]},{"id":"1314","name":"back extension on exercise ball","nameZh":"背伸展在健身球","equipment":"stability ball","bodyPart":"back","target":"spine","imagePath":"exercises/images/1314-qLpO4vV.jpg","gifPath":"exercises/videos/1314-qLpO4vV.gif","instructionSteps":["将稳定球放在地面上，面朝下躺在上面，臀部放在球上，双脚靠在墙壁或其他稳定的表面上。","将双手放在脑后或交叉在胸前。","启动你的核心，慢慢地将你的上半身抬离球，伸展你的背部，直到你的身体从头部到脚后跟形成一条直线。","在顶部停顿片刻，然后慢慢将上半身放回起始位置。","重复所需的重复次数。"]},{"id":"1316","name":"barbell bent arm pullover","nameZh":"杠铃屈臂仰卧屈臂上拉","equipment":"barbell","bodyPart":"back","target":"lats","imagePath":"exercises/images/1316-cA9FuWG.jpg","gifPath":"exercises/videos/1316-cA9FuWG.gif","instructionSteps":["平躺在长凳上，头放在一端，双脚放在地板上。","握距与肩同宽，握住杠铃，将手臂伸直至胸部上方。","将杠铃放在脑后，同时保持手臂稍微弯曲。","暂停片刻，然后将杠铃举回起始位置。","重复所需的重复次数。"]},{"id":"1317","name":"barbell reverse grip incline bench row","nameZh":"杠铃反握上斜凳划船","equipment":"barbell","bodyPart":"back","target":"upper back","imagePath":"exercises/images/1317-8d8qJQI.jpg","gifPath":"exercises/videos/1317-8d8qJQI.gif","instructionSteps":["设置一个 45 度角的上斜凳。","坐在长凳上，面向靠背，胸部靠在靠背上。","反握（手掌朝下）抓住杠铃，双手距离略宽于肩宽。","保持背部挺直，核心参与。","将杠铃拉向上腹部，将肩胛骨挤压在一起。","在动作的最高点停顿片刻。","慢慢地将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"1318","name":"cable incline bench row","nameZh":"绳索上斜凳划船","equipment":"cable","bodyPart":"back","target":"upper back","imagePath":"exercises/images/1318-yaMIo4D.jpg","gifPath":"exercises/videos/1318-yaMIo4D.gif","instructionSteps":["以 45 度角设置一个上斜凳，并将绳索手柄连接到低滑轮上。","坐在长凳上，面向电缆机，双脚平放在地板上，膝盖稍微弯曲。","正手握住电缆手柄，并将双臂完全伸展到身前。","从臀部开始向前倾，同时保持背部挺直，核心肌群参与。","缩回肩胛骨并弯曲肘部，将电缆手柄拉向胸部。","在动作的最高点挤压背部肌肉，然后慢慢伸展手臂回到起始位置。","重复所需的重复次数。"]},{"id":"1319","name":"cable palm rotational row","nameZh":"绳索手掌旋转划船","equipment":"cable","bodyPart":"back","target":"upper back","imagePath":"exercises/images/1319-OmQ8w0p.jpg","gifPath":"exercises/videos/1319-OmQ8w0p.gif","instructionSteps":["将手柄连接到腰部高度的缆绳机上。","面向机器站立，双脚分开与肩同宽。","正手握住手柄，手掌朝下。","向后退一步，在绳索上产生张力，保持背部挺直，膝盖稍微弯曲。","将手柄拉向身体，同时将手掌旋转至向上。","在动作结束时将肩胛骨挤压在一起。","慢慢松开手柄回到起始位置。","重复所需的重复次数。"]},{"id":"1320","name":"cable rope crossover seated row","nameZh":"绳索绳索交叉坐姿划船","equipment":"cable","bodyPart":"back","target":"upper back","imagePath":"exercises/images/1320-UFGF6gk.jpg","gifPath":"exercises/videos/1320-UFGF6gk.gif","instructionSteps":["坐在划船机上，双脚平放在脚踏板上，膝盖稍微弯曲。","正手握住缆绳，手掌相对。","稍微向后倾斜，保持背部挺直，核心肌群参与。","将缆绳拉向胸部，将肩胛骨挤压在一起。","在动作的最高点停顿片刻，然后慢慢释放张力，回到起始位置。","重复所需的重复次数。"]},{"id":"1321","name":"cable rope elevated seated row","nameZh":"绳索绳索抬高坐姿划船","equipment":"cable","bodyPart":"back","target":"upper back","imagePath":"exercises/images/1321-c8oybX6.jpg","gifPath":"exercises/videos/1321-c8oybX6.gif","instructionSteps":["坐在面向电缆机的高架座椅上。","正手握住缆绳手柄，手掌相对。","保持背部挺直并稍微向后倾斜，保持膝盖轻微弯曲。","通过缩回肩胛骨并挤压背部肌肉，将电缆拉向您的身体。","在完全收缩的位置暂停片刻。","慢慢释放压力并将手臂伸回到起始位置。","重复所需的重复次数。"]},{"id":"1322","name":"cable rope extension incline bench row","nameZh":"绳索绳索伸展上斜凳划船","equipment":"cable","bodyPart":"back","target":"upper back","imagePath":"exercises/images/1322-MgKwAAo.jpg","gifPath":"exercises/videos/1322-MgKwAAo.gif","instructionSteps":["以 45 度角设置上斜凳，并将绳索机连接到低滑轮上。","将绳索手柄连接到缆绳机上，然后坐在面向机器的倾斜长凳上。","正手抓住绳索把手，身体前倾，保持背部挺直。","充分伸展双臂，将绳子拉向上胸部，同时保持肘部靠近身体。","在动作结束时将肩胛骨挤压在一起。","慢慢释放张力并回到起始位置。","重复所需的重复次数。"]},{"id":"1323","name":"cable rope seated row","nameZh":"绳索绳索坐姿划船","equipment":"cable","bodyPart":"back","target":"upper back","imagePath":"exercises/images/1323-SJqRxOt.jpg","gifPath":"exercises/videos/1323-SJqRxOt.gif","instructionSteps":["坐在划船机上，双脚平放在脚踏板上，膝盖稍微弯曲。","正手握住缆绳，手掌相对。","保持背部挺直，稍微向前倾斜，肘部保持轻微弯曲。","将缆绳拉向身体，将肩胛骨挤压在一起。","在动作的最高点停顿片刻，然后慢慢释放张力，回到起始位置。","重复所需的重复次数。"]},{"id":"1324","name":"cable upper row","nameZh":"绳索上划船","equipment":"cable","bodyPart":"back","target":"upper back","imagePath":"exercises/images/1324-PQStVXH.jpg","gifPath":"exercises/videos/1324-PQStVXH.gif","instructionSteps":["将直杆连接到胸部高度的缆绳机上。","面向机器站立，双脚分开与肩同宽。","正手握住杠铃，双手距离略宽于肩宽。","保持背部挺直，核心肌群参与。","将杠铃拉向上胸部，将肩胛骨挤压在一起。","在动作的最高点停顿片刻。","慢慢地将杠铃释放回起始位置。","重复所需的重复次数。"]},{"id":"1325","name":"cable wide grip rear pulldown behind neck","nameZh":"绳索宽距后下拉颈后","equipment":"cable","bodyPart":"back","target":"lats","imagePath":"exercises/images/1325-CmEr4pM.jpg","gifPath":"exercises/videos/1325-CmEr4pM.gif","instructionSteps":["调整缆绳机，使下拉杆位于您头部上方的高度。","坐在座椅上，用宽的正手握法抓住下拉杆。","稍微向后倾斜时，保持背部挺直，挺胸。","将杠铃向下拉至上胸部，将肩胛骨挤压在一起。","在动作底部暂停片刻，然后慢慢将杠铃释放回起始位置。","重复所需的重复次数。"]},{"id":"1326","name":"chin-up","nameZh":"反握引体向上","equipment":"body weight","bodyPart":"back","target":"lats","imagePath":"exercises/images/1326-T2mxWqc.jpg","gifPath":"exercises/videos/1326-T2mxWqc.gif","instructionSteps":["悬挂在引体向上杆上，手掌朝向自己，双手与肩同宽。","启动核心肌群，将身体拉向杠铃杆，以胸部为主导。","继续拉，直到下巴位于杠铃上方。","在顶部停顿片刻，然后慢慢将身体放回起始位置。","重复所需的重复次数。"]},{"id":"1327","name":"close grip chin-up","nameZh":"窄距反握引体向上","equipment":"body weight","bodyPart":"back","target":"lats","imagePath":"exercises/images/1327-VnfUNW7.jpg","gifPath":"exercises/videos/1327-VnfUNW7.gif","instructionSteps":["抓住引体向上杆，手掌朝向自己，双手与肩同宽。","悬挂在杠上，双臂完全伸展，双脚离开地面。","收紧背部肌肉，将身体拉向杠铃杆，保持肘部靠近身体。","继续拉，直到下巴位于杠铃上方。","在顶部停顿片刻，然后慢慢将身体放回起始位置。","重复所需的重复次数。"]},{"id":"1328","name":"dumbbell lying rear delt row","nameZh":"哑铃仰卧后三角肌划船","equipment":"dumbbell","bodyPart":"back","target":"upper back","imagePath":"exercises/images/1328-XUUD0Fs.jpg","gifPath":"exercises/videos/1328-XUUD0Fs.gif","instructionSteps":["脸朝下躺在平坦的长凳上，每只手各握一个哑铃，手掌朝内。","将手臂伸直向下伸向地板，肘部保持轻微弯曲。","调动背部肌肉，将哑铃举向胸部，将肩胛骨挤压在一起。","在顶部停顿片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"1329","name":"dumbbell palm rotational bent over row","nameZh":"哑铃手掌旋转俯身划船","equipment":"dumbbell","bodyPart":"back","target":"upper back","imagePath":"exercises/images/1329-wt6rwjk.jpg","gifPath":"exercises/videos/1329-wt6rwjk.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个哑铃，正握。","臀部向前弯曲，保持背部挺直，膝盖稍微弯曲。","让你的手臂笔直下垂，手掌朝向身体。","收紧核心肌群，将哑铃拉向胸部，保持肘部靠近身体。","当你向上拉哑铃时，旋转手掌，使其背向身体。","在动作的最高点将肩胛骨挤压在一起。","慢慢地将哑铃放回起始位置，将手掌旋转回起始位置。","重复所需的重复次数。"]},{"id":"1330","name":"dumbbell reverse grip incline bench one arm row","nameZh":"哑铃反握上斜凳单臂划船","equipment":"dumbbell","bodyPart":"back","target":"upper back","imagePath":"exercises/images/1330-ZIViNh1.jpg","gifPath":"exercises/videos/1330-ZIViNh1.gif","instructionSteps":["设置一个 45 度角的上斜凳。","将哑铃放在长凳旁边的地板上。","面对长凳站立，双脚分开与肩同宽。","弯曲腰部，将左膝和左手放在长凳上以获得支撑。","用右手反握（手掌朝下）拿起哑铃。","保持背部挺直，核心肌群参与。","将哑铃向上拉向胸部，保持肘部靠近身体。","在动作的最高点挤压背部肌肉。","以受控的方式将哑铃放回起始位置。","重复所需的重复次数。","换边并用左臂重复练习。"]},{"id":"1331","name":"dumbbell reverse grip incline bench two arm row","nameZh":"哑铃反握上斜凳双臂划船","equipment":"dumbbell","bodyPart":"back","target":"upper back","imagePath":"exercises/images/1331-9pQSkH8.jpg","gifPath":"exercises/videos/1331-9pQSkH8.gif","instructionSteps":["设置一个 45 度角的上斜凳。","坐在长凳上，胸部靠在靠背上，双脚平放在地上。","双手各握一个哑铃，反握。","身体前倾，双臂伸直下垂，完全伸展。","将哑铃拉向胸部，将肩胛骨挤压在一起。","在顶部停顿片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"1332","name":"exercise ball alternating arm ups","nameZh":"健身球交替臂向上s","equipment":"stability ball","bodyPart":"back","target":"lats","imagePath":"exercises/images/1332-EyLrNC2.jpg","gifPath":"exercises/videos/1332-EyLrNC2.gif","instructionSteps":["坐在稳定球上，双脚平放在地面上，背部挺直。","双手各握一个哑铃，手掌朝内，双臂在身体两侧向下伸展。","启动你的核心，慢慢地将一只手臂向肩膀抬起，保持肘部稍微弯曲。","在顶部暂停片刻，然后慢慢将手臂放回起始位置。","用另一只手臂重复该动作。","继续交替手臂进行所需的重复次数。"]},{"id":"1333","name":"exercise ball back extension with arms extended","nameZh":"健身球背伸展带手臂伸展","equipment":"stability ball","bodyPart":"back","target":"spine","imagePath":"exercises/images/1333-PERjVm8.jpg","gifPath":"exercises/videos/1333-PERjVm8.gif","instructionSteps":["将稳定球放在地上，面朝下躺在上面，臀部放在球上，双脚靠在墙上以保持稳定。","将双臂伸直在身前，手掌朝下。","启动你的核心，慢慢地将上半身抬离球，保持背部挺直，颈部与脊柱成一直线。","在顶部停顿片刻，然后慢慢将上半身放回起始位置。","重复所需的重复次数。"]},{"id":"1334","name":"exercise ball back extension with hands behind head","nameZh":"健身球背伸展带手头后","equipment":"stability ball","bodyPart":"back","target":"spine","imagePath":"exercises/images/1334-o1HGDSq.jpg","gifPath":"exercises/videos/1334-o1HGDSq.gif","instructionSteps":["将稳定球放在地上，面朝下躺在上面，臀部放在球上。","将脚靠在墙壁或其他稳定的表面上以获得支撑。","双臂交叉于脑后，双手触碰后脑勺。","启动你的核心，慢慢地将你的上半身抬离球，伸展你的背部，直到你的身体从头部到臀部形成一条直线。","在动作的最高点暂停片刻，然后慢慢将上半身放回起始位置。","重复所需的重复次数。"]},{"id":"1335","name":"exercise ball back extension with knees off ground","nameZh":"健身球背伸展带膝盖离地面","equipment":"stability ball","bodyPart":"back","target":"spine","imagePath":"exercises/images/1335-WME869U.jpg","gifPath":"exercises/videos/1335-WME869U.gif","instructionSteps":["将稳定球放在地上，面朝下躺在上面，臀部放在球上，双脚靠在墙上以保持稳定。","将双手放在脑后或交叉在胸前。","启动你的核心，慢慢地将你的上半身抬离球，伸展你的背部，直到你的身体从头部到脚后跟形成一条直线。","在顶部停顿片刻，然后慢慢将上半身放回起始位置。","重复所需的重复次数。"]},{"id":"1336","name":"exercise ball back extension with rotation","nameZh":"健身球背伸展带旋转","equipment":"stability ball","bodyPart":"back","target":"spine","imagePath":"exercises/images/1336-WVD66ff.jpg","gifPath":"exercises/videos/1336-WVD66ff.gif","instructionSteps":["首先，面朝下躺在稳定球上，臀部放在球上，双脚牢牢踩在地面上。","将双手放在脑后或交叉放在胸前。","启动你的核心，慢慢地将你的上半身抬离球，伸展你的背部，直到你的身体从头部到脚后跟形成一条直线。","在顶部停顿片刻，然后慢慢将躯干旋转到一侧，保持臀部和腿部稳定。","返回中心并重复旋转到另一侧。","将上半身放低至起始位置，然后重复所需的重复次数。"]},{"id":"1338","name":"exercise ball hug","nameZh":"健身球抱","equipment":"stability ball","bodyPart":"back","target":"spine","imagePath":"exercises/images/1338-d7z1Y7V.jpg","gifPath":"exercises/videos/1338-d7z1Y7V.gif","instructionSteps":["坐在稳定球上，双脚平放在地面上，背部挺直。","用双手握住稳定球，将其抱在靠近胸部的位置。","启动你的核心肌肉，慢慢向后倾斜，保持背部挺直，双脚踩在地上。","继续向后倾斜，直到感觉到背部肌肉伸展。","保持该姿势几秒钟，然后慢慢回到起始位置。","重复所需的重复次数。"]},{"id":"1339","name":"exercise ball lat stretch","nameZh":"健身球背阔肌拉伸","equipment":"stability ball","bodyPart":"back","target":"lats","imagePath":"exercises/images/1339-sM84pE4.jpg","gifPath":"exercises/videos/1339-sM84pE4.gif","instructionSteps":["坐在稳定球上，双脚平放在地面上，背部挺直。","一只手握住哑铃，然后将手臂伸直至头顶。","慢慢地向另一侧倾斜，感受背阔肌的拉伸。","保持伸展动作 20-30 秒，然后回到起始位置。","在另一侧重复。"]},{"id":"1341","name":"exercise ball lower back stretch (pyramid)","nameZh":"健身球下背拉伸 (金字塔)","equipment":"stability ball","bodyPart":"back","target":"lats","imagePath":"exercises/images/1341-yU7w7CA.jpg","gifPath":"exercises/videos/1341-yU7w7CA.gif","instructionSteps":["坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。","慢慢地向前移动你的脚，将球沿着你的背部滚动，直到你的下背部靠在球上。","将双手放在脑后或交叉放在胸前。","启动你的核心，慢慢地将你的上半身降低到地面，让你的下背部伸展到球上方。","保持伸展几秒钟，然后慢慢回到起始位置。","重复所需的重复次数。"]},{"id":"1342","name":"exercise ball lying side lat stretch","nameZh":"健身球仰卧侧背阔肌拉伸","equipment":"stability ball","bodyPart":"back","target":"lats","imagePath":"exercises/images/1342-rTbyBYV.jpg","gifPath":"exercises/videos/1342-rTbyBYV.gif","instructionSteps":["侧躺，双腿伸展，头部由稳定球支撑。","将上臂放在球上以保持稳定性。","将上臂举过头顶，让躯干稍微旋转。","感受身体一侧背阔肌的拉伸。","保持拉伸 20-30 秒，然后换边重复。"]},{"id":"1343","name":"exercise ball prone leg raise","nameZh":"健身球俯卧抬腿","equipment":"stability ball","bodyPart":"back","target":"spine","imagePath":"exercises/images/1343-lCKm4Rs.jpg","gifPath":"exercises/videos/1343-lCKm4Rs.gif","instructionSteps":["面朝下躺在垫子上，双腿伸展，脚趾放在稳定球上。","将双手放在地上，与肩同宽，锻炼核心肌肉。","保持双腿伸直，慢慢将它们抬离地面，用下背部和臀部将它们尽可能抬高。","在顶部暂停片刻，然后慢慢将双腿放回起始位置。","重复所需的重复次数。"]},{"id":"1344","name":"ez bar reverse grip bent over row","nameZh":"曲杠反握俯身划船","equipment":"ez barbell","bodyPart":"back","target":"upper back","imagePath":"exercises/images/1344-G8dXpNG.jpg","gifPath":"exercises/videos/1344-G8dXpNG.gif","instructionSteps":["站立，双脚分开与肩同宽，膝盖稍微弯曲。","反手握住 ez 杠铃，手掌朝上，双手与肩同宽。","臀部向前弯曲，保持背部挺直，挺胸，直到躯干几乎与地板平行。","将 ez 杠铃拉向下胸部，将肩胛骨挤压在一起。","在顶部暂停片刻，然后慢慢将 ez 杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"1345","name":"kettlebell two arm row","nameZh":"壶铃双臂划船","equipment":"kettlebell","bodyPart":"back","target":"upper back","imagePath":"exercises/images/1345-wf24o8S.jpg","gifPath":"exercises/videos/1345-wf24o8S.gif","instructionSteps":["双脚分开与肩同宽站立，膝盖稍微弯曲，双手各握一个壶铃，手掌朝向身体。","臀部向前弯曲，保持背部挺直，核心肌群参与。","将壶铃拉向胸部，将肩胛骨挤压在一起。","在顶部暂停片刻，然后慢慢将壶铃放回起始位置。","重复所需的重复次数。"]},{"id":"1346","name":"kneeling lat stretch","nameZh":"跪姿背阔肌拉伸","equipment":"body weight","bodyPart":"back","target":"lats","imagePath":"exercises/images/1346-f38OEuO.jpg","gifPath":"exercises/videos/1346-f38OEuO.gif","instructionSteps":["跪在地上，膝盖分开与臀部同宽，脚趾向后。","将双臂伸过头顶，手指交叉。","保持背部挺直，慢慢向右侧倾斜，感受左侧背阔肌的拉伸。","保持伸展动作 20-30 秒，然后回到起始位置。","在左侧重复该拉伸动作，向左侧倾斜，感受右侧背阔肌的拉伸。","继续交替进行所需的重复次数。"]},{"id":"1347","name":"lever one arm lateral wide pulldown","nameZh":"杠杆机单臂侧向宽下拉","equipment":"leverage machine","bodyPart":"back","target":"lats","imagePath":"exercises/images/1347-tTuZSDT.jpg","gifPath":"exercises/videos/1347-tTuZSDT.gif","instructionSteps":["调整座椅高度，将自己放在机器上，胸部靠在垫子上，双脚平放在地板上。","正手握住手柄，完全伸展手臂，保持肘部轻微弯曲。","将手柄向下拉，穿过身体向对面的臀部方向拉，在动作底部挤压背阔肌。","慢慢地将手柄返回到起始位置，完全伸展手臂。","重复所需的重复次数，然后换边。"]},{"id":"1348","name":"lever reverse grip vertical row","nameZh":"杠杆机反握垂直划船","equipment":"leverage machine","bodyPart":"back","target":"upper back","imagePath":"exercises/images/1348-ZqNOWQ6.jpg","gifPath":"exercises/videos/1348-ZqNOWQ6.gif","instructionSteps":["调整座椅高度和踏板位置以确保正确对齐。","坐在机器上，胸部靠在垫子上，双脚平放在踏板上。","反手握住手柄，手掌朝上。","保持背部挺直并启动核心肌群。","将手柄拉向胸部，将肩胛骨挤压在一起。","在动作的最高点停顿片刻，然后慢慢松开并伸展手臂回到起始位置。","重复所需的重复次数。"]},{"id":"1349","name":"lever reverse t-bar row","nameZh":"杠杆机反向 T 杆划船","equipment":"leverage machine","bodyPart":"back","target":"upper back","imagePath":"exercises/images/1349-BgljGjd.jpg","gifPath":"exercises/videos/1349-BgljGjd.gif","instructionSteps":["调整杠杆机上的座椅高度和踏板位置。","坐在机器上，胸部靠在垫子上，双脚平放在踏板上。","正手握住手柄，握距略宽于肩宽。","保持背部挺直并启动核心肌群。","将手柄拉向胸部，将肩胛骨挤压在一起。","在动作的最高点停顿片刻，然后慢慢松开并伸展手臂回到起始位置。","重复所需的重复次数。"]},{"id":"1350","name":"lever seated row","nameZh":"杠杆机坐姿划船","equipment":"leverage machine","bodyPart":"back","target":"upper back","imagePath":"exercises/images/1350-7I6LNUG.jpg","gifPath":"exercises/videos/1350-7I6LNUG.gif","instructionSteps":["将座椅高度和脚踏板调整到舒适的位置。","坐在机器上，胸部靠在垫子上，双脚放在脚踏板上。","正手握住手柄，距离与肩同宽。","保持背部挺直，核心肌群参与。","将手柄拉向身体，将肩胛骨挤压在一起。","在动作的最高点停顿片刻。","慢慢松开手柄并返回到起始位置。","重复所需的重复次数。"]},{"id":"1351","name":"lever t-bar reverse grip row","nameZh":"杠杆机 T 杆反握划船","equipment":"leverage machine","bodyPart":"back","target":"upper back","imagePath":"exercises/images/1351-FVM1AUZ.jpg","gifPath":"exercises/videos/1351-FVM1AUZ.gif","instructionSteps":["调整座椅高度，将自己放在机器上，胸部靠在垫子上，双脚平放在地板上。","正手握住手柄，握距略宽于肩宽。","保持背部挺直并启动核心肌群。","将手柄拉向胸部，将肩胛骨挤压在一起。","在动作的最高点停顿片刻，然后慢慢松开并伸展手臂回到起始位置。","重复所需的重复次数。"]},{"id":"1352","name":"lower back curl","nameZh":"下背弯举","equipment":"body weight","bodyPart":"back","target":"spine","imagePath":"exercises/images/1352-ANbbry2.jpg","gifPath":"exercises/videos/1352-ANbbry2.gif","instructionSteps":["平躺，双腿伸直，双臂放在身体两侧。","收紧臀肌和腿筋，慢慢将上半身抬离地面，向上弯曲背部。","在顶部停顿片刻，然后慢慢将上半身放回起始位置。","重复所需的重复次数。"]},{"id":"1353","name":"medicine ball catch and overhead throw","nameZh":"药球接和过头抛","equipment":"medicine ball","bodyPart":"back","target":"lats","imagePath":"exercises/images/1353-PsVS1QP.jpg","gifPath":"exercises/videos/1353-PsVS1QP.gif","instructionSteps":["双脚分开与肩同宽站立，双手握住健身球，与胸部齐平。","稍微弯曲膝盖并启动核心。","将身体降低至蹲姿，保持背部挺直、挺胸。","爆发性伸展臀部和腿部，同时将药球扔过头顶。","在动作的最高点释放球并在下降的过程中接住它。","将身体放回蹲姿，然后重复所需的重复次数。"]},{"id":"1354","name":"medicine ball overhead slam","nameZh":"药球过头砸","equipment":"medicine ball","bodyPart":"back","target":"upper back","imagePath":"exercises/images/1354-oHg8eop.jpg","gifPath":"exercises/videos/1354-oHg8eop.gif","instructionSteps":["双脚分开与肩同宽站立，双手握住药球举过头顶。","启动你的核心并保持背部挺直。","稍微弯曲膝盖，用力将药球摔到你面前的地面上。","当你击球时，用你的整个身体来产生力量，包括你的肩膀和核心。","接住球的弹跳并重复所需的重复次数。"]},{"id":"1355","name":"one arm against wall","nameZh":"单臂靠墙","equipment":"body weight","bodyPart":"back","target":"lats","imagePath":"exercises/images/1355-ZZTGMKh.jpg","gifPath":"exercises/videos/1355-ZZTGMKh.gif","instructionSteps":["面向墙壁站立，双脚分开与肩同宽。","将一只手臂伸直到身前，将手掌靠在墙上。","启动你的核心，身体向前倾斜，保持手臂伸直，背部平坦。","用手掌慢慢推向墙壁，激活背阔肌。","保持该姿势几秒钟，然后松开并用另一只手臂重复该动作。"]},{"id":"1356","name":"lever one arm lateral high row","nameZh":"杠杆机单臂侧向高位划船","equipment":"leverage machine","bodyPart":"back","target":"upper back","imagePath":"exercises/images/1356-OIFMAp1.jpg","gifPath":"exercises/videos/1356-OIFMAp1.gif","instructionSteps":["调整座椅高度并将自己面向机器。","用一只手抓住手柄并保持背部挺直。","将手柄拉向身体，保持肘部靠近身体两侧。","在动作的最高点挤压背部肌肉。","慢慢松开手柄回到起始位置。","重复所需的重复次数。"]},{"id":"1358","name":"side lying floor stretch","nameZh":"侧卧地面拉伸","equipment":"body weight","bodyPart":"back","target":"lats","imagePath":"exercises/images/1358-jDOKRM5.jpg","gifPath":"exercises/videos/1358-jDOKRM5.gif","instructionSteps":["侧躺，双腿伸直，下臂伸直过头顶。","弯曲上面的膝盖，将脚放在下面的腿前面的地面上。","将上臂伸过头顶，抓住稳定的东西，例如墙壁或一件家具。","慢慢地将下面的腿抬离地面，保持伸直，直到感觉到身体一侧有拉伸感。","保持拉伸 20-30 秒，然后慢慢将腿放下。","在另一侧重复。"]},{"id":"1359","name":"smith bent over row","nameZh":"史密斯俯身划船","equipment":"smith machine","bodyPart":"back","target":"upper back","imagePath":"exercises/images/1359-ZX9UZmj.jpg","gifPath":"exercises/videos/1359-ZX9UZmj.gif","instructionSteps":["将史密斯机设置为与臀部高度相同的杠铃。","面向杠铃站立，双脚分开与肩同宽。","稍微弯曲膝盖，髋部向前转动，保持背部挺直。","正手握住杠铃，双手距离略宽于肩宽。","将杠铃拉向下胸部，将肩胛骨挤压在一起。","在顶部暂停片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"1360","name":"smith one arm row","nameZh":"史密斯单臂划船","equipment":"smith machine","bodyPart":"back","target":"upper back","imagePath":"exercises/images/1360-Q4DSJPC.jpg","gifPath":"exercises/videos/1360-Q4DSJPC.gif","instructionSteps":["将史密斯机杆的高度调整至腰部水平。","面对史密斯机站立，双脚与肩同宽。","稍微弯曲膝盖，髋部向前转动，保持背部挺直。","用一只手正手握住杠铃，手掌朝下。","保持肘部靠近身体，将杠铃拉向腰部，将肩胛骨挤压在一起。","在动作的最高点暂停片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数，然后换到另一只手臂。"]},{"id":"1361","name":"smith reverse grip bent over row","nameZh":"史密斯反握俯身划船","equipment":"smith machine","bodyPart":"back","target":"upper back","imagePath":"exercises/images/1361-aaxA3cm.jpg","gifPath":"exercises/videos/1361-aaxA3cm.gif","instructionSteps":["将史密斯机设置为与臀部高度相同的杠铃。","面向杠铃站立，双脚分开与肩同宽。","稍微弯曲膝盖，髋部向前转动，保持背部挺直。","反手握住杠铃，双手与肩同宽。","将杠铃拉向下胸部，将肩胛骨挤压在一起。","在顶部暂停片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"1362","name":"sphinx","nameZh":"狮身人面式","equipment":"body weight","bodyPart":"back","target":"spine","imagePath":"exercises/images/1362-DIVyqrU.jpg","gifPath":"exercises/videos/1362-DIVyqrU.gif","instructionSteps":["面朝下躺在地上，前臂平放在地板上，肘部直接位于肩膀下方。","收紧核心肌群，将胸部抬离地面，将前臂和脚趾保持在地板上。","保持这个姿势几秒钟，确保颈部保持在中立位置。","慢慢地将胸部放回起始位置。","重复所需的重复次数。"]},{"id":"1363","name":"spine stretch","nameZh":"脊柱拉伸","equipment":"body weight","bodyPart":"back","target":"spine","imagePath":"exercises/images/1363-JbC2iaV.jpg","gifPath":"exercises/videos/1363-JbC2iaV.gif","instructionSteps":["坐在地上，双腿在身前伸展。","将双手放在身后的地面上，手指指向身体。","启动你的核心并慢慢向后倾斜，保持背部挺直。","继续向后倾斜，直到感觉到脊柱被拉伸。","保持伸展几秒钟，然后慢慢回到起始位置。","重复所需的重复次数。"]},{"id":"1364","name":"standing pelvic tilt","nameZh":"站姿骨盆倾斜","equipment":"body weight","bodyPart":"back","target":"spine","imagePath":"exercises/images/1364-cuKYxhu.jpg","gifPath":"exercises/videos/1364-cuKYxhu.gif","instructionSteps":["双脚分开与肩同宽站立，膝盖稍微弯曲。","将双手放在臀部或垂在身体两侧。","调动核心肌肉并向前倾斜骨盆，将下背部推向身后的墙壁。","保持该位置几秒钟，然后松开并返回到起始位置。","重复所需的重复次数。"]},{"id":"1365","name":"upper back stretch","nameZh":"上背拉伸","equipment":"body weight","bodyPart":"back","target":"upper back","imagePath":"exercises/images/1365-GSDioYu.jpg","gifPath":"exercises/videos/1365-GSDioYu.gif","instructionSteps":["站直，双脚分开与肩同宽。","将双臂伸直在身前，与地面平行。","手指交叉，手掌旋转远离身体。","慢慢地将手臂举过头顶，保持它们伸直并彼此平行。","当你举起手臂时，将肩胛骨挤压在一起。","保持拉伸 15-30 秒，然后松开并重复。"]},{"id":"1366","name":"upward facing dog","nameZh":"上犬式","equipment":"body weight","bodyPart":"back","target":"spine","imagePath":"exercises/images/1366-01qpYSe.jpg","gifPath":"exercises/videos/1366-01qpYSe.gif","instructionSteps":["脸朝下躺在地板上，双腿伸到身后。","将双手放在下肋骨旁边的地板上，手指指向前方。","双手用力按在地板上，伸直手臂，将躯干和大腿抬离地面。","向后和向下转动肩膀，打开胸部，将目光转向天花板。","保持这个姿势几次呼吸，然后慢慢将身体放回起始位置。","重复所需的重复次数。"]},{"id":"1367","name":"wide grip rear pull-up","nameZh":"宽距后引体向上","equipment":"body weight","bodyPart":"back","target":"lats","imagePath":"exercises/images/1367-OYFhXVD.jpg","gifPath":"exercises/videos/1367-OYFhXVD.gif","instructionSteps":["正手宽握抓住引体向上杆，双手间距略宽于肩宽。","悬挂在杠上，双臂完全伸展，身体伸直。","调动背部肌肉，将身体拉向杠铃杆，以胸部为主导。","继续拉，直到下巴位于杠铃上方。","在顶部停顿片刻，然后慢慢将身体放回起始位置。","重复所需的重复次数。"]},{"id":"1368","name":"ankle circles","nameZh":"脚踝绕环","equipment":"body weight","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/1368-uL9CsKm.jpg","gifPath":"exercises/videos/1368-uL9CsKm.gif","instructionSteps":["坐在地上，双腿在身前伸展。","将一条腿抬离地面，并以圆周运动旋转脚踝。","在一个方向上转所需的圈数，然后切换到另一个方向。","换另一条腿重复上述步骤。"]},{"id":"1369","name":"band two legs calf raise - (band under both legs) v. 2","nameZh":"弹力带双腿提踵 - (弹力带下方双腿) 版本 2","equipment":"band","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/1369-jl6uxZV.jpg","gifPath":"exercises/videos/1369-jl6uxZV.gif","instructionSteps":["双脚分开与肩同宽站立，并将阻力带放在双脚下方。","用手握住带子的末端以保持稳定。","用小腿将脚跟抬离地面，尽可能高。","在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。","重复所需的重复次数。"]},{"id":"1370","name":"barbell floor calf raise","nameZh":"杠铃地面提踵","equipment":"barbell","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/1370-2IHEa2T.jpg","gifPath":"exercises/videos/1370-2IHEa2T.gif","instructionSteps":["将杠铃放在您面前的地板上。","站立，脚掌放在杠铃边缘，脚跟悬垂。","如果需要，请抓住一个稳定的物体以保持平衡。","尽可能高地抬高脚后跟，用小腿来抬起身体。","在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。","重复所需的重复次数。"]},{"id":"1371","name":"barbell seated calf raise","nameZh":"杠铃坐姿提踵","equipment":"barbell","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/1371-ipvgBnC.jpg","gifPath":"exercises/videos/1371-ipvgBnC.gif","instructionSteps":["坐在长凳上，双脚平放在地板上，杠铃放在大腿上。","将脚掌放在升高的平台上，例如木块或台阶。","尽可能降低脚后跟，感受小腿的拉伸。","尽可能高地抬高脚后跟，收缩小腿。","重复所需的重复次数。"]},{"id":"1372","name":"barbell standing calf raise","nameZh":"杠铃站姿提踵","equipment":"barbell","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/1372-8ozhUIZ.jpg","gifPath":"exercises/videos/1372-8ozhUIZ.gif","instructionSteps":["双脚分开与肩同宽站立，将杠铃放在上背部。","仅用脚趾将脚后跟抬离地面，尽可能高。","在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。","重复所需的重复次数。"]},{"id":"1373","name":"bodyweight standing calf raise","nameZh":"自重站姿提踵","equipment":"body weight","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/1373-bJYHBIN.jpg","gifPath":"exercises/videos/1373-bJYHBIN.gif","instructionSteps":["双脚分开与肩同宽站立，脚趾指向前方。","将手放在墙壁或稳定的表面上以保持平衡。","慢慢地将脚后跟抬离地面，将身体重量转移到脚掌上。","在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。","重复所需的重复次数。"]},{"id":"1374","name":"box jump down with one leg stabilization","nameZh":"跳箱向下带单腿稳定","equipment":"body weight","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/1374-iPm26QU.jpg","gifPath":"exercises/videos/1374-iPm26QU.gif","instructionSteps":["站在盒子或平台前，双脚分开与肩同宽。","弯曲膝盖，跳到盒子上，一只脚轻轻落地，另一只脚悬在盒子边缘。","将脚踩在盒子上，将自己稳定在盒子上，同时保持另一只脚离开地面。","保持这个姿势几秒钟，锻炼小腿肌肉以保持平衡。","将放在盒子上的脚慢慢放下，回到起始位置。","用另一条腿重复该练习。"]},{"id":"1375","name":"cable standing calf raise","nameZh":"绳索站姿提踵","equipment":"cable","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/1375-yl2IYyy.jpg","gifPath":"exercises/videos/1375-yl2IYyy.gif","instructionSteps":["面向缆绳机站立，双脚与肩同宽。","握住电缆机手柄或将电缆脚踝带固定在脚踝上。","尽可能高地伸展脚踝，将脚后跟抬离地面。","在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。","重复所需的重复次数。"]},{"id":"1376","name":"cable standing one leg calf raise","nameZh":"绳索站姿单腿提踵","equipment":"cable","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/1376-fgc9Xdl.jpg","gifPath":"exercises/videos/1376-fgc9Xdl.gif","instructionSteps":["面向缆绳机站立，双脚与肩同宽。","抓住电缆机以获得支撑。","将一条腿抬离地面并用另一条腿保持平衡。","慢慢地将脚跟抬离地面，将身体抬起到脚趾上。","在顶部暂停片刻，然后慢慢将脚跟放回起始位置。","重复所需的重复次数，然后换腿。"]},{"id":"1377","name":"calf stretch with hands against wall","nameZh":"小腿拉伸带手靠墙","equipment":"body weight","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/1377-m0tCHqc.jpg","gifPath":"exercises/videos/1377-m0tCHqc.gif","instructionSteps":["面向墙壁站立，双脚分开与臀部同宽。","将双手靠在墙上，与肩同高。","右脚向后退一步，保持脚后跟着地，腿伸直。","弯曲左膝并向前倾斜，保持后腿伸直，脚后跟着地。","保持拉伸 20-30 秒。","换腿并重复拉伸。"]},{"id":"1378","name":"calf stretch with rope","nameZh":"小腿拉伸带绳索","equipment":"rope","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/1378-1LVFcEn.jpg","gifPath":"exercises/videos/1378-1LVFcEn.gif","instructionSteps":["面向墙壁或坚固物体站立，双脚分开与臀部同宽。","双手握住绳子的两端，将绳子的中间放在右脚掌周围。","左脚向后退一步，脚跟保持在地面上，腿伸直。","身体前倾，保持背部挺直，轻轻拉动绳子以伸展小腿。","保持拉伸 20-30 秒，然后放松。","在另一条腿上重复。"]},{"id":"1379","name":"dumbbell seated calf raise","nameZh":"哑铃坐姿提踵","equipment":"dumbbell","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/1379-r29jP7S.jpg","gifPath":"exercises/videos/1379-r29jP7S.gif","instructionSteps":["坐在长凳或椅子上，双脚平放在地面上，并将哑铃放在大腿上。","将脚掌放在升高的表面（例如台阶或木块）上，脚跟悬在边缘外。","握住哑铃以保持稳定。","尽可能高地抬高脚后跟，将身体重量转移到脚掌上。","在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。","重复所需的重复次数。"]},{"id":"1380","name":"dumbbell seated one leg calf raise - hammer grip","nameZh":"哑铃坐姿单腿提踵 - 大锤握","equipment":"dumbbell","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/1380-FxhcxUW.jpg","gifPath":"exercises/videos/1380-FxhcxUW.gif","instructionSteps":["坐在长凳或椅子上，双脚平放在地面上，并将哑铃放在大腿上。","将一只脚放在凸起的表面上，例如台阶或木块，脚跟悬在边缘之外。","用锤式握法握住哑铃，这意味着您的手掌相对，手指缠绕在手柄上。","保持核心收紧，背部挺直，通过脚掌推动，将脚后跟慢慢抬高，尽可能高。","在顶部暂停片刻，然后慢慢将脚跟放回起始位置。","重复所需的重复次数，然后换另一条腿。"]},{"id":"1381","name":"dumbbell seated one leg calf raise - palm up","nameZh":"哑铃坐姿单腿提踵 - 手掌向上","equipment":"dumbbell","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/1381-VW88JNd.jpg","gifPath":"exercises/videos/1381-VW88JNd.gif","instructionSteps":["坐在长凳或椅子上，背部挺直，双脚平放在地面上。","一只手握住哑铃，将其放在大腿上方，掌心朝上。","将一条腿抬离地面并将其延伸到您面前，保持膝盖稍微弯曲。","通过脚掌推动，尽可能高地抬起脚后跟。","在顶部停顿片刻，然后慢慢降低脚跟。","重复所需的重复次数，然后换腿并重复。"]},{"id":"1382","name":"exercise ball on the wall calf raise","nameZh":"健身球在墙提踵","equipment":"dumbbell","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/1382-xo6sENf.jpg","gifPath":"exercises/videos/1382-xo6sENf.gif","instructionSteps":["背靠墙站立，将健身球放在下背部和墙壁之间。","双脚分开与肩同宽，脚趾指向前方。","每只手握住一个哑铃，双臂伸向身体两侧。","将脚跟抬离地面，将身体重量转移到脚掌上。","在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。","重复所需的重复次数。"]},{"id":"1383","name":"hack calf raise","nameZh":"哈克提踵","equipment":"sled machine","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/1383-2ORFMoR.jpg","gifPath":"exercises/videos/1383-2ORFMoR.gif","instructionSteps":["将雪橇机调整至舒适的重量。","站在雪橇机上，脚趾放在平台上，脚后跟悬空。","握住手柄以保持稳定性。","通过推动脚掌将脚后跟尽可能抬高。","在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。","重复所需的重复次数。"]},{"id":"1384","name":"hack one leg calf raise","nameZh":"哈克单腿提踵","equipment":"sled machine","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/1384-AxFoqAD.jpg","gifPath":"exercises/videos/1384-AxFoqAD.gif","instructionSteps":["将雪橇机调整到合适的重量。","一脚站在雪橇机上，另一只脚离开地面。","握住手柄以保持稳定性。","尽可能高地抬高脚跟，用脚掌抬起身体。","在顶部暂停片刻，然后慢慢将脚跟放回起始位置。","重复所需的重复次数。","换腿并重复练习。"]},{"id":"1385","name":"lever seated squat calf raise on leg press machine","nameZh":"杠杆机坐姿深蹲提踵在腿举器械","equipment":"leverage machine","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/1385-IeDEXTe.jpg","gifPath":"exercises/videos/1385-IeDEXTe.gif","instructionSteps":["调整压腿机的座椅，使双脚放在踏板上时膝盖稍微弯曲。","坐在机器上，背部靠在靠背上，双脚平放在踏板上，与肩同宽。","将脚趾和脚掌放在踏板上，使脚后跟远离边缘。","松开安全手柄，并通过伸展膝盖将踏板推离您。","一旦膝盖完全伸展，弯曲小腿，慢慢降低脚后跟。","在底部停顿片刻，然后通过伸展小腿将踏板向后推。","重复所需的重复次数。"]},{"id":"1386","name":"one leg donkey calf raise","nameZh":"单腿驴式提踵","equipment":"body weight","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/1386-A2upspL.jpg","gifPath":"exercises/videos/1386-A2upspL.gif","instructionSteps":["双脚分开与肩同宽站立，脚趾指向前方。","将双手放在稳定的表面上以获得支撑，例如墙壁或酒吧。","将一条腿抬离地面，保持膝盖稍微弯曲。","使用小腿肌肉，尽可能高地抬高脚跟。","在顶部停顿片刻，然后慢慢降低脚跟。","重复所需的重复次数，然后换腿。"]},{"id":"1387","name":"one leg floor calf raise","nameZh":"单腿地面提踵","equipment":"body weight","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/1387-0jp9Rlz.jpg","gifPath":"exercises/videos/1387-0jp9Rlz.gif","instructionSteps":["双脚分开与臀部同宽站立，双手放在墙壁或坚固的物体上以保持平衡。","将一只脚抬离地面并用另一只脚保持平衡。","慢慢地将脚跟抬离地面，将身体抬起到脚掌上。","在顶部暂停片刻，然后慢慢将脚跟放回起始位置。","重复所需的重复次数，然后换腿并重复。"]},{"id":"1388","name":"peroneals stretch","nameZh":"腓骨肌拉伸","equipment":"rope","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/1388-XhfS1DZ.jpg","gifPath":"exercises/videos/1388-XhfS1DZ.gif","instructionSteps":["坐在地上，双腿在身前伸展。","将绳子绕在脚掌上，并用手握住绳子的末端。","轻轻地将绳子拉向自己，弯曲脚并伸展小腿肌肉。","保持拉伸 15-30 秒。","释放绳子上的张力，然后在另一条腿上重复拉伸。","重复所需的重复次数。"]},{"id":"1389","name":"posterior tibialis stretch","nameZh":"后侧胫骨前肌拉伸","equipment":"rope","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/1389-DEEqoI2.jpg","gifPath":"exercises/videos/1389-DEEqoI2.gif","instructionSteps":["坐在地上，双腿在身前伸展。","将绳子绕在脚掌上，并用手握住绳子的末端。","轻轻地将绳子拉向自己，弯曲脚并伸展小腿肌肉。","保持拉伸 20-30 秒。","释放绳子上的张力并放松脚。","在另一条腿上重复该拉伸动作。"]},{"id":"1390","name":"seated calf stretch (male)","nameZh":"坐姿小腿拉伸 （男）","equipment":"body weight","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/1390-17bqEXD.jpg","gifPath":"exercises/videos/1390-17bqEXD.gif","instructionSteps":["坐在椅子或长凳的边缘，双脚平放在地面上。","将一只腿伸直在身前，脚跟保持在地面上。","稍微向前倾，感受小腿肌肉的拉伸。","保持拉伸 20-30 秒。","换腿并重复拉伸。"]},{"id":"1391","name":"sled calf press on leg press","nameZh":"雪橇机小腿推举在腿举","equipment":"sled machine","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/1391-ykHcWme.jpg","gifPath":"exercises/videos/1391-ykHcWme.gif","instructionSteps":["调整压腿机的座椅，使双脚踩在雪橇上时膝盖稍微弯曲。","将双脚与肩同宽放在雪橇上，脚趾指向前方。","松开安全手柄，并通过伸展膝盖和脚踝将雪橇推离您。","在动作的最高点暂停片刻，然后弯曲膝盖和脚踝，慢慢将雪橇放回原处。","重复所需的重复次数。"]},{"id":"1392","name":"sled one leg calf press on leg press","nameZh":"雪橇机单腿小腿推举在腿举","equipment":"sled machine","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/1392-u0pLNgz.jpg","gifPath":"exercises/videos/1392-u0pLNgz.gif","instructionSteps":["调整压腿机的座椅，使双脚踩在雪橇上时膝盖稍微弯曲。","坐在机器上，背部靠在靠背上，双脚放在雪橇上，与肩同宽。","将脚趾和脚掌放在雪橇上，保持脚跟离开。","伸展脚踝，保持膝盖稍微弯曲，将雪橇向前推。","在顶部停顿片刻，然后通过弯曲脚踝慢慢将雪橇放回原处。","重复所需的重复次数。"]},{"id":"1393","name":"smith one leg floor calf raise","nameZh":"史密斯单腿地面提踵","equipment":"smith machine","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/1393-9GXrTE6.jpg","gifPath":"exercises/videos/1393-9GXrTE6.gif","instructionSteps":["将自己放在史密斯机杆下方的地板上，背对机器。","将脚掌放在凸起的表面上，例如举重板或杠铃块。","将史密斯机杆放在小腿上，就在脚踝上方。","用手握住横杆以保持稳定。","伸展脚踝，将脚后跟抬离地面，抬起身体。","在动作的最高点暂停，然后慢慢降低脚跟回到起始位置。","重复所需的重复次数。"]},{"id":"1394","name":"smith reverse calf raises","nameZh":"史密斯反向提踵s","equipment":"smith machine","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/1394-Lsqrgh4.jpg","gifPath":"exercises/videos/1394-Lsqrgh4.gif","instructionSteps":["将史密斯机杆调整到略低于肩膀的高度。","面向杠铃站立，双脚分开与臀部同宽，脚趾向前。","将脚掌放在台阶或平台的边缘，脚后跟悬空。","抓住横杆以获得支撑。","尽可能高地抬高脚跟，将身体抬起到脚趾上。","在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。","重复所需的重复次数。"]},{"id":"1395","name":"smith seated one leg calf raise","nameZh":"史密斯坐姿单腿提踵","equipment":"smith machine","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/1395-0S75mYG.jpg","gifPath":"exercises/videos/1395-0S75mYG.gif","instructionSteps":["坐在机器上，背部靠在垫子上，双脚放在脚踏板上。","将一条腿放在脚踏板上，另一条腿离开脚踏板。","使用小腿肌肉，尽可能高地抬高脚跟。","在顶部暂停片刻，然后慢慢将脚跟放回起始位置。","重复所需的重复次数，然后换腿并重复。"]},{"id":"1396","name":"smith toe raise","nameZh":"史密斯抬脚尖","equipment":"smith machine","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/1396-Y4QlY8z.jpg","gifPath":"exercises/videos/1396-Y4QlY8z.gif","instructionSteps":["将史密斯机杆调整到一个高度，让您可以舒适地站立，双脚平放在地面上。","将自己置于杠铃下方，肩膀位于杠铃正下方，双脚分开与肩同宽。","将脚掌放在升高的平台或重量板上，脚后跟悬在边缘。","正手握住杠铃，握距略宽于肩宽。","在整个练习过程中启动你的核心并保持背部挺直。","慢慢地尽可能高地抬起脚后跟，将身体重量转移到脚掌上。","在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。","重复所需的重复次数。"]},{"id":"1397","name":"standing calves","nameZh":"站姿小腿","equipment":"body weight","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/1397-XIHEoCG.jpg","gifPath":"exercises/videos/1397-XIHEoCG.gif","instructionSteps":["双脚分开与肩同宽站立，脚趾指向前方。","将脚后跟抬离地面，尽可能高，用脚趾站立。","保持该姿势片刻，然后慢慢降低脚跟回到起始位置。","重复所需的重复次数。"]},{"id":"1398","name":"standing calves calf stretch","nameZh":"站姿小腿小腿拉伸","equipment":"body weight","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/1398-qOKcgVP.jpg","gifPath":"exercises/videos/1398-qOKcgVP.gif","instructionSteps":["面朝墙壁或坚固物体站立，距离大约一臂远。","将手放在与肩同高的墙壁或物体上。","一只脚向后退一步，保持脚跟平放在地面上。","稍微弯曲前膝盖并向前倾斜，保持后腿伸直。","您应该感觉到小腿肌肉有拉伸感。","保持拉伸 20-30 秒。","在另一条腿上重复。"]},{"id":"1399","name":"bench dip on floor","nameZh":"凳上臂屈伸在地面","equipment":"body weight","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/1399-9RT8oQW.jpg","gifPath":"exercises/videos/1399-9RT8oQW.gif","instructionSteps":["坐在长凳或椅子的边缘，双手抓住边缘，手指指向前方。","将臀部滑离长凳，用手支撑体重。","弯曲肘部降低身体，直到上臂与地板平行。","伸直手臂，将自己推回起始位置。","重复所需的重复次数。"]},{"id":"1401","name":"muscle-up (on vertical bar)","nameZh":"双力臂 (在竖杆)","equipment":"body weight","bodyPart":"back","target":"lats","imagePath":"exercises/images/1401-Af0EW2I.jpg","gifPath":"exercises/videos/1401-Af0EW2I.gif","instructionSteps":["首先悬挂在垂直杆上，手掌背对自己，手臂完全伸展。","启动核心肌群，将身体拉向杠铃杆，以胸部为主导。","当你站起来时，稍微向后倾斜，并将肘部移向身体两侧。","继续拉，直到胸部到达杠铃并且肘部完全弯曲。","在最高点暂停片刻，然后慢慢降低回到起始位置。","重复所需的重复次数。"]},{"id":"1403","name":"neck side stretch","nameZh":"颈部侧拉伸","equipment":"body weight","bodyPart":"neck","target":"levator scapulae","imagePath":"exercises/images/1403-x2chWLO.jpg","gifPath":"exercises/videos/1403-x2chWLO.gif","instructionSteps":["站直或坐直，肩膀放松。","将头向一侧倾斜，将耳朵靠近肩膀。","保持拉伸 15-30 秒。","在另一侧重复。","每侧进行 2-4 组。"]},{"id":"1405","name":"back pec stretch","nameZh":"背阔肌拉伸","equipment":"body weight","bodyPart":"back","target":"lats","imagePath":"exercises/images/1405-chfnQnM.jpg","gifPath":"exercises/videos/1405-chfnQnM.gif","instructionSteps":["站直，双脚分开与肩同宽。","将双臂伸直在身前，与地面平行。","双臂交叉在身体前方，右臂放在左臂上方。","手指交叉，手掌旋转远离身体。","慢慢抬起手臂并远离身体，感觉背部和胸部有拉伸感。","保持拉伸 15-30 秒，然后放松。","在另一侧重复。"]},{"id":"1407","name":"calf push stretch with hands against wall","nameZh":"小腿推拉伸带手靠墙","equipment":"body weight","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/1407-PzNxakt.jpg","gifPath":"exercises/videos/1407-PzNxakt.gif","instructionSteps":["面向墙壁站立，双脚分开与臀部同宽。","将双手靠在墙上，与肩同高。","一只脚向后退一步，脚跟保持在地面上，腿伸直。","稍微弯曲前膝盖并向前倾斜，感觉小腿有拉伸感。","保持拉伸 20-30 秒。","换腿并重复拉伸。"]},{"id":"1408","name":"band hip lift","nameZh":"弹力带髋上提","equipment":"band","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/1408-E4R8Hz1.jpg","gifPath":"exercises/videos/1408-E4R8Hz1.gif","instructionSteps":["仰卧，膝盖弯曲，双脚平放在地上。","将阻力带放在膝盖上方。","调动你的臀肌和核心肌肉。","将脚后跟压入地面，将臀部抬离地板，在顶部挤压臀部。","在顶部暂停片刻，然后慢慢将臀部放回起始位置。","重复所需的重复次数。"]},{"id":"1409","name":"barbell glute bridge","nameZh":"杠铃臀桥","equipment":"barbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/1409-qKBpF7I.jpg","gifPath":"exercises/videos/1409-qKBpF7I.gif","instructionSteps":["首先平躺在地上，膝盖弯曲，双脚平放在地板上。","将杠铃放在臀部上，用双手牢牢握住它。","锻炼臀部和核心肌肉，然后将臀部抬离地面，直到身体从膝盖到肩膀形成一条直线。","在顶部暂停片刻，挤压臀部。","慢慢地将臀部放回起始位置。","重复所需的重复次数。"]},{"id":"1410","name":"barbell lateral lunge","nameZh":"杠铃侧弓步","equipment":"barbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/1410-py1HSzx.jpg","gifPath":"exercises/videos/1410-py1HSzx.gif","instructionSteps":["双脚分开与肩同宽站立，将杠铃放在上背部。","右脚向一侧迈出一大步，保持左脚踩地。","弯曲右膝，将身体降低到弓步位置，保持左腿伸直。","用右脚推出并返回到起始位置。","在另一侧重复，用左脚迈步。"]},{"id":"1411","name":"barbell palms down wrist curl over a bench","nameZh":"杠铃手掌向下手腕弯举过a 凳","equipment":"barbell","bodyPart":"lower arms","target":"forearms","imagePath":"exercises/images/1411-yzYH9pI.jpg","gifPath":"exercises/videos/1411-yzYH9pI.gif","instructionSteps":["坐在长凳上，双脚平放在地上，前臂放在大腿上，手掌朝下。","正手握住杠铃，双手与肩同宽。","弯曲手腕，将杠铃降低到地面，保持前臂静止。","在底部停顿片刻，然后通过伸展手腕慢慢将杠铃举起。","重复所需的重复次数。"]},{"id":"1412","name":"barbell palms up wrist curl over a bench","nameZh":"杠铃手掌向上手腕弯举过a 凳","equipment":"barbell","bodyPart":"lower arms","target":"forearms","imagePath":"exercises/images/1412-SJAA2IQ.jpg","gifPath":"exercises/videos/1412-SJAA2IQ.gif","instructionSteps":["坐在长凳上，双脚平放在地面上，反手握住杠铃，手掌朝上。","将前臂放在长凳上，让手腕悬在长凳边缘。","保持前臂静止，呼气并尽可能向上弯曲手腕。","保持收缩位置短暂停顿，然后吸气并慢慢将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"1413","name":"cable reverse one arm curl","nameZh":"绳索反向单臂弯举","equipment":"cable","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/1413-gVlnLIJ.jpg","gifPath":"exercises/videos/1413-gVlnLIJ.gif","instructionSteps":["面向缆绳机站立，双脚与肩同宽。","反手握住电缆手柄，手掌朝下。","保持肘部靠近身体两侧，慢慢地将前臂向上卷向肩膀。","在顶部暂停片刻，然后慢慢将前臂放回起始位置。","重复所需的重复次数。"]},{"id":"1414","name":"dumbbell one arm reverse preacher curl","nameZh":"哑铃单臂反向牧师凳弯举","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/1414-bWxq4op.jpg","gifPath":"exercises/videos/1414-bWxq4op.gif","instructionSteps":["坐在牧师凳上，胸部靠在垫子上，手臂伸出长凳边缘，反握哑铃。","慢慢降低哑铃，直到手臂完全伸展。","将哑铃向后弯向肩膀，保持上臂静止。","在动作的最高点挤压二头肌，然后慢慢将哑铃放回起始位置。","重复所需的重复次数，然后换臂。"]},{"id":"1415","name":"dumbbell one arm seated neutral wrist curl","nameZh":"哑铃单臂坐姿中立手腕弯举","equipment":"dumbbell","bodyPart":"lower arms","target":"forearms","imagePath":"exercises/images/1415-YtaCTYl.jpg","gifPath":"exercises/videos/1415-YtaCTYl.gif","instructionSteps":["坐在长凳上，双脚平放在地上，一手握住哑铃，掌心朝上。","将前臂放在大腿上，让手腕悬在边缘。","保持前臂静止，尽可能向上弯曲手腕。","在顶部暂停片刻，然后慢慢将手腕放回起始位置。","重复所需的重复次数，然后换另一只手。"]},{"id":"1416","name":"exercise ball one leg prone lower body rotation","nameZh":"健身球单腿俯卧下半身旋转","equipment":"stability ball","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/1416-M72BExt.jpg","gifPath":"exercises/videos/1416-M72BExt.gif","instructionSteps":["面朝下躺在稳定球上，臀部放在球上，双腿伸直在身后。","将双手放在身前的地面上以获得支撑。","调动你的臀肌和核心肌肉来稳定你的身体。","慢慢地将一条腿抬离地面，保持笔直并与地板平行。","向外旋转腿部，远离身体，同时保持臀部和上半身稳定。","旋转结束时暂停片刻，然后慢慢地将腿放回起始位置。","用另一条腿重复旋转。","继续交替双腿达到所需的重复次数。"]},{"id":"1417","name":"exercise ball one legged diagonal kick hamstring curl","nameZh":"健身球单腿对角踢腘绳肌弯举","equipment":"stability ball","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/1417-GOJKFfO.jpg","gifPath":"exercises/videos/1417-GOJKFfO.gif","instructionSteps":["首先仰卧，双腿伸展，脚跟放在稳定球上。","将手臂放在身体两侧以保持稳定。","调动臀肌和核心肌肉，将臀部抬离地面，从肩膀到脚后跟形成一条直线。","弯曲右膝并将其靠近胸部，保持左腿伸展，脚部弯曲。","将右腿斜踢过身体，完全伸展并拉动腿筋。","慢慢地将右腿返回到起始位置，保持控制和稳定性。","用左腿重复该动作，交替进行所需的重复次数。"]},{"id":"1418","name":"hug keens to chest","nameZh":"抱膝贴胸","equipment":"body weight","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/1418-znP9SIh.jpg","gifPath":"exercises/videos/1418-znP9SIh.gif","instructionSteps":["首先站立，双脚分开与肩同宽。","弯曲膝盖并将身体降低至蹲姿。","当你蹲下时，将膝盖抬向胸部，并用手臂抱住它们。","保持这个姿势一会儿，然后慢慢回到起始位置。","重复所需的重复次数。"]},{"id":"1419","name":"iron cross stretch","nameZh":"十字支撑拉伸","equipment":"body weight","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/1419-pZwUsKB.jpg","gifPath":"exercises/videos/1419-pZwUsKB.gif","instructionSteps":["平躺，双臂向两侧伸展。","将双腿抬向天花板，保持伸直。","慢慢地将双腿降低到一侧，旨在用脚接触地板。","保持伸展几秒钟，然后将双腿恢复到起始位置。","在另一侧重复拉伸。","继续交替进行所需的重复次数。"]},{"id":"1420","name":"kneeling jump squat","nameZh":"跪姿跳跃深蹲","equipment":"barbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/1420-UgDm3oy.jpg","gifPath":"exercises/videos/1420-UgDm3oy.gif","instructionSteps":["首先跪在地上，双脚分开与臀部同宽，脚趾向前。","将杠铃放在上背部，将其放在肩膀上。","启动你的核心和臀部，然后爆发性地跳到空中，伸展你的臀部和膝盖。","跳跃时，用脚趾推动并充分伸展脚踝、膝盖和臀部。","轻轻地回到地面，弯曲膝盖以吸收冲击力。","立即进入下一个重复，重复跳蹲动作。"]},{"id":"1421","name":"modified push up to lower arms","nameZh":"改良俯卧撑至下手臂","equipment":"body weight","bodyPart":"lower arms","target":"forearms","imagePath":"exercises/images/1421-arvaszz.jpg","gifPath":"exercises/videos/1421-arvaszz.gif","instructionSteps":["从俯卧撑位置开始，双手直接放在肩膀下方，身体呈一条直线。","弯曲肘部，使肘部靠近身体两侧，将身体降低到地面。","一旦肘部成 90 度角，将前臂放低至地面，将肘部保持在肩膀正下方。","暂停片刻，然后用手掌推动前臂，使其回到起始位置。","重复所需的重复次数。"]},{"id":"1422","name":"pelvic tilt into bridge","nameZh":"骨盆倾斜进入桥式","equipment":"body weight","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/1422-D9qe7CM.jpg","gifPath":"exercises/videos/1422-D9qe7CM.gif","instructionSteps":["仰卧，膝盖弯曲，双脚平放在地上。","将手臂放在身体两侧，手掌朝下。","调动你的臀肌和核心肌肉。","向上倾斜骨盆，将臀部抬离地面。","保持桥位置几秒钟。","慢慢地将臀部放回起始位置。","重复所需的重复次数。"]},{"id":"1423","name":"reverse hyper on flat bench","nameZh":"反向过度伸展在平板凳","equipment":"body weight","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/1423-OrETs32.jpg","gifPath":"exercises/videos/1423-OrETs32.gif","instructionSteps":["脸朝下躺在平坦的长凳上，臀部位于边缘，双腿悬在长凳上。","抓住长凳以保持稳定。","保持双腿伸直，尽可能将它们抬向天花板。","在动作的最高点挤压臀部。","慢慢地将双腿放回起始位置。","重复所需的重复次数。"]},{"id":"1424","name":"seated glute stretch","nameZh":"坐姿臀肌拉伸","equipment":"body weight","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/1424-DeDThfG.jpg","gifPath":"exercises/videos/1424-DeDThfG.gif","instructionSteps":["坐在地上，双腿在身前伸展。","弯曲右膝，将右脚踝交叉在左大腿上。","将右手放在身后的地面上以获得支撑。","用左手轻轻按下右膝盖以加深伸展。","保持拉伸 30 秒到 1 分钟。","换边并重复。"]},{"id":"1425","name":"sled 45 degrees one leg press","nameZh":"雪橇机 45 度一腿举","equipment":"sled machine","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/1425-WWD6FzI.jpg","gifPath":"exercises/videos/1425-WWD6FzI.gif","instructionSteps":["将雪橇机调整至 45 度角。","坐在雪橇机上，背部靠在垫子上，双脚放在踏板上。","将一只脚放在踏板上并伸展腿，将雪橇推离您。","慢慢弯曲膝盖，将雪橇放回起始位置。","换另一条腿重复上述步骤。","继续交替双腿达到所需的重复次数。"]},{"id":"1426","name":"smith seated wrist curl","nameZh":"史密斯坐姿手腕弯举","equipment":"smith machine","bodyPart":"lower arms","target":"forearms","imagePath":"exercises/images/1426-B6dAO1t.jpg","gifPath":"exercises/videos/1426-B6dAO1t.gif","instructionSteps":["坐在史密斯机前的长凳上，双脚平放在地面上。","反握抓住杠铃，双手与肩同宽。","将前臂放在大腿上，让手腕悬垂。","慢慢向上弯曲手腕，将杠铃拉向前臂。","在顶部停顿片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"1427","name":"straight leg outer hip abductor","nameZh":"直腿外侧髋外展肌","equipment":"body weight","bodyPart":"upper legs","target":"abductors","imagePath":"exercises/images/1427-mQ1tBXn.jpg","gifPath":"exercises/videos/1427-mQ1tBXn.gif","instructionSteps":["侧躺，双腿伸直并叠放在一起。","将下臂放在头下方以获得支撑。","启动你的核心并尽可能高地抬起你的上腿，不要旋转你的臀部或向后倾斜。","在顶部暂停片刻，然后慢慢将腿放回起始位置。","重复所需的重复次数，然后换边。"]},{"id":"1428","name":"wrist circles","nameZh":"手腕绕环","equipment":"body weight","bodyPart":"lower arms","target":"forearms","imagePath":"exercises/images/1428-2zNKRUB.jpg","gifPath":"exercises/videos/1428-2zNKRUB.gif","instructionSteps":["将双臂伸直在身前。","双手握拳。","以圆周运动旋转手腕，保持手臂静止。","继续手腕转圈达到所需的重复次数。"]},{"id":"1429","name":"wide grip pull-up","nameZh":"宽距引体向上","equipment":"body weight","bodyPart":"back","target":"lats","imagePath":"exercises/images/1429-Qqi7bko.jpg","gifPath":"exercises/videos/1429-Qqi7bko.gif","instructionSteps":["悬挂在引体向上杆上，手掌背向自己，双手之间的距离比肩宽。","启动你的核心并将肩胛骨挤压在一起。","将身体向上拉向杠铃，直到下巴位于杠铃上方。","有控制地降低身体回到起始位置。","重复所需的重复次数。"]},{"id":"1430","name":"chest dip (on dip-pull-up cage)","nameZh":"胸部臂屈伸 (在臂屈伸-引体向上架)","equipment":"body weight","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/1430-XgWyAiA.jpg","gifPath":"exercises/videos/1430-XgWyAiA.gif","instructionSteps":["将倾斜杆调整到您可以舒适地握住它们的高度。","站在杠铃之间，将双手放在每个杠铃上，距离略宽于肩宽。","跳起来并伸直双臂，将体重支撑在杠上。","弯曲膝盖并将脚踝交叉在身后。","弯曲肘部降低身体，保持胸部向上，肩膀向下。","继续降低，直到肩膀低于肘部或直到您感到胸部有拉伸感。","推动手掌并伸展肘部，将身体抬回到起始位置。","重复所需的重复次数。"]},{"id":"1431","name":"assisted standing chin-up","nameZh":"辅助站姿反握引体向上","equipment":"leverage machine","bodyPart":"back","target":"lats","imagePath":"exercises/images/1431-7OeHptV.jpg","gifPath":"exercises/videos/1431-7OeHptV.gif","instructionSteps":["将机器调整至您所需的辅助级别。","站在脚踏板上，正手握住手柄，握距略宽于肩宽。","保持挺胸、肩膀向后，收紧核心肌群，并稍微弯曲膝盖。","弯曲肘部并将肘部向身体两侧压低，将身体向上拉。","继续拉，直到下巴位于杠铃上方。","在顶部停顿片刻，然后慢慢将身体放回起始位置。","重复所需的重复次数。"]},{"id":"1432","name":"assisted standing pull-up","nameZh":"辅助站姿引体向上","equipment":"leverage machine","bodyPart":"back","target":"lats","imagePath":"exercises/images/1432-f4xtKBj.jpg","gifPath":"exercises/videos/1432-f4xtKBj.gif","instructionSteps":["将机器调整至您所需的体重和高度设置。","面向机器站立，双脚分开与肩同宽。","正手握住手柄，握距略宽于肩宽。","启动你的背阔肌和二头肌，并将自己拉向手柄。","在顶部暂停片刻，挤压背部肌肉。","慢慢地将自己放回到起始位置。","重复所需的重复次数。"]},{"id":"1433","name":"smith front squat (clean grip)","nameZh":"史密斯前蹲 (翻举握距)","equipment":"smith machine","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/1433-lFhb2Rw.jpg","gifPath":"exercises/videos/1433-lFhb2Rw.gif","instructionSteps":["将杠铃置于肩高的史密斯机上。","面向杠铃站立，双脚与肩同宽。","正手握住杠铃，握距略宽于肩宽。","后退一步，将杠铃放在前肩上，放在锁骨和三角肌上。","保持挺胸、背部挺直、核心收紧。","弯曲膝盖和臀部，降低身体，就像坐回椅子上一样。","继续降低，直到大腿与地面平行或略低于地面。","暂停片刻，然后用力推动脚后跟，回到起始位置。","重复所需的重复次数。"]},{"id":"1434","name":"smith low bar squat","nameZh":"史密斯低杠深蹲","equipment":"smith machine","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/1434-RGLscZM.jpg","gifPath":"exercises/videos/1434-RGLscZM.gif","instructionSteps":["将史密斯机与杠铃设置在一个高度，以便您可以将其舒适地放在上背部。","站立，双脚分开与肩同宽，脚趾稍微向外转动。","走到杠铃下方，将其放在上背部上方，将其放在斜方肌上。","双手握住杠铃，距离略大于肩宽。","伸直双腿并从架子上退后，将杠铃松开。","深呼吸并支撑你的核心。","通过向后推臀部并弯曲膝盖来开始深蹲。","降低身体，直到大腿与地面平行或稍低于地面。","在整个动作过程中保持挺胸、背部挺直。","通过脚后跟站起来，伸展臀部和膝盖。","重复所需的重复次数。"]},{"id":"1435","name":"barbell low bar squat","nameZh":"杠铃低杠深蹲","equipment":"barbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/1435-bTpEUcm.jpg","gifPath":"exercises/videos/1435-bTpEUcm.gif","instructionSteps":["双脚分开与肩同宽站立，杠铃放在上背部。","保持挺胸，核心收紧，弯曲膝盖并向后推臀部，慢慢降低身体。","继续降低，直到大腿与地面平行或略低于地面。","暂停片刻，然后用力推动脚后跟，回到起始位置。","重复所需的重复次数。"]},{"id":"1436","name":"barbell high bar squat","nameZh":"杠铃高位杆深蹲","equipment":"barbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/1436-Gnfo4FM.jpg","gifPath":"exercises/videos/1436-Gnfo4FM.gif","instructionSteps":["站立，双脚分开与肩同宽，脚趾稍微向外。","将杠铃放在上背部，放在斜方肌上。","当你开始蹲下时，启动你的核心并保持胸部挺直，将臀部向后推并弯曲膝盖。","放低身体，直到大腿与地面平行，或者尽可能低到您能舒服的高度。","通过脚后跟站起来，伸展臀部和膝盖。","重复所需的重复次数。"]},{"id":"1437","name":"dumbbell finger curls","nameZh":"哑铃手指弯举","equipment":"dumbbell","bodyPart":"lower arms","target":"forearms","imagePath":"exercises/images/1437-mtXengz.jpg","gifPath":"exercises/videos/1437-mtXengz.gif","instructionSteps":["坐在长凳或椅子上，双脚平放在地上，背部挺直。","一只手握住哑铃，反手握住，将前臂放在大腿上，手掌朝上。","让哑铃向下滚动到指尖，然后弯曲手指将其卷起。","重复所需的重复次数，然后换另一只手。"]},{"id":"1438","name":"kettlebell seated two arm military press","nameZh":"壶铃坐姿双臂军事推举","equipment":"kettlebell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/1438-ZEkjZDi.jpg","gifPath":"exercises/videos/1438-ZEkjZDi.gif","instructionSteps":["坐在长凳上，背部挺直，双脚平放在地上。","每只手握住一个壶铃，与肩同高，手掌朝前。","完全伸展双臂，将壶铃压过头顶。","在顶部暂停片刻，然后慢慢将壶铃放回肩部水平。","重复所需的重复次数。"]},{"id":"1439","name":"lever gripless shrug v. 2","nameZh":"杠杆机无握耸肩版本 2","equipment":"leverage machine","bodyPart":"back","target":"traps","imagePath":"exercises/images/1439-cbuFJrn.jpg","gifPath":"exercises/videos/1439-cbuFJrn.gif","instructionSteps":["调整座椅高度并将自己放在机器上，背部靠在垫子上。","正手握住手柄或杆，保持手臂伸直。","保持背部挺直，将肩膀尽可能高地抬向耳朵。","保持收缩一会儿，然后慢慢将肩膀放回起始位置。","重复所需的重复次数。"]},{"id":"1441","name":"dumbbell over bench one arm reverse wrist curl","nameZh":"哑铃过凳单臂反手腕弯举","equipment":"dumbbell","bodyPart":"lower arms","target":"forearms","imagePath":"exercises/images/1441-4Jc36XM.jpg","gifPath":"exercises/videos/1441-4Jc36XM.gif","instructionSteps":["坐在长凳上，双脚平放在地上，一手握住哑铃，掌心朝下。","将前臂放在长凳上，手腕悬在长凳边缘。","慢慢向上弯曲手腕，将哑铃拉向前臂。","在顶部停顿片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数，然后换到另一只手臂。"]}];
